window.QDATA = {"chapters":{"1":{"title":"Introduction","deck":"introduction.pptx","slides":16},"2":{"title":"Project Management","deck":"project management.pptx","slides":33},"3":{"title":"Quality Management","deck":"quality mangment.pptx","slides":32},"4":{"title":"Source Code Quality","deck":"Source code Quality.pptx","slides":36},"5":{"title":"Object-Oriented Analysis & Design","deck":"object-Oriented sowfware analysis and design.pptx","slides":27},"6":{"title":"Security Engineering","deck":"security engineering.pptx","slides":44},"7":{"title":"Dependability & Reliability","deck":"Dependability and reliability.pptx","slides":33},"8":{"title":"Software Testing","deck":null},"9":{"title":"Software Evolution & Configuration Management","deck":null},"10":{"title":"Other Topics (Formal Verification, TDD, Patterns)","deck":null}},"sources":{"F26a":{"id":"F26a","label":"Final — 1st Semester 2026","file":"Exams/Final/2026/Final_1st_2026.pdf"},"M26b":{"id":"M26b","label":"Midterm — 2nd Semester 2026","file":"Exams/Midterm/2026/Midterm/SWE2_Midterm_2nd.pdf"},"F25b":{"id":"F25b","label":"Final — 2nd Semester 2025","file":"Exams/Final/2025/Final_2nd_2025.pdf  +  solved copy: Exams/Final/2025/Final_2nd_2025_sol.pdf"},"M25b":{"id":"M25b","label":"Midterm — 2nd Semester 2025","file":"Exams/Midterm/2025/Midterm_2nd_2025.pdf"},"F25x":{"id":"F25x","label":"Extra question bundled with the solved Final 2025 (2nd semester)","file":"Exams/Final/2025/Final_2nd_2025_sol.pdf"},"M25a":{"id":"M25a","label":"Midterm — 1st Semester 2025","file":"Exams/Midterm/2025/Midterm_1st_2025.pdf"},"F24c":{"id":"F24c","label":"Final — 3rd Semester 2024","file":"Exams/Final/2024/final_3nd_2024.pdf"},"M24c":{"id":"M24c","label":"Midterm — 3rd Semester 2024","file":"Exams/Midterm/2024/Midterm-3rd-2024.pdf"},"F24b":{"id":"F24b","label":"Final — 2nd Semester 2024","file":"Exams/Final/2024/Final_2nd_2024.pdf"},"M24b":{"id":"M24b","label":"Midterm — 2nd Semester 2024","file":"Exams/Midterm/2024/Midterm2-2nd-2024.pdf"},"F24a":{"id":"F24a","label":"Final — 1st Semester 2024","file":"Exams/Final/2024/Final_1st_2024.pdf  +  solved copy: Exams/Final/2024/فاينل الترم الاول Renad-2024.pdf"},"M24a":{"id":"M24a","label":"Midterm — 1st Semester 2024","file":"Exams/Midterm/2024/Midterm-1st-2024.pdf"},"F23c":{"id":"F23c","label":"Final — 3rd Semester 2023","file":"Exams/Final/2023/Final_3rd_2023.pdf"},"F23b":{"id":"F23b","label":"Final — 2nd Semester 2023","file":"Exams/Final/2023/Final_2nd_CS392_2023.pdf  (also pages 1–6 of Exams/Final/2023/_Final_2nd_CS392_2023.pdf)"},"F23a":{"id":"F23a","label":"Final — 1st Semester 1445 (Fall 2023), official model answer","file":"Exams/Final/2024/FinalExam_MA.docx  (student notes on the same exam: Exams/Final/2023/FINAL-1st-2023.pdf)"},"M22b1":{"id":"M22b1","label":"Midterm 1 — 2nd Semester 2022","file":"Exams/Midterm/2022/CS 392 - 2022 - mid 1 - second semester.pdf"},"M22a":{"id":"M22a","label":"Midterm — 1st Semester 1444 (Oct 2022), official model answer","file":"Exams/Midterm/2022/CS 392 Mid 1 2022 MA.docx"},"M22b2":{"id":"M22b2","label":"Midterm 2 — 2nd Semester 2022","file":"Exams/Midterm/2022/CS 392 Mid 2 2022 - second semester.pdf  (same Q1 as page 14 of Exams/Final/2023/_Final_2nd_CS392_2023.pdf)"},"Q22a":{"id":"Q22a","label":"Online Quiz A — 2022","file":"Exams/Quiz/2022/Online Quiz/Image_1–5 2022-11-29.png"},"Q22b":{"id":"Q22b","label":"Online Quiz B — 2022","file":"Exams/Quiz/2022/Online Quiz/Image_6–9 2022-11-29.png"},"Q21":{"id":"Q21","label":"Quizzes 1–3 & 6 — 1st Semester 1443 (2021)","file":"Exams/Quiz/2021/Quizes 1-4/*.pdf, Quizzes1-4-2021.zip, Q6.37x.docx"},"F21a":{"id":"F21a","label":"Final — 1st Semester 1443 (Dec 2021), official model answer","file":"Exams/Final/2021/Final2021_ModelAnswer.pdf  (also pages 7–13 of Exams/Final/2023/_Final_2nd_CS392_2023.pdf)"},"M21a":{"id":"M21a","label":"Midterm 1 — 1st Semester 1443 (Oct 2021), official model answer","file":"Exams/Midterm/2021/Midterm1_Answers.pdf"},"M21b":{"id":"M21b","label":"Midterm 1 (re-sit) — 1st Semester 1443 (Dec 2021), official model answer","file":"Exams/Midterm/2021/Midterm1_2021_Answers.pdf"},"M21c":{"id":"M21c","label":"Midterm 2 — 1st Semester 1443 (2021), official model answer","file":"Exams/Midterm/2021/Midterm2_2021_Answers.pdf  (student copy: Exams/Midterm/2021/Midterm2_2021.pdf)"}},"questions":[{"id":"M26b-1-1","ch":1,"sl":"9","tp":"Maintenance types","t":"mcq","q":"What type of maintenance involves fixing uncovered defects?","o":["Adaptive","Perfective","Corrective","Preventive"],"a":2,"e":"Slide 9: \"Corrective — fix uncovered defect; Adaptive — platform change; Enhancement — perfective, additional functionality; Preventive — re-engineering, make system more maintainable.\"","from":[{"s":"M26b","qn":"Q1.1","pg":1}]},{"id":"M26b-1-2","ch":1,"sl":"11","tp":"Iterative model","t":"mcq","q":"Which process model is described as \"develop increasingly more complex versions of the software\"?","o":["Waterfall","Prototyping","Iterative model","Spiral model"],"a":2,"e":"Slide 11 (Software evolution): \"<b>Iterative model</b> — Develop increasingly more complex versions of the software.\"","from":[{"s":"M26b","qn":"Q1.2","pg":1}]},{"id":"M26b-1-3","ch":1,"sl":"12","tp":"Evolutionary process models","t":"mcq","q":"Which of the following is categorized as an \"Evolutionary Process Model\"?","o":["Waterfall","Spiral Model","Prototyping Model","Rapid Application Development"],"a":1,"e":"Slide 12: Evolutionary process models = Incremental, <b>Spiral</b>, Component Assembly, Concurrent Development. Waterfall, Prototyping and RAD are listed as <i>classical</i> process models.","from":[{"s":"M26b","qn":"Q1.3","pg":1}]},{"id":"M26b-1-7","ch":1,"sl":"15","tp":"Quality = fitness for use","t":"mcq","q":"According to the quality perspective, software quality is defined as:","o":["Zero defects","Fitness for use","Maximum performance","Lowest cost"],"a":1,"e":"Introduction slide 15: \"Quality == '<b>fitness for use</b>'\".","from":[{"s":"M26b","qn":"Q1.7","pg":1}]},{"id":"M25a-1-1","ch":1,"sl":"12","tp":"Evolutionary process models","t":"mcq","q":"__________ is considered as an Evolutionary Process Model.","o":["Waterfall Model","Prototyping Model","Incremental Model","Rapid Application Development"],"a":2,"e":"Intro slide 12: Evolutionary process models = <b>Incremental</b>, Spiral, Component Assembly, Concurrent Development. Waterfall, Prototyping and RAD are classical process models.","from":[{"s":"M25b","qn":"Q1.1","pg":1},{"s":"M25a","qn":"Q1.1","pg":1}]},{"id":"M25a-1-2","ch":1,"sl":"9","tp":"Maintenance types","t":"mcq","q":"Which type of software maintenance focuses on fixing defects that have been discovered after the software has been released?","o":["Corrective maintenance","Adaptive maintenance","Preventive maintenance","Enhancement maintenance"],"a":0,"e":"Intro slide 9: \"<b>Corrective</b> — fix uncovered defect.\" Adaptive = platform change, enhancement = perfective/additional functionality, preventive = re-engineering.","from":[{"s":"M25a","qn":"Q1.2","pg":1}]},{"id":"M24c-1-1","ch":1,"sl":"15","tp":"SQA focus","t":"mcq","q":"SQA (Software Quality Assurance) focuses on:","o":["Ensuring the software meets specific functional requirements","Evaluating the software's usability and user experience","Ensuring that quality standards and processes are followed","Managing the software development team and project timelines"],"a":2,"e":"Intro slide 15: \"Quality Assurance: <b>processes/standards</b> to produce product and to improve quality over time.\" Quality slide 4: QM checks deliverables are consistent with organizational standards.","from":[{"s":"M24c","qn":"Q1.1","pg":8}]},{"id":"M24b-1-2","ch":1,"sl":"5","tp":"Problems with software production","t":"mcq","q":"One of the problems in software production is:","o":["Software is very hard to visualize","Software wears out very quickly","Software is manufactured","Software is not scalable"],"a":0,"e":"Intro slide 5: problems are complexity, conformity, changeability and \"<b>Invisibility</b> — software is very hard to visualize\".","from":[{"s":"M24b","qn":"Q1.2","pg":1}]},{"id":"F23a-1-5","ch":1,"sl":"9","tp":"Preventive maintenance","t":"mcq","q":"What is the primary goal of \"Preventive Maintenance\" in software evolution?","o":["Fixing defects and issues","Enhancing software functionality","Identifying and addressing potential issues before they cause problems","Rewriting the entire software application"],"a":2,"e":"Intro slide 9: \"Preventive — re-engineering, make system more maintainable\" — i.e. improving the system <i>before</i> problems happen. Fixing defects is corrective; enhancing functionality is perfective. Official key: c.","from":[{"s":"F23a","qn":"Q1.5"}]},{"id":"Q22a-2","ch":1,"sl":"8","tp":"TDD and agile","t":"mcq","q":"The ______ method embraces Test Driven Development.","o":["Spiral","P&amp;D","Agile","Waterfall"],"a":2,"e":"TDD comes from <b>agile</b> methods (Extreme Programming): short cycles of test → code → refactor. Intro slide 8 names Agile as the process layer; plan-and-document (P&amp;D) methods such as waterfall test after implementation.","from":[{"s":"Q22a","qn":"Q2"}]},{"id":"Q21-1c","ch":1,"sl":"15","tp":"Who verifies corrections?","t":"mcq","q":"Who identifies, documents, and verifies that corrections have been made to the software?","o":["Project manager","Project team","Software Quality Assurance group","Testing team"],"a":2,"e":"Intro slide 15: the <b>Software QA</b> department improves the organization's quality processes and checks them. Quiz 1 model answer: SQA group.","from":[{"s":"Q21","qn":"Quiz 1 (sec 372) Q2b"}]},{"id":"Q21-2e","ch":1,"sl":"10","tp":"Cost of changes","t":"tf","q":"Changes before software deployment and release are more expensive than changes after software deployment and release.","a":1,"e":"It is the opposite — the relative cost of correcting defects grows the later they are found (Intro slide 10, Pressman). Source Code Quality slide 7: once in production it is harder to apply fixes.","from":[{"s":"Q21","qn":"Quiz 2 (sec 372) Q1b"}]},{"id":"M26b-1-4","ch":2,"sl":"17","tp":"Risk planning strategies","t":"mcq","q":"Which risk management strategy aims to reduce the probability that a risk will arise?","o":["Avoidance strategies","Minimization strategies","Contingency plans","Acceptance strategies"],"a":0,"e":"Slide 17: \"<b>Avoidance strategies</b> — the probability that the risk will arise is reduced; Minimisation strategies — the impact of the risk is reduced; Contingency plans — plans to deal with the risk if it arises.\"","from":[{"s":"M26b","qn":"Q1.4","pg":1}]},{"id":"M26b-1-5","ch":2,"sl":"27","tp":"Personality types","t":"mcq","q":"A personality type motivated primarily by the work itself is referred to as:","o":["Self-oriented","Interaction-oriented","Goal-oriented","Task-oriented"],"a":3,"e":"Slide 27: \"<b>Task-oriented</b> — the motivation for doing the work is the work itself.\" Self-oriented = work is a means to personal goals; interaction-oriented = motivated by co-workers.","from":[{"s":"M26b","qn":"Q1.5","pg":1},{"s":"M24a","qn":"Q1.5","pg":1},{"s":"F21a","qn":"Q1.6","pg":2}]},{"id":"M26b-1-6","ch":2,"sl":"30","tp":"Group cohesiveness","t":"mcq","q":"What is a key advantage of a \"cohesive\" group in teamwork?","o":["Knowledge is shared among members","The group is more expensive to maintain","Members work independently of group goals","It requires a strictly hierarchical structure"],"a":0,"e":"Slide 30 (advantages of a cohesive group): group quality standards, team members learn from each other, <b>knowledge is shared</b> (continuity if a member leaves), refactoring and continual improvement are encouraged.","from":[{"s":"M26b","qn":"Q1.6","pg":1}]},{"id":"M26b-1-8","ch":2,"sl":"23","tp":"People management factors","t":"mcq","q":"Which people management factor states that all team members should be treated in a comparable way without favorites or discrimination?","o":["Respect","Inclusion","Consistency","Honesty"],"a":2,"e":"Slide 23: \"<b>Consistency</b> — team members should all be treated in a comparable way without favourites or discrimination.\"","from":[{"s":"M26b","qn":"Q1.8","pg":2}]},{"id":"M26b-1-9","ch":2,"sl":"10","tp":"Risk management process order","t":"mcq","q":"What is the correct order of the risk management process?","o":["Planning → Identification → Monitoring → Analysis","Identification → Analysis → Planning → Monitoring","Analysis → Identification → Planning → Monitoring","Identification → Planning → Analysis → Monitoring"],"a":1,"e":"Slide 10: 1- Risk identification, 2- Risk analysis, 3- Risk planning, 4- Risk monitoring.","from":[{"s":"M26b","qn":"Q1.9","pg":2}]},{"id":"M26b-1-10","ch":2,"sl":"8","tp":"Risk categories","t":"mcq","q":"A risk that affects the quality or performance of the software is called a:","o":["Project risk","Product risk","Business risk","Technical risk"],"a":1,"e":"Slide 8: project risks affect schedule or resources; <b>product risks affect the quality or performance</b> of the software; business risks affect the organisation.","from":[{"s":"M26b","qn":"Q1.10","pg":2}]},{"id":"F25b-1-1","ch":2,"sl":"10","tp":"Project & quality management T/F","t":"tf","q":"In the risk management process, risk identification is concerned with assessing the likelihood and consequences of these risks.","a":1,"e":"Slide 10: that is <b>risk analysis</b> (\"Assess the likelihood and consequences of these risks\"). Risk identification only identifies project, product and business risks.","from":[{"s":"F25b","qn":"Q1.1","pg":1}]},{"id":"F25b-1-2","ch":2,"sl":"3","tp":"Project & quality management T/F","t":"tf","q":"Project management is needed because software development is always subject to budget and schedule constraints.","a":0,"e":"Slide 3: \"Project management is needed because software development is always subject to budget and schedule constraints that are set by the organisation.\"","from":[{"s":"F25b","qn":"Q1.2","pg":1}]},{"id":"F25b-1-7","ch":2,"sl":"17","tp":"Project & quality management T/F","t":"tf","q":"In risk planning, avoidance strategies mean the probability that the risk will arise is reduced.","a":0,"e":"Slide 17: \"Avoidance strategies — the probability that the risk will arise is reduced.\"","from":[{"s":"F25b","qn":"Q1.7","pg":1}]},{"id":"F25b-1-8","ch":2,"sl":"24","tp":"Project & quality management T/F","t":"tf","q":"An important role of a manager is to motivate the people working on a project.","a":0,"e":"Slide 24: \"An important role of a manager is to motivate the people working on a project.\"","from":[{"s":"F25b","qn":"Q1.8","pg":1}]},{"id":"M25b-1-3","ch":2,"sl":"27","tp":"Personality types","t":"mcq","q":"In a project team, which personality type is the one where work is a means to an end, which is the achievement of individual goals?","o":["Task-oriented","Self-oriented","Interaction-oriented","Team-oriented"],"a":1,"e":"PM slide 27: \"<b>Self-oriented</b> — the work is a means to an end which is the achievement of individual goals, e.g. to get rich, to play tennis, to travel.\"","from":[{"s":"M25b","qn":"Q1.3","pg":1}]},{"id":"M25b-1-5","ch":2,"sl":"13","tp":"Risk types","t":"mcq","q":"It is considered as __________ when it is difficult to recruit staff with the skills required.","o":["Technology risks","Organisational risks","Requirements risks","People risks"],"a":3,"e":"PM slide 13: <b>People</b> risks — \"It is impossible to recruit staff with the skills required\", key staff are ill, required training not available.","from":[{"s":"M25b","qn":"Q1.5","pg":1}]},{"id":"M25b-1-6","ch":2,"sl":"12","tp":"Risk identification checklist","t":"mcq","q":"Which is <b>not</b> a common risk type used to identify project risk?","o":["Technology risks","Adaptive risks","Requirements risks","Estimation risks"],"a":1,"e":"PM slide 12: the checklist of common risks is technology, people, organisational, requirements and estimation risks (slide 13 adds tools). There is no 'adaptive' risk type.","from":[{"s":"M25b","qn":"Q1.6","pg":1}]},{"id":"M25b-1-7","ch":2,"sl":"18","tp":"Strategy for financial problems","t":"mcq","q":"What should a manager do when organizational financial problems appear?","o":["Alert customer to potential difficulties and the possibility of delays","Reorganize team so that there is more overlap of work and people","Replace potentially defective components with bought-in components of known reliability","Prepare a briefing document for senior management showing how the project is making a very important contribution to the goals of the business and presenting reasons why cuts to the project budget would not be cost-effective"],"a":3,"e":"PM slide 18: Organizational financial problems → prepare a briefing document for senior management. (A = recruitment problems, B = staff illness, C = defective components.)","from":[{"s":"M25b","qn":"Q1.7","pg":1}]},{"id":"M25b-1-8","ch":2,"sl":"17","tp":"Minimisation strategy","t":"mcq","q":"Which of the following is a risk minimization strategy?","o":["Ignoring the risk until it happens","Increasing the project scope","Reducing the effect of the risk on the product","Changing the project team members"],"a":2,"e":"PM slide 17: \"<b>Minimisation strategies</b> — the impact of the risk on the project or product will be reduced.\"","from":[{"s":"M25b","qn":"Q1.8","pg":1},{"s":"M24a","qn":"Q1.9","pg":2}]},{"id":"M25b-1-9","ch":2,"sl":"21","tp":"Risk indicators","t":"mcq","q":"What is a common indicator of organizational risks in a project?","o":["Poor relationships among team members","Lack of action by senior management","Inefficient database performance","Inability to recruit skilled staff"],"a":1,"e":"PM slide 21 (risk indicators): Organizational — \"organizational gossip; <b>lack of action by senior management</b>\". Poor relationships is a <i>people</i> indicator.","from":[{"s":"M25b","qn":"Q1.9","pg":2},{"s":"M24a","qn":"Q1.8","pg":2}]},{"id":"M25a-1-4","ch":2,"sl":"10, 17","tp":"Risk planning","t":"mcq","q":"Which stage of risk management involves developing a strategy to minimize risk effects?","o":["Risk analysis","Risk identification","Risk planning","Risk monitoring"],"a":2,"e":"PM slide 10: \"<b>Risk planning</b> — draw up plans to avoid or minimise the effects of the risk.\" Slide 17: consider each risk and develop a strategy to manage it.","from":[{"s":"M25b","qn":"Q1.2","pg":1},{"s":"M25a","qn":"Q1.4","pg":1},{"s":"M24a","qn":"Q1.3","pg":1}]},{"id":"M25a-1-10","ch":2,"sl":"23","tp":"People management factors","t":"mcq","q":"Which people management factor involves treating the team members in a comparable way without favourites?","o":["Consistency","Respect","Inclusion","Honesty"],"a":0,"e":"PM slide 23: \"<b>Consistency</b> — team members should all be treated in a comparable way without favourites or discrimination.\"","from":[{"s":"M25b","qn":"Q1.10","pg":2},{"s":"M25a","qn":"Q1.10","pg":2}]},{"id":"M25a-1-3","ch":2,"sl":"6","tp":"Management activities","t":"mcq","q":"Which management activity involves estimating, scheduling project development, and assigning people to tasks?","o":["Project planning","Reporting","Risk management","People management"],"a":0,"e":"PM slide 6: \"<b>Project planning</b> — project managers are responsible for planning, estimating and scheduling project development and assigning people to tasks.\"","from":[{"s":"M25a","qn":"Q1.3","pg":1}]},{"id":"M25a-1-5","ch":2,"sl":"8","tp":"Definition of risk","t":"mcq","q":"What best defines a <u>risk</u> in the context of risk management in software development?","o":["A confirmed issue that must be resolved in the project","A known defect in the software design or code","A probability that some adverse circumstance will occur","An unexpected change in project requirements"],"a":2,"e":"PM slide 8: \"A risk is a <b>probability that some adverse circumstance will occur</b>.\"","from":[{"s":"M25a","qn":"Q1.5","pg":1}]},{"id":"M25a-1-6","ch":2,"sl":"18","tp":"Strategy for staff illness","t":"mcq","q":"As part of risk management, what should a manager do when a team member becomes ill and is unable to continue working on the project?","o":["Alert the customer to potential delays in delivery","Reorganize the team so that there is more overlap of work and people","Reduce the project requirements to fit the smaller team","Request additional funding to hire a backup resource"],"a":1,"e":"PM slide 18 (strategies): \"<b>Staff illness</b> — Reorganize team so that there is more overlap of work and people therefore understand each other's jobs.\" (Option A is the strategy for recruitment problems.)","from":[{"s":"M25a","qn":"Q1.6","pg":1}]},{"id":"M25a-1-8","ch":2,"sl":"26","tp":"Self-realization needs","t":"mcq","q":"How can managers support self-realization needs in software teams?","o":["Offer health insurance","Offer appropriate rewards","Offer social networking","Offer training to learn"],"a":3,"e":"PM slide 26 (need satisfaction): Social — communal facilities, informal communication; Esteem — recognition, appropriate rewards; <b>Self-realization — training (people want to learn more), responsibility</b>.","from":[{"s":"M25a","qn":"Q1.8","pg":2}]},{"id":"M24c-1-2","ch":2,"sl":"27","tp":"Interaction-oriented motivation","t":"mcq","q":"Which of the following scenarios best represents \"interaction-oriented\" motivation for work?","o":["Sarah enjoys her job as a software developer because she finds programming tasks intellectually stimulating and fulfilling.","Ali works as an accountant primarily to earn a high salary and achieve financial security.","Eman works as a customer service representative because she enjoys interacting with customers and helping them solve problems.","Mahmoud works as a chef because he is passionate about cooking and wants to create delicious dishes."],"a":2,"e":"PM slide 27: \"<b>Interaction-oriented</b> — the principal motivation is the presence and actions of co-workers.\" Sarah and Mahmoud are task-oriented (the work itself); Ali is self-oriented (personal goals).","from":[{"s":"M24c","qn":"Q1.2","pg":8}]},{"id":"M24c-1-10","ch":2,"sl":"13","tp":"People risks","t":"mcq","q":"When staff are ill and unavailable at critical times in a project, the type of risk here is:","o":["Technology risk","People risk","Estimation risk","Tools risk"],"a":1,"e":"PM slide 13: <b>People</b> — \"Key staff are ill and unavailable at critical times.\"","from":[{"s":"M24c","qn":"Q1.10","pg":1}]},{"id":"M24c-2","ch":2,"sl":"10–21","tp":"Risk process for a game launch","t":"short","q":"A software development company is planning to launch a new mobile application in the competitive gaming industry. They want to ensure a successful launch while effectively managing potential risks. They recognize that the gaming market is highly competitive and subject to rapid technological advancements. The company has conducted market research, analysed the competitive landscape, developed a marketing strategy, and established a feedback collection mechanism. They plan to closely track user engagement metrics, app reviews and ratings, stay updated on industry trends and analyse competitor activities.<br>1) <b>Risk identification:</b> identify and explain one potential risk.<br>2) <b>Risk analysis:</b> assess its likelihood and consequences.<br>3) <b>Risk planning:</b> propose one strategy to mitigate it.<br>4) <b>Risk monitoring:</b> describe how the company plans to monitor the app's performance and user reception.","a":"1) <b>Product competition</b> (business risk): a competitor releases a similar or better game before or during the launch and takes the target audience. <i>(Also acceptable: technology change — new technology makes the app outdated.)</i><br>2) <b>Probability: high</b> (the market is \"highly competitive\" with rapid advances). <b>Effects: serious</b> — fewer downloads and revenue, the launch may fail.<br>3) <b>Minimisation strategy:</b> differentiate the game with unique features, release an early/beta version quickly, and use the marketing strategy to build awareness; <b>contingency plan:</b> adjust pricing/features quickly based on feedback.<br>4) <b>Monitoring:</b> regularly track user engagement metrics, app reviews and ratings, and competitor activity and industry trends; discuss these indicators at management meetings to see if the risk is becoming more or less likely and adapt strategies.","e":"PM slide 10 (risk management process), slide 9 (product competition / technology change are business risks), slide 14 (probability and effects scales), slide 17 (avoidance, minimisation, contingency), slides 20–21 (risk monitoring and indicators).","from":[{"s":"M24c","qn":"Q2","pg":2}]},{"id":"M24b-1-1","ch":2,"sl":"8, 9","tp":"Business risk","t":"mcq","q":"Which of the following risks is the potential negative impact on the company's reputation and image due to company corruption rumors?","o":["Product risk","Project risk","Business risk","Programming risk"],"a":2,"e":"PM slide 8: \"<b>Business risks</b> affect the organisation developing or procuring the software.\" Reputation damage hits the organisation, not the schedule (project) or the software quality (product).","from":[{"s":"M24b","qn":"Q1.1","pg":1}]},{"id":"M24b-1-3","ch":2,"sl":"25, 26","tp":"Human needs hierarchy","t":"mcq","q":"Recognition of achievements is considered a(n) ______ need according to Maslow's human hierarchy of needs.","o":["Physiological","Esteem","Social","Self-realization"],"a":1,"e":"PM slide 26 (need satisfaction): \"<b>Esteem</b> — recognition of achievements; appropriate rewards.\" Self-realization = training and responsibility.","from":[{"s":"M24b","qn":"Q1.3","pg":1}]},{"id":"M24b-2-1","ch":2,"sl":"9","tp":"Match risk to risk type","t":"mcq","q":"Choose the most appropriate risk type for this possible risk (each type is used once in the exam):<br>There is a sudden shift in consumer preferences towards a new social media app.","o":["Hardware unavailability","Technology change","Size underestimation","Product competition","Management change"],"a":3,"e":"Slide 9: \"Product competition (business) — a competitive product is marketed before the system is completed\"; consumers moving to a competing app is a competition risk.","from":[{"s":"M24b","qn":"Q2.1","pg":2}]},{"id":"M24b-2-2","ch":2,"sl":"9","tp":"Match risk to risk type","t":"mcq","q":"Choose the most appropriate risk type for this possible risk (each type is used once in the exam):<br>The company decides to adopt a new software development methodology for all its projects.","o":["Hardware unavailability","Technology change","Size underestimation","Product competition","Management change"],"a":1,"e":"Slide 9: \"Technology change (business) — the underlying technology on which the system is built is superseded by new technology.\" A new development methodology replaces the existing way of working.","from":[{"s":"M24b","qn":"Q2.2","pg":2}]},{"id":"M24b-2-3","ch":2,"sl":"9","tp":"Match risk to risk type","t":"mcq","q":"Choose the most appropriate risk type for this possible risk (each type is used once in the exam):<br>There is a change in the executive team, resulting in a new strategic direction for the organization.","o":["Hardware unavailability","Technology change","Size underestimation","Product competition","Management change"],"a":4,"e":"Slide 9: \"Management change (project) — there will be a change of organizational management with different priorities.\"","from":[{"s":"M24b","qn":"Q2.3","pg":2}]},{"id":"M24b-2-4","ch":2,"sl":"9","tp":"Match risk to risk type","t":"mcq","q":"Choose the most appropriate risk type for this possible risk (each type is used once in the exam):<br>The staff used an algorithm and estimated that it would take two weeks to complete; however, as they delved deeper into the technical details, they realized that the algorithm involved intricate calculations. As a result, the implementation took three months.","o":["Hardware unavailability","Technology change","Size underestimation","Product competition","Management change"],"a":2,"e":"Slide 9: \"Size underestimate (project and product) — the size of the system has been underestimated\" (2 weeks became 3 months).","from":[{"s":"M24b","qn":"Q2.4","pg":2}]},{"id":"M24b-2-5","ch":2,"sl":"9","tp":"Match risk to risk type","t":"mcq","q":"Choose the most appropriate risk type for this possible risk (each type is used once in the exam):<br>Due to Covid-19-related disruptions, the staff faced delays in receiving a critical chip for their system, leading to uncertainty on when they will receive it.","o":["Hardware unavailability","Technology change","Size underestimation","Product competition","Management change"],"a":0,"e":"Slide 9: \"Hardware unavailability (project) — hardware that is essential for the project will not be delivered on schedule.\"","from":[{"s":"M24b","qn":"Q2.5","pg":2}]},{"id":"F24a-1-1","ch":2,"sl":"3","tp":"Project management T/F","t":"tf","q":"Software project management is concerned with ensuring that software is delivered on time and on budget.","a":0,"e":"PM slide 3: project management is \"concerned with activities involved in ensuring that software is delivered on time and on schedule and in accordance with the requirements\"; slide 4 success criteria include keeping costs within budget.","from":[{"s":"F24a","qn":"Q1.1","pg":1}]},{"id":"F24a-1-2","ch":2,"sl":"6","tp":"Project management T/F","t":"tf","q":"Risk management involves assessing risks that may affect a project and taking action when problems arise.","a":0,"e":"PM slide 6: \"Project managers assess the risks that may affect a project, monitor these risks and take action when problems arise.\"","from":[{"s":"F24a","qn":"Q1.2","pg":1}]},{"id":"F24a-1-3","ch":2,"sl":"5","tp":"Project management T/F","t":"tf","q":"All software projects are similar, making it easy for experienced managers to anticipate problems.","a":1,"e":"PM slide 5: many software projects are 'one-off' projects — \"Even managers who have lots of previous experience may find it difficult to anticipate problems.\"","from":[{"s":"F24a","qn":"Q1.3","pg":1}]},{"id":"F24a-1-4","ch":2,"sl":"22","tp":"Project management T/F","t":"tf","q":"Poor people management can lead to project failure.","a":0,"e":"PM slide 22: \"Poor people management is an important contributor to project failure.\"","from":[{"s":"F24a","qn":"Q1.4","pg":1}]},{"id":"F24a-1-5","ch":2,"sl":"30","tp":"Project management T/F","t":"tf","q":"Group cohesiveness can lead to shared knowledge and continuity if a member leaves the team.","a":0,"e":"PM slide 30: \"Knowledge is shared. Continuity can be maintained if a group member leaves.\"","from":[{"s":"F24a","qn":"Q1.5","pg":1}]},{"id":"F24a-1-8","ch":2,"sl":"8","tp":"Project management T/F","t":"tf","q":"Product risks affect the quality or performance of the software being developed.","a":0,"e":"PM slide 8: \"Product risks affect the quality or performance of the software being developed.\"","from":[{"s":"F24a","qn":"Q1.8","pg":1}]},{"id":"M24a-1-1","ch":2,"sl":"3, 4","tp":"Project management concern","t":"mcq","q":"What is the primary concern of software project management?","o":["Hardware development","Ensuring software is delivered on time and within budget","Designing user interfaces","Testing software performance"],"a":1,"e":"PM slide 3: ensuring that software is delivered on time and on schedule; slide 4 success criteria: deliver at the agreed time and keep overall costs within budget.","from":[{"s":"M24a","qn":"Q1.1","pg":1}]},{"id":"M24a-1-2","ch":2,"sl":"5","tp":"Software management distinctions","t":"mcq","q":"Why is software project management different from traditional project management?","o":["Software is intangible and cannot be seen","Software is cheaper to produce","Software projects are always identical","Software is always developed by large teams"],"a":0,"e":"PM slide 5: \"The product is <b>intangible</b>. Software cannot be seen or touched. Software project managers cannot see progress by simply looking at the artefact.\"","from":[{"s":"M24a","qn":"Q1.2","pg":1}]},{"id":"M24a-1-4","ch":2,"sl":"18","tp":"Strategy for staff illness","t":"mcq","q":"What should a manager do when a staff member is ill at critical times?","o":["Ignore the problem","Increase project scope","Reorganize the team for overlapping tasks","Hire a consultant"],"a":2,"e":"PM slide 18: \"Staff illness — Reorganize team so that there is more overlap of work and people therefore understand each other's jobs.\"","from":[{"s":"M24a","qn":"Q1.4","pg":1}]},{"id":"M24a-1-7","ch":2,"sl":"21","tp":"Risk indicators","t":"mcq","q":"Which is a potential indicator of technology risk?","o":["Low staff morale","Organizational restructuring","Late hardware delivery","Customer complaints"],"a":2,"e":"PM slide 21: Technology indicators — \"<b>late delivery of hardware</b> or support software; many reported technology problems.\" Low morale = people; customer complaints = requirements.","from":[{"s":"M24a","qn":"Q1.7","pg":2}]},{"id":"M24a-1-10","ch":2,"sl":"29, 30","tp":"Team cohesiveness","t":"mcq","q":"Why is team cohesiveness important in software development?","o":["It allows individuals to focus solely on their personal goals","It improves group performance and encourages collective problem solving","It enables managers to control every detail of the project","It ensures tasks are distributed unevenly"],"a":1,"e":"PM slide 29: a good group is cohesive and has team spirit; group interaction is a key determinant of group performance. Slide 30: members work collectively to deliver high quality results and fix problems.","from":[{"s":"M24a","qn":"Q1.10","pg":2}]},{"id":"F21a-1-9","ch":2,"sl":"26","tp":"Self-realization needs","t":"mcq","q":"As a project manager, you notice that deep knowledge of the system is held by a very small number of team members. The remaining team members are frustrated that they do not understand the system very well. What type of human need (according to the human needs hierarchy) is not met for the majority of the team?","o":["Physiological needs","Social needs","Safety needs","Self-realization needs"],"a":3,"e":"PM slide 26: self-realization is satisfied by <b>training — people want to learn more</b> — and responsibility. The team can't learn/grow in the system. Official key: d.","from":[{"s":"F21a","qn":"Q1.9","pg":3}]},{"id":"F21a-1-10","ch":2,"sl":"13, 21","tp":"Potential risk","t":"mcq","q":"Same scenario (system knowledge held by a few people; the rest are frustrated). As a project manager, what potential risk do you find?","o":["Poor relationships amongst team members can lead to high staff turnover","It is impossible to recruit staff with the skills required","The size of the software is underestimated","There is no risk"],"a":0,"e":"PM slide 21: people-risk indicators are \"poor staff morale; poor relationships amongst team members; high staff turnover\"; slide 9: staff turnover — experienced staff leave before the project is finished. Official key: a.","from":[{"s":"F21a","qn":"Q1.10","pg":3}]},{"id":"M26b-2-1","ch":3,"sl":"4","tp":"Quality management T/F","t":"tf","q":"The quality team should be independent from the development team to take an objective view of the software.","a":0,"e":"Slide 4: \"The quality team should be independent from the development team so that they can take an objective view of the software.\"","from":[{"s":"M26b","qn":"Q2.1","pg":3}]},{"id":"M26b-2-2","ch":3,"sl":"7","tp":"Quality management T/F","t":"tf","q":"A quality plan should be long and detailed to cover all possible scenarios.","a":1,"e":"Slide 7: \"Quality plans should be <b>short, succinct</b> documents. If they are too long, no-one will read them.\"","from":[{"s":"M26b","qn":"Q2.2","pg":3}]},{"id":"M26b-2-3","ch":3,"sl":"12","tp":"Quality management T/F","t":"tf","q":"It is possible for a software system to be optimized for all quality attributes simultaneously (e.g., robustness and performance).","a":1,"e":"Slide 12: \"It is <b>not</b> possible for any system to be optimized for all of these attributes — for example, improving robustness may lead to loss of performance.\"","from":[{"s":"M26b","qn":"Q2.3","pg":3}]},{"id":"M26b-2-4","ch":3,"sl":"15","tp":"Quality management T/F","t":"tf","q":"Quality managers should aim to develop a 'quality culture' where everyone is committed to achieving high product quality.","a":0,"e":"Slide 15: quality managers should develop a 'quality culture' where everyone responsible for software development is committed to achieving a high level of product quality.","from":[{"s":"M26b","qn":"Q2.4","pg":3}]},{"id":"M26b-2-5","ch":3,"sl":"29","tp":"Quality management T/F","t":"tf","q":"Dynamic software metrics are collected by making measurements while a program is in execution.","a":0,"e":"Slide 29: \"Dynamic metrics which are collected by measurements made of a program <b>in execution</b>.\"","from":[{"s":"M26b","qn":"Q2.5","pg":3}]},{"id":"M26b-2-6","ch":3,"sl":"19, 20","tp":"Quality management T/F","t":"tf","q":"Pair programming ensures that code is constantly reviewed, but it can still lead to mutual misunderstandings of system requirements.","a":0,"e":"Slide 19: code is constantly examined and reviewed by another team member. Slide 20: weakness — mutual misunderstandings.","from":[{"s":"M26b","qn":"Q2.6","pg":3}]},{"id":"M26b-2-7","ch":3,"sl":"32","tp":"Quality management T/F","t":"tf","q":"A high \"Fog index\" indicates that a document is written in a way that is very simple and easy for most people to understand.","a":1,"e":"Slide 32: \"The <b>higher</b> the value of a document's Fog index, the <b>more difficult</b> the document is to understand.\"","from":[{"s":"M26b","qn":"Q2.7","pg":3}]},{"id":"M26b-2-8","ch":3,"sl":"20","tp":"Quality management T/F","t":"tf","q":"One weakness of pair programming is that both members may share the same misunderstanding of system requirements.","a":0,"e":"Slide 20: \"Mutual misunderstandings — both members of a pair may make the same mistake in understanding the system requirements.\"","from":[{"s":"M26b","qn":"Q2.8","pg":3}]},{"id":"M26b-2-9","ch":3,"sl":"30","tp":"Quality management T/F","t":"tf","q":"Static metrics, such as cyclomatic complexity, have a direct and easily measured relationship with quality attributes like maintainability.","a":1,"e":"Slide 30: \"Static metrics have an <b>indirect</b> relationship with quality attributes.\" It is dynamic metrics that are closely related to quality attributes.","from":[{"s":"M26b","qn":"Q2.9","pg":3}]},{"id":"M26b-2-10","ch":3,"sl":"31","tp":"Quality management T/F","t":"tf","q":"Generally, the larger the size of a code component, the more complex and error-prone it is likely to be.","a":0,"e":"Slide 31 (Length of code): \"Generally, the larger the size of the code of a component, the more complex and error-prone that component is likely to be.\"","from":[{"s":"M26b","qn":"Q2.10","pg":3}]},{"id":"F26a-1-1","ch":3,"sl":"16","tp":"Agile quality management","t":"mcq","q":"In agile development, how is quality management primarily approached?","o":["Through extensive documentation","Through formal audits and compliance checks","Informally, with team responsibility for quality","By outsourcing quality checks"],"a":2,"e":"Slide 16: \"Quality management in agile development is <b>informal</b> rather than document-based. It relies on establishing a quality culture, where all team members feel responsible for software quality.\"","from":[{"s":"F26a","qn":"Q1.1","pg":1}]},{"id":"F26a-1-2","ch":3,"sl":"11","tp":"Quality attributes","t":"mcq","q":"Which of the following is a software quality attribute related to how well the software can be modified?","o":["Adaptability","Efficiency","Usability","Portability"],"a":0,"e":"Slide 11 lists the quality attributes. <b>Adaptability</b> is how easily the software can be changed/adapted to new requirements. Efficiency is about resource use, usability about ease of use, and portability about moving the software to another platform.","from":[{"s":"F26a","qn":"Q1.2","pg":1}]},{"id":"F26a-1-3","ch":3,"sl":"32","tp":"Fog index","t":"mcq","q":"What does the \"Fog Index\" measure in software documentation?","o":["The number of spelling errors per page","The average length of words and sentences to determine readability","The amount of technical jargon used in a document","The visual layout and formatting of a manual"],"a":1,"e":"Slide 32: \"Fog index — a measure of the average length of words and sentences in documents. The higher the value of a document's Fog index, the more difficult the document is to understand.\"","from":[{"s":"F26a","qn":"Q1.3","pg":1}]},{"id":"F26a-1-4","ch":3,"sl":"20","tp":"Pair programming weaknesses","t":"mcq","q":"What is a weakness of pair programming?","o":["It always leads to faster development","Mutual misunderstandings where both may make the same mistake","It reduces knowledge sharing","It eliminates all bugs"],"a":1,"e":"Slide 20 (pair programming weaknesses): \"<b>Mutual misunderstandings</b> — both members of a pair may make the same mistake in understanding the system requirements.\" The other weaknesses are pair reputation and working relationships.","from":[{"s":"F26a","qn":"Q1.4","pg":1}]},{"id":"F26a-1-5","ch":3,"sl":"15, 16","tp":"Quality culture","t":"mcq","q":"What does a \"quality culture\" emphasize in software development?","o":["Strict adherence to deadlines only","Everyone taking responsibility for quality","Maximizing profits","Minimizing documentation"],"a":1,"e":"Slide 15: quality managers develop a 'quality culture' \"where everyone responsible for software development is committed to achieving a high level of product quality\". Slide 16: all team members feel responsible for software quality.","from":[{"s":"F26a","qn":"Q1.5","pg":1}]},{"id":"F25b-1-3","ch":3,"sl":"29","tp":"Project & quality management T/F","t":"tf","q":"Dynamic metrics help assess efficiency and reliability while static metrics are collected by measurements made of the system representations.","a":0,"e":"Slide 29: static metrics are collected from system representations; \"Dynamic metrics help assess efficiency and reliability.\"","from":[{"s":"F25b","qn":"Q1.3","pg":1}]},{"id":"F25b-1-4","ch":3,"sl":"16","tp":"Project & quality management T/F","t":"tf","q":"Quality management in agile development is informal rather than document-based.","a":0,"e":"Slide 16: \"Quality management in agile development is informal rather than document-based.\"","from":[{"s":"F25b","qn":"Q1.4","pg":1},{"s":"M25a","qn":"Q2.8","pg":2},{"s":"M24a","qn":"Q2.6","pg":3}]},{"id":"F25b-1-5","ch":3,"sl":"29, 32","tp":"Project & quality management T/F","t":"tf","q":"Cyclomatic complexity is an example of dynamic software product metrics.","a":1,"e":"Slide 32 lists cyclomatic complexity under <b>static</b> software product metrics (it is measured from the code, not from the running program).","from":[{"s":"F25b","qn":"Q1.5","pg":1}]},{"id":"F25b-2-2","ch":3,"sl":"3","tp":"Quality plan contents","t":"mcq","q":"What should a quality plan include?","o":["The company's marketing strategy","Quality goals for the project and the standards to be used","A list of competitors in the market","The software's user interface design"],"a":1,"e":"Quality slide 3: \"The quality plan should set out the quality goals for the project and define what processes and standards are to be used.\" Slide 7 lists the structure: product introduction, product plans, process descriptions, quality goals, risks.","from":[{"s":"F25b","qn":"Q2.2","pg":2}]},{"id":"F25b-2-5","ch":3,"sl":"8, 9","tp":"Fitness for purpose","t":"mcq","q":"What is the main focus of software 'fitness for purpose'?","o":["Conforming strictly to specification","Reducing project costs","Meeting the practical needs and expectations of users","Simplifying code structures"],"a":2,"e":"Quality slide 8: \"The focus may be 'fitness for purpose' <b>rather than specification conformance</b>.\" Slide 9 lists the questions: tested? dependable? acceptable performance? usable? — i.e. does it meet users' practical needs.","from":[{"s":"F25b","qn":"Q2.5","pg":2}]},{"id":"F25b-2-6","ch":3,"sl":"18, 19","tp":"Pair programming benefit","t":"mcq","q":"What is one of the key benefits of pair programming in agile development?","o":["It eliminates the need for testing","It ensures constant code review by another team member","It reduces the time needed for coding by 50%","It guarantees perfect code without errors"],"a":1,"e":"Quality slide 18: \"In Extreme Programming, pair programming ensures that code is constantly being examined and reviewed by another team member.\"","from":[{"s":"F25b","qn":"Q2.6","pg":2}]},{"id":"M25b-1-4","ch":3,"sl":"32","tp":"Fog index","t":"mcq","q":"__________ is a measure of the average length of words and sentences in documents.","o":["Length of identifiers","Fog index","Cyclomatic complexity","Fan-in"],"a":1,"e":"Quality slide 32: \"<b>Fog index</b> — a measure of the average length of words and sentences in documents.\"","from":[{"s":"M25b","qn":"Q1.4","pg":1}]},{"id":"M25b-2-1","ch":3,"sl":"3","tp":"Quality management T/F","t":"tf","q":"At the project level, quality management involves applying specific quality processes and checking that these planned processes are followed.","a":0,"e":"Slide 3: \"At the project level, quality management involves the application of specific quality processes and checking that these planned processes have been followed.\"","from":[{"s":"M25b","qn":"Q2.1","pg":3}]},{"id":"M25b-2-2","ch":3,"sl":"4","tp":"Quality management T/F","t":"tf","q":"The quality team should become independent of the development team so that they can take an objective view of the software.","a":0,"e":"Slide 4: the quality team should be independent so they can take an objective view of the software.","from":[{"s":"M25b","qn":"Q2.2","pg":3}]},{"id":"M25b-2-3","ch":3,"sl":"6","tp":"Quality management T/F","t":"tf","q":"A quality plan sets out the desired product qualities and how these are assessed, and there is no need to set up organizational standards.","a":1,"e":"Slide 6: the quality plan \"should set out <b>which organizational standards should be applied</b> and, where necessary, define new standards.\"","from":[{"s":"M25b","qn":"Q2.3","pg":3}]},{"id":"M25b-2-4","ch":3,"sl":"9","tp":"Quality management T/F","t":"tf","q":"A software is fit for purpose if it is properly tested, sufficiently dependable, and has acceptable performance for normal use.","a":0,"e":"Slide 9 (software fitness for purpose): properly tested? sufficiently dependable? acceptable performance for normal use? usable? well-structured?","from":[{"s":"M25b","qn":"Q2.4","pg":3}]},{"id":"M25b-2-5","ch":3,"sl":"13","tp":"Quality management T/F","t":"tf","q":"The quality of a developed product is completely separate from the quality of the production process.","a":1,"e":"Slide 13: \"The quality of a developed product is <b>influenced by</b> the quality of the production process.\"","from":[{"s":"M25b","qn":"Q2.5","pg":3}]},{"id":"M25b-2-6","ch":3,"sl":"","tp":"Quality management T/F","t":"tf","q":"One of the major problems with software standards is that they usually involve too much official form filling.","a":0,"e":"Not on your slides — Sommerville ch. 24 (problems with standards): standards \"often involve too much bureaucratic form filling\" and may not be seen as relevant by engineers.","from":[{"s":"M25b","qn":"Q2.6","pg":3},{"s":"M24a","qn":"Q2.5","pg":3}]},{"id":"M25b-2-7","ch":3,"sl":"","tp":"Quality management T/F","t":"tf","q":"Process standards apply to the software product being developed, including document standards and coding standards.","a":1,"e":"Those are <b>product standards</b> (document standards, coding standards). Process standards define the processes to be followed during development (Sommerville ch. 24 — not on your slides).","from":[{"s":"M25b","qn":"Q2.7","pg":3}]},{"id":"M25b-2-8","ch":3,"sl":"12","tp":"Quality management T/F","t":"tf","q":"It is possible for any system to be optimized for all of the quality attributes.","a":1,"e":"Slide 12: \"It is not possible for any system to be optimized for all of these attributes.\"","from":[{"s":"M25b","qn":"Q2.8","pg":3}]},{"id":"M25b-2-9","ch":3,"sl":"17","tp":"Quality management T/F","t":"tf","q":"'Never break the build' means team members should not check in code that causes the system to fail.","a":0,"e":"Slide 17: \"Never break the build — team members should not check in code that causes the system to fail.\"","from":[{"s":"M25b","qn":"Q2.9","pg":3}]},{"id":"M25b-2-10","ch":3,"sl":"20","tp":"Quality management T/F","t":"tf","q":"Pair reputation is considered a weakness since pairs may be reluctant to look for errors because they do not want to slow down the progress of the project.","a":0,"e":"Slide 20: \"Pair reputation — pairs may be reluctant to look for errors because they do not want to slow down the progress of the project.\"","from":[{"s":"M25b","qn":"Q2.10","pg":3}]},{"id":"M25a-1-7","ch":3,"sl":"4","tp":"Independent quality team","t":"mcq","q":"Why should the quality team be independent from the development team?","o":["To work faster than the development team","To take an objective view without being influenced by development issues","To share development resources and experiences","To focus on coding new software features"],"a":1,"e":"Quality slide 4: \"The quality team should be independent from the development team so that they can take an <b>objective view</b> of the software. This allows them to report on software quality without being influenced by software development issues.\"","from":[{"s":"M25a","qn":"Q1.7","pg":1}]},{"id":"M25a-1-9","ch":3,"sl":"29, 30","tp":"Measuring complexity","t":"mcq","q":"How can we measure properties such as complexity in software?","o":["By running the software and measuring response time","By reviewing the requirements document of the software","By measuring the speed of the system during execution","By using static metrics that analyze the software code"],"a":3,"e":"Quality slide 29: \"<b>Static metrics</b> help assess complexity, understandability and maintainability.\" Dynamic metrics (measured during execution) assess efficiency and reliability.","from":[{"s":"M25a","qn":"Q1.9","pg":2}]},{"id":"M25a-2-1","ch":3,"sl":"6","tp":"Quality management T/F","t":"tf","q":"A quality plan sets out the desired product qualities and how these are assessed.","a":0,"e":"Slide 6: \"A quality plan sets out the desired product qualities and how these are assessed and defines the most significant quality attributes.\"","from":[{"s":"M25a","qn":"Q2.1","pg":2}]},{"id":"M25a-2-2","ch":3,"sl":"12","tp":"Quality management T/F","t":"tf","q":"Improving one quality attribute, like robustness, may reduce another, such as performance.","a":0,"e":"Slide 12 (quality conflicts): \"improving robustness may lead to loss of performance.\"","from":[{"s":"M25a","qn":"Q2.2","pg":2}]},{"id":"M25a-2-3","ch":3,"sl":"7","tp":"Quality management T/F","t":"tf","q":"Quality plans should be long and detailed documents.","a":1,"e":"Slide 7: quality plans should be <b>short, succinct</b> documents — if they are too long, no-one will read them.","from":[{"s":"M25a","qn":"Q2.3","pg":2}]},{"id":"M25a-2-4","ch":3,"sl":"8","tp":"Quality management T/F","t":"tf","q":"Customer quality requirements are the same as developer quality requirements in software systems.","a":1,"e":"Slide 8: \"There is a <b>tension</b> between customer quality requirements (efficiency, reliability, etc.) and developer quality requirements (maintainability, reusability, etc.).\"","from":[{"s":"M25a","qn":"Q2.4","pg":2}]},{"id":"M25a-2-5","ch":3,"sl":"21","tp":"Quality management T/F","t":"tf","q":"When a large system is being developed, agile approaches to quality management may be impractical.","a":0,"e":"Slide 21: \"When a large system is being developed for an external customer, agile approaches to quality management with minimal documentation may be impractical.\"","from":[{"s":"M25a","qn":"Q2.5","pg":2}]},{"id":"M25a-2-6","ch":3,"sl":"10","tp":"Quality management T/F","t":"tf","q":"If the software's functionality is not what is expected, then users will work around this and find other ways to do what they want to do.","a":0,"e":"Slide 10: \"if the software's functionality is not what is expected, then users will often just work around this and find other ways to do what they want to do.\"","from":[{"s":"M25a","qn":"Q2.6","pg":2}]},{"id":"M25a-2-7","ch":3,"sl":"22","tp":"Quality management T/F","t":"tf","q":"Software measurement is concerned with deriving a numeric value for an attribute of a software.","a":0,"e":"Slide 22: \"Software measurement is concerned with deriving a numeric value for an attribute of a software product or process.\"","from":[{"s":"M25a","qn":"Q2.7","pg":2}]},{"id":"M25a-2-9","ch":3,"sl":"25","tp":"Quality management T/F","t":"tf","q":"One of the uses of software measurements is to identify the system time and budget.","a":1,"e":"Slide 25 gives the two uses of measurement: to <b>assign a value to system quality attributes</b> and to <b>identify system components whose quality is sub-standard</b>. Time and budget are not mentioned.","from":[{"s":"M25a","qn":"Q2.9","pg":2}]},{"id":"M25a-2-10","ch":3,"sl":"31, 32","tp":"Quality management T/F","t":"tf","q":"Length of code is a measure of the average length of words and sentences in documents.","a":1,"e":"That is the <b>Fog index</b> (slide 32). Length of code (slide 31) measures the size of a program.","from":[{"s":"M25a","qn":"Q2.10","pg":2}]},{"id":"M24c-1-5","ch":3,"sl":"16","tp":"ISO 9001","t":"mcq","q":"ISO 9001 certification for software quality indicates that:","o":["The software is completely free of defects or bugs","The software meets specific industry functional requirements","The software meets specific industry functional and non-functional requirements","The organization has established and follows a robust quality management system"],"a":3,"e":"ISO 9001 is a standard for <b>quality management processes</b> (Quality slide 16 mentions \"quality processes as embodied in ISO 9001\"). It certifies the organization's process, not that a product is defect-free.","from":[{"s":"M24c","qn":"Q1.5","pg":1}]},{"id":"M24c-1-8","ch":3,"sl":"30","tp":"Dynamic metrics","t":"mcq","q":"Dynamic metrics are closely related to software quality attributes such as:","o":["Code coverage","Lines of code","Length of user manual","Response time"],"a":3,"e":"Quality slide 30: \"It is relatively easy to measure the <b>response time</b> of a system (performance attribute) or the number of failures (reliability attribute).\"","from":[{"s":"M24c","qn":"Q1.8","pg":1}]},{"id":"M24c-1-9","ch":3,"sl":"3, 4","tp":"Quality management responsibilities","t":"mcq","q":"Quality management is responsible for:","o":["Independent check on the software development process","Checking the project deliverables to ensure that they are consistent with organizational standards and goals","Establishing a quality plan for a project","All of the above"],"a":3,"e":"Quality slide 4: independent check; checks deliverables against organizational standards and goals. Slide 3: establishing a quality plan for a project. All three are listed.","from":[{"s":"M24c","qn":"Q1.9","pg":1}]},{"id":"M24c-3","ch":3,"sl":"11","tp":"Quality attributes fill-in","t":"short","q":"Fill the blank with the most appropriate term (no duplication).<br><b>Terms:</b> Understandability · Complexity · Robustness · Resilience · Usability · Reusability · Portability · Modularity · Maintainability · Learnability · Adaptability<ol><li>______ is a characteristic attributed to a computer program if it can run with minimal rework on operating systems other than the one for which it was created.</li><li>______ is a measure of the depth and quantity of routines in a piece of code.</li><li>______ refers to an organizing structure in which different components of a software system are divided into separate functional units.</li><li>______ refers to how effectively users can interact with a software product.</li></ol>","a":"<ol><li><b>Portability</b></li><li><b>Complexity</b></li><li><b>Modularity</b></li><li><b>Usability</b></li></ol>","e":"All four are software quality attributes on Quality slide 11.","from":[{"s":"M24c","qn":"Q3","pg":5}]},{"id":"M24b-1-4","ch":3,"sl":"20","tp":"Pair programming weakness","t":"mcq","q":"Which of the following is a true disadvantage of pair programming in XP?","o":["The code is not being examined or reviewed","Both members of a pair mutual understanding of the code","Both members of a pair may make the same mistake in understanding the system requirements","Working in pairs takes double the time to produce the code compared to single individuals"],"a":2,"e":"Quality slide 20: \"Mutual misunderstandings — both members of a pair may make the same mistake in understanding the system requirements.\"","from":[{"s":"M24b","qn":"Q1.4","pg":1}]},{"id":"M24b-1-5","ch":3,"sl":"2","tp":"Benefit of standards","t":"mcq","q":"The benefit of having and using software standards is:","o":["They are always up-to-date","They often involve bureaucratic form-filling and processes","They are a framework for defining what quality means in a particular setting","They take into account measuring quality as experienced by users of the software"],"a":2,"e":"'Software standards' is a topic on Quality slide 2. Sommerville ch. 24: standards \"provide a framework for defining what quality means in a particular setting\" and capture best practice. Option b is a <i>problem</i> with standards.","from":[{"s":"M24b","qn":"Q1.5","pg":1}]},{"id":"M24b-1-6","ch":3,"sl":"11","tp":"Efficiency","t":"mcq","q":"It refers to the ability of a system to maximize performance and productivity while minimizing resource usage:","o":["Portability","Reliability","Resilience","Efficiency"],"a":3,"e":"<b>Efficiency</b> (a quality attribute on Quality slide 11) is about getting the most performance from the least resources (CPU, memory, time).","from":[{"s":"M24b","qn":"Q1.6","pg":2}]},{"id":"M24b-1-7","ch":3,"sl":"31","tp":"Size metrics","t":"mcq","q":"In size-oriented metrics, to measure the size of the program we use:","o":["Number of functions","Number of user inputs","Number of lines of code","Amount of memory usage"],"a":2,"e":"Quality slide 31: \"<b>Length of code</b> — this is a measure of the size of a program.\"","from":[{"s":"M24b","qn":"Q1.7","pg":2}]},{"id":"F24a-1-6","ch":3,"sl":"29","tp":"Project management T/F","t":"tf","q":"Static metrics are used to measure the performance and reliability of software.","a":1,"e":"Quality slide 29: <b>dynamic</b> metrics help assess efficiency and reliability; static metrics help assess complexity, understandability and maintainability.","from":[{"s":"F24a","qn":"Q1.6","pg":1}]},{"id":"F24a-1-7","ch":3,"sl":"23","tp":"Project management T/F","t":"tf","q":"A software metric can be used to quantify aspects of the software development process.","a":0,"e":"Quality slide 23: metrics \"allow the software and the software process to be quantified.\"","from":[{"s":"F24a","qn":"Q1.7","pg":1}]},{"id":"F24a-2-1","ch":3,"sl":"3","tp":"Quality management concern","t":"mcq","q":"What is the primary concern of software quality management?","o":["Cost reduction","Ensuring software meets the required quality level","Increasing development speed","Reducing team size"],"a":1,"e":"Quality slide 3: software quality management is \"concerned with ensuring that the <b>required level of quality is achieved</b> in a software product.\"","from":[{"s":"F24a","qn":"Q2.1","pg":2}]},{"id":"F24a-2-2","ch":3,"sl":"3","tp":"Project-level concerns","t":"mcq","q":"What is one of the three principal concerns of quality management at the project level?","o":["Marketing strategies","Defining a quality plan","Software pricing","Hiring more developers"],"a":1,"e":"Quality slide 3: \"At the project level, quality management is also concerned with <b>establishing a quality plan</b> for a project.\"","from":[{"s":"F24a","qn":"Q2.2","pg":2}]},{"id":"F24a-2-3","ch":3,"sl":"8","tp":"Fitness for purpose","t":"mcq","q":"The concept of 'fitness for purpose' in software quality focuses on:","o":["Aesthetic design","Specification conformance","How well the software meets user needs","Code efficiency"],"a":2,"e":"Quality slide 8: \"The focus may be 'fitness for purpose' <b>rather than specification conformance</b>\" — i.e. whether the software meets its users' needs.","from":[{"s":"F24a","qn":"Q2.3","pg":2}]},{"id":"F24a-2-4","ch":3,"sl":"16","tp":"Agile quality management","t":"mcq","q":"Agile quality management relies on:","o":["Strict adherence to documentation","Informal, culture-driven quality practices","Reducing team interactions","Outsourcing testing processes"],"a":1,"e":"Quality slide 16: agile QM is informal rather than document-based and relies on establishing a <b>quality culture</b>.","from":[{"s":"F24a","qn":"Q2.4","pg":2}]},{"id":"F24a-2-5","ch":3,"sl":"12","tp":"Quality conflicts","t":"mcq","q":"Quality conflicts in software development can occur because:","o":["Developers prefer working on different platforms","Improving one quality attribute may negatively impact another","Software specifications are always clear and concise","All teams have the same quality priorities"],"a":1,"e":"Quality slide 12 (quality conflicts): \"It is not possible for any system to be optimized for all of these attributes — for example, improving robustness may lead to loss of performance.\"","from":[{"s":"F24a","qn":"Q2.5","pg":2}]},{"id":"F24a-2-6","ch":3,"sl":"15","tp":"Quality culture","t":"mcq","q":"When developing a quality culture, quality managers should:","o":["Focus on documentation","Restrict communication between teams","Encourage teams to take ownership of quality improvement","Assign quality tasks to few key members"],"a":2,"e":"Quality slide 15: \"They should encourage teams to take responsibility for the quality of their work and to develop new approaches to quality improvement.\"","from":[{"s":"F24a","qn":"Q2.6","pg":2}]},{"id":"F24a-2-7","ch":3,"sl":"11","tp":"Quality attributes","t":"mcq","q":"Which of these is a software quality attribute focused on safety and resilience?","o":["Reliability","Portability","Usability","Modularity"],"a":0,"e":"Quality slide 11 groups <b>Safety, Security, Reliability, Resilience, Robustness</b> together (the dependability-related attributes). Portability, usability and modularity are not about safety.","from":[{"s":"F24a","qn":"Q2.7","pg":3}]},{"id":"M24a-1-6","ch":3,"sl":"31","tp":"Fan-in","t":"mcq","q":"What is FAN-IN a measure of?","o":["The number of functions that call another function","The number of bugs in a system","The number of classes in a program","The number of code lines written"],"a":0,"e":"Quality slide 31: \"Fan-in is a measure of the number of functions or methods that call another function or method (say X).\" Fan-out is the number of functions called by X.","from":[{"s":"M24a","qn":"Q1.6","pg":1}]},{"id":"M24a-2-1","ch":3,"sl":"4","tp":"Quality management T/F","t":"tf","q":"Quality management provides a dependent check on the software development process based on the project deliverables.","a":1,"e":"Quality slide 4: quality management provides an <b>independent</b> check on the software development process.","from":[{"s":"M24a","qn":"Q2.1","pg":3}]},{"id":"M24a-2-2","ch":3,"sl":"4","tp":"Quality management T/F","t":"tf","q":"The quality team should become a part of the development team so that they can take an objective view of the software.","a":1,"e":"Slide 4: the quality team should be <b>independent from</b> the development team to take an objective view.","from":[{"s":"M24a","qn":"Q2.2","pg":3}]},{"id":"M24a-2-3","ch":3,"sl":"9","tp":"Quality management T/F","t":"tf","q":"A software is fit for purpose if it is properly tested, sufficiently dependable, well-structured, and has acceptable performance for normal use.","a":0,"e":"Slide 9 (software fitness for purpose) lists exactly these questions.","from":[{"s":"M24a","qn":"Q2.3","pg":3}]},{"id":"M24a-2-4","ch":3,"sl":"","tp":"Quality management T/F","t":"tf","q":"Process standards are applied to the software product being developed, which include document standards, such as the structure of requirements documents.","a":1,"e":"Standards applied to the <b>product</b> (document structure, coding standards) are <b>product standards</b>; process standards define how development is carried out. (Sommerville ch. 24 — not on your slides.)","from":[{"s":"M24a","qn":"Q2.4","pg":3}]},{"id":"M24a-2-7","ch":3,"sl":"16","tp":"Quality management T/F","t":"tf","q":"The agile community is deeply supportive of the bureaucratic overheads of standards-based approaches because it improves quality processes.","a":1,"e":"Slide 16: \"The agile community is fundamentally <b>opposed</b> to what it sees as the bureaucratic overheads of standards-based approaches.\"","from":[{"s":"M24a","qn":"Q2.7","pg":3}]},{"id":"M24a-2-8","ch":3,"sl":"17","tp":"Quality management T/F","t":"tf","q":"'Check before check-in' means team members should not check in code that causes the system to fail.","a":1,"e":"Slide 17: that describes <b>never break the build</b>. 'Check before check-in' means programmers organise their own code reviews with other team members before checking code in.","from":[{"s":"M24a","qn":"Q2.8","pg":3}]},{"id":"M24a-2-9","ch":3,"sl":"19","tp":"Quality management T/F","t":"tf","q":"Pair programming leads to a profound knowledge of a program, as both programmers have to understand the program to continue development.","a":0,"e":"Slide 19: \"Pair programming leads to a deep knowledge of a program, as both programmers have to understand the program in detail to continue development.\"","from":[{"s":"M24a","qn":"Q2.9","pg":3}]},{"id":"M24a-2-10","ch":3,"sl":"18","tp":"Quality management T/F","t":"tf","q":"The review process in agile software development is usually informal.","a":0,"e":"Slide 18: \"The review process in agile software development is usually informal.\"","from":[{"s":"M24a","qn":"Q2.10","pg":3}]},{"id":"F23c-1-7","ch":3,"sl":"11","tp":"Efficiency","t":"mcq","q":"Minimal use of resources is best used to measure:","o":["Efficiency","Adaptability","Complexity","Robustness"],"a":0,"e":"<b>Efficiency</b> (Quality slide 11) is about using minimal resources (time, memory, CPU) for the required performance.","from":[{"s":"F23c","qn":"Q1.7","pg":2}]},{"id":"M22b1-1-5","ch":3,"sl":"20","tp":"Pair programming downside","t":"mcq","q":"A downside of pair programming that could jeopardize the quality of software development is the possibility of having:","o":["Code is unlikely being reviewed by the pair","Mutual misunderstanding of the requirements","The depth of knowledge of the program by the pair is shallow","None of the above. Pair programming guarantees to produce software with the best qualities."],"a":1,"e":"Quality slide 20: \"Mutual misunderstandings — both members of a pair may make the same mistake in understanding the system requirements.\"","from":[{"s":"M22b1","qn":"Q1.5","pg":1}]},{"id":"Q22a-1","ch":3,"sl":"16","tp":"Agile vs standards","t":"mcq","q":"The agile community is opposed to the ______ of the standards.","o":["Continuity","Best practices","Attributes","Bureaucratic overhead"],"a":3,"e":"Quality slide 16: \"The agile community is fundamentally opposed to what it sees as the <b>bureaucratic overheads</b> of standards-based approaches.\"","from":[{"s":"Q22a","qn":"Q1"}]},{"id":"Q22a-3","ch":3,"sl":"8, 12","tp":"Fitness for purpose","t":"tf","q":"In software quality we focus on fitness for purpose rather than optimizing all quality attributes.","a":0,"e":"Quality slide 8: \"The focus may be 'fitness for purpose' rather than specification conformance\"; slide 12: no system can be optimized for all attributes, so the plan picks the most important ones.","from":[{"s":"Q22a","qn":"Q3"}]},{"id":"Q22a-5","ch":3,"sl":"11","tp":"Crucial quality attributes for a banking app","t":"short","q":"You are required to develop a banking application for a bank's customers to use for account and monetary transactions. Pick the <b>two</b> most crucial quality attributes for the developers:<br>Reusability · Security · Adaptability · Usability · Complexity · Testability · Modularity","a":"<b>Security</b> (money and personal data must be protected) and <b>Usability</b> (ordinary customers, not experts, must be able to use it easily).","e":"Quality slide 11 (quality attributes) and slide 12: the quality plan must pick the <i>most important</i> attributes for the specific system. Reusability, modularity, testability etc. are developer-side attributes (slide 8).","from":[{"s":"Q22a","qn":"Q5"}]},{"id":"M22a-1-1","ch":3,"sl":"7","tp":"Quality plan structure","t":"mcq","q":"A quality plan structure contains:","o":["Quality goals","Risks management","Process descriptions","All of the above"],"a":3,"e":"Quality slide 7 (quality plan structure): product introduction, product plans, <b>process descriptions</b>, <b>quality goals</b>, <b>risks and risk management</b>. Official key: d.","from":[{"s":"M22a","qn":"Q1.1"},{"s":"M21b","qn":"Q1.1","pg":2},{"s":"Q21","qn":"Quiz 1 (sec 373) Q2a"}]},{"id":"M22a-1-2","ch":3,"sl":"4","tp":"Quality management activities","t":"mcq","q":"Which is <b>not</b> one of the quality management activities?","o":["Provides an independent check on the software development process","The quality management should be done by the development team","Ensure that the project is consistent with organizational standards and goals"],"a":1,"e":"Quality slide 4: QM provides an independent check and checks deliverables against organizational standards; the quality team should be <b>independent from</b> the development team. Official key: b.","from":[{"s":"M22a","qn":"Q1.2"}]},{"id":"M22a-1-6","ch":3,"sl":"2","tp":"Benefit of standards","t":"mcq","q":"A benefit of following software standards is:","o":["Standards might be irrelevant","Standards encapsulate best practices","Standards are always up-to-date","None of the above"],"a":1,"e":"Standards capture (encapsulate) best practice and knowledge that was learned through trial and error. 'Might be irrelevant' and 'not up-to-date' are problems of standards. Official key: b.","from":[{"s":"M22a","qn":"Q1.6"},{"s":"M21b","qn":"Q1.5","pg":2}]},{"id":"M21a-1-1","ch":3,"sl":"16","tp":"Agile quality management","t":"mcq","q":"Quality management in agile development is:","o":["A document-based process","A bureaucratic process","A stage-by-stage process","An informal process"],"a":3,"e":"Quality slide 16: \"Quality management in agile development is <b>informal</b> rather than document-based.\" Official key: d.","from":[{"s":"M21a","qn":"Q1.1","pg":2}]},{"id":"M21a-2-2","ch":3,"sl":"2","tp":"True / False","t":"tf","q":"Quality standards aren't usually up-to-date.","a":0,"e":"A known problem with standards: they are often out-of-date / not seen as relevant (Sommerville ch. 24). Official key: T.","from":[{"s":"M21a","qn":"Q2.2","pg":3}]},{"id":"Q21-1b","ch":3,"sl":"16","tp":"ISO 9001 — process control","t":"mcq","q":"According to ISO 9001, inspection and testing come under which management responsibility?","o":["Process control","Document control","Product control"],"a":0,"e":"In ISO 9001, inspection and testing are part of <b>process control</b>. Quiz 1 model answer: process control. (Quality slide 16 mentions ISO 9001 quality processes.)","from":[{"s":"Q21","qn":"Quiz 1 (sec 372) Q2a"}]},{"id":"Q21-1d","ch":3,"sl":"4","tp":"Quality management activities","t":"short","q":"Give two of the main activities provided by quality management.","a":"1) Quality management provides an <b>independent check</b> on the software development process.<br>2) It <b>checks the project deliverables</b> to ensure they are consistent with organisational standards and goals.","e":"Quality slide 4 (quiz model answer).","from":[{"s":"Q21","qn":"Quiz 1 (sec 373) Q1"}]},{"id":"Q21-1h","ch":3,"sl":"2","tp":"Benefit of standards","t":"mcq","q":"The benefit of standards is that they:","o":["Are up-to-date","Provide continuity","Are usually supported by software tools","All of the above"],"a":1,"e":"Standards capture best practice and <b>provide continuity</b> — new staff can understand and follow the organisation's practices. Quiz 1 model answer: b.","from":[{"s":"Q21","qn":"Quiz 1 (sec 371) Q2a"}]},{"id":"Q21-1i","ch":3,"sl":"16","tp":"ISO 9001 is a…","t":"mcq","q":"ISO 9001 is a:","o":["Standard","Standard framework","Software measurement","All of the above"],"a":1,"e":"ISO 9001 is a general <b>framework</b> for quality management systems that organisations instantiate with their own standards and processes. Quiz 1 model answer: b.","from":[{"s":"Q21","qn":"Quiz 1 (sec 371) Q2b"}]},{"id":"M26b-3B","ch":4,"sl":"12–16, 23, 27–29","tp":"Refactor for readability","t":"short","q":"The following code is intended to compute and return the area of a rectangle using its length and width. Refactor the code to improve its readability by applying good coding practices of <b>code structure</b> and <b>code documentation</b>.<pre>int f(int l,int w)\nint r=l*w;\nreturn r;</pre>","a":"<pre>/**\n * Computes the area of a rectangle.\n * @param length  the rectangle's length (must be &gt;= 0)\n * @param width   the rectangle's width (must be &gt;= 0)\n * @return        the area (length * width)\n */\nint computeRectangleArea(int length, int width) {\n    int area = length * width;\n    return area;\n}</pre>","e":"Code structure: meaningful identifiers — the function name is a verb, variables are nouns, one naming style (slides 12–16); be explicit with curly brackets and consistent indentation (slide 23). Documentation: use a standard such as JavaDoc describing what the code does, its parameters, restrictions and return value (slides 27–29).","from":[{"s":"M26b","qn":"Q3 Part B","pg":4}]},{"id":"F26a-1-6","ch":4,"sl":"31","tp":"Formally correct program","t":"mcq","q":"What is a \"formally correct\" program?","o":["One that compiles without warnings","One that follows naming conventions","One whose correctness can be mathematically proved","One that is fully documented"],"a":2,"e":"Slide 31: \"A 'formally correct' program is one whose correctness can be <b>proved mathematically</b>, at least to a point that designers and users are convinced about its relative absence of errors.\"","from":[{"s":"F26a","qn":"Q1.6","pg":1}]},{"id":"F26a-1-7","ch":4,"sl":"32","tp":"Runtime errors","t":"mcq","q":"Which type of errors are detected at \"runtime\" because they cannot be found by the compiler?","o":["Syntax errors","Static semantic errors","Spelling errors in comments","Dynamic semantic errors and logical errors"],"a":3,"e":"Slide 32: \"Runtime errors: <b>dynamic semantic errors, and logical errors</b>, that cannot be detected by the compiler (debugging).\" Syntax and static semantic errors are compile-time errors.","from":[{"s":"F26a","qn":"Q1.7","pg":2}]},{"id":"F26a-1-8","ch":4,"sl":"14, 15","tp":"Choosing identifiers","t":"mcq","q":"What is recommended for choosing identifiers in code structure?","o":["Use small variations like s1, s2","Mix CamelCase and underscores freely","Use meaningful names and coherent styles","Always use non-English keywords"],"a":2,"e":"Slide 14: use <b>meaningful names</b> and avoid small variations like s1, s2. Slide 15: use coherent identifiers — one language, one variable style.","from":[{"s":"F26a","qn":"Q1.8","pg":2}]},{"id":"F26a-1-9","ch":4,"sl":"10","tp":"SRP","t":"mcq","q":"According to SRP (Single Responsibility Principle), what should a function do?","o":["As many things as possible","One thing only, and do it well","Whatever the programmer wants","Only mathematical calculations"],"a":1,"e":"Slide 10: SRP — \"Functions should do one thing. They should do it well. They should do it only.\" (Robert C. Martin)","from":[{"s":"F26a","qn":"Q1.9","pg":2}]},{"id":"F26a-1-10","ch":4,"sl":"15","tp":"Naming style","t":"mcq","q":"Regarding variable naming styles (like CamelCase vs. underscores), the slides advise:","o":["Always use underscores for Java and CamelCase for C","Use both styles in the same project to show versatility","Never use CamelCase as it is hard for compilers to read","Use one variable style and stick to it; do not use both"],"a":3,"e":"Slide 15: \"Use one variable style — either CamelCaseIdentifiers or underscores_identifiers, <b>but not both!</b>\"","from":[{"s":"F26a","qn":"Q1.10","pg":2}]},{"id":"F25b-1-6","ch":4,"sl":"8","tp":"Project & quality management T/F","t":"tf","q":"Code review really has two main purposes: improving the code and improving the programmer.","a":0,"e":"Source Code Quality slide 8: \"Code review really has two purposes: Improving the code. Improving the programmer.\"","from":[{"s":"F25b","qn":"Q1.6","pg":1}]},{"id":"F25b-2-9","ch":4,"sl":"10","tp":"DRY principle","t":"mcq","q":"DRY: Don't Repeat Yourself is one of the common clean code principles, which means …","o":["Leave the campground cleaner than you found it","Functions should do one thing and should do it well","Avoid code duplications","Function names are verbs"],"a":2,"e":"Source Code Quality slide 10: \"DRY: Don't Repeat Yourself — to avoid code duplications.\" (a) is the Boy Scout rule, (b) is SRP.","from":[{"s":"F25b","qn":"Q2.9","pg":3}]},{"id":"F25b-2-10","ch":4,"sl":"6","tp":"Clean code","t":"mcq","q":"Clean code means …","o":["Compact and literate","Contains only what is necessary","Readable, simple and direct","All of the above"],"a":3,"e":"Source Code Quality slide 6 (What is clean code): readable, simple and direct; compact and literate; contains only what is necessary; … — all three are listed.","from":[{"s":"F25b","qn":"Q2.10","pg":3}]},{"id":"M25b-3A-1","ch":4,"sl":"6","tp":"Clean code","t":"short","q":"What is clean code?","a":"Clean code is code that is <b>readable, simple and direct</b>; compact and literate; contains only what is necessary; makes it easy for other developers to enhance it; has clean tests; contains no duplicates; is built on tiny abstractions; and gives fast productivity during maintenance.","e":"Source Code Quality slide 6 (What is clean code after all?).","from":[{"s":"M25b","qn":"Q3 Part A.1","pg":4}]},{"id":"M25b-3A-2","ch":4,"sl":"10","tp":"SRP","t":"short","q":"What is SRP: Single Responsibility Principle?","a":"\"<b>Functions should do one thing. They should do it well. They should do it only.</b>\" — a function/class should have one responsibility (one and only one reason to change).","e":"Source Code Quality slide 10 (Robert C. Martin); OOAD slide 15: a class should have one and only one reason to change.","from":[{"s":"M25b","qn":"Q3 Part A.2","pg":4}]},{"id":"M25b-3B","ch":4,"sl":"12–16, 20–23, 27–29","tp":"Refactor for readability","t":"short","q":"The following code snippet is supposed to check the age of a user. Refactor the code snippet to make it more readable by using code quality practices.<pre>static void checkA(int A) {\nif (A &lt; 18) {\nSystem.out.println(\"Access denied - You are not old enough!\");\n} else\n{System.out.println(\"Access granted - You are old enough!\");\n}\n}</pre>","a":"<pre>/**\n * Checks whether a user is old enough to get access.\n * @param userAge  the user's age in years (must be &gt;= 0)\n */\nstatic void checkUserAge(int userAge) {\n    final int MINIMUM_AGE = 18;\n    if (userAge &lt; MINIMUM_AGE) {\n        System.out.println(\"Access denied - You are not old enough!\");\n    } else {\n        System.out.println(\"Access granted - You are old enough!\");\n    }\n}</pre>","e":"Meaningful identifiers (verb for the method, noun for the variable), no magic numbers, one brace style with consistent indentation (slides 12–18), explicit curly brackets (slides 20–23), and JavaDoc documentation (slides 27–29).","from":[{"s":"M25b","qn":"Q3 Part B","pg":5}]},{"id":"M25a-3B","ch":4,"sl":"12–16, 23, 27–29","tp":"Refactor for readability","t":"short","q":"The following code snippet is supposed to calculate and return a person's age based on their birth year. Refactor the code snippet to make it more readable by using code quality practices.<pre>int fun(int y)\nint a = 2025 - y;\nreturn a;</pre>","a":"<pre>/**\n * Calculates a person's age from their birth year.\n * @param birthYear  the year the person was born (must not be after currentYear)\n * @return           the person's age in years\n */\nint calculateAge(int birthYear) {\n    final int CURRENT_YEAR = 2025;\n    int age = CURRENT_YEAR - birthYear;\n    return age;\n}</pre>","e":"Code structure: meaningful identifiers (verb for the function name, nouns for variables), avoid magic numbers, one naming style, explicit curly brackets and indentation (slides 12–17, 23). Documentation: a JavaDoc comment stating what the code does, its parameter, restrictions and return value (slides 27–29).","from":[{"s":"M25a","qn":"Q3 Part B","pg":3}]},{"id":"F24c-1-5","ch":4,"sl":"33","tp":"When to apply formal methods","t":"mcq","q":"When should formal methods be applied in the development process?","o":["Only at the end, after the system is fully implemented","Throughout the development lifecycle, in parallel with testing","During the early stages of design and specification","When the system is released to the customers"],"a":2,"e":"Source Code Quality slide 33: formal methods are applied to software requirements analysis (UML) and validation — they are most cost-effective in the <b>early stages of specification and design</b>, where they find errors before code is written.","from":[{"s":"F24c","qn":"Q1.5","pg":7}]},{"id":"F24c-4-1-1","ch":4,"sl":"15","tp":"Code review of Util class","t":"tf","q":"<pre>public class Util {\n  public static int add(int a, int b) { return a + b; }\n  public static int sub(int a, int b) { return a - b; }\n  public static int mul(int a, int b) { return a * b; }\n  public static int div(int a, int b) { return a / b; }\n  public static boolean isEven(int num) { return num % 2 == 0; }\n  public static boolean is_Odd(int num) { return num % 2 != 0; }\n  public static void printMessage(String message) { System.out.println(message); }\n}\npublic class Main {\n  public static void main(String[] args) {\n    int result = Util.add(5, 3);\n    Util.printMessage(\"The sum is: \" + result);\n    result = Util.sub(10, 4); …  result = Util.div(20, 4); …\n    boolean isEven = Util.isEven(12); …\n    boolean isOdd = Util.isOdd(11); …\n  }\n}</pre>The identifiers in the code are coherent.","a":1,"e":"The naming style is mixed: <code>isEven</code> uses CamelCase but <code>is_Odd</code> uses an underscore — slide 15: use one variable style, \"but not both!\" (main even calls <code>isOdd</code>, which does not match <code>is_Odd</code>).","from":[{"s":"F24c","qn":"Q4.1.1","pg":4}]},{"id":"F24c-4-1-2","ch":4,"sl":"26–29","tp":"Code review of Util class","t":"tf","q":"<pre>public class Util {\n  public static int add(int a, int b) { return a + b; }\n  public static int sub(int a, int b) { return a - b; }\n  public static int mul(int a, int b) { return a * b; }\n  public static int div(int a, int b) { return a / b; }\n  public static boolean isEven(int num) { return num % 2 == 0; }\n  public static boolean is_Odd(int num) { return num % 2 != 0; }\n  public static void printMessage(String message) { System.out.println(message); }\n}\npublic class Main {\n  public static void main(String[] args) {\n    int result = Util.add(5, 3);\n    Util.printMessage(\"The sum is: \" + result);\n    result = Util.sub(10, 4); …  result = Util.div(20, 4); …\n    boolean isEven = Util.isEven(12); …\n    boolean isOdd = Util.isOdd(11); …\n  }\n}</pre>The code lacks proper documentation.","a":0,"e":"There are no comments or JavaDoc at all — slides 27–29: document what the code does, the parameters, return values, restrictions (e.g. <code>div</code> with b = 0) and exceptions.","from":[{"s":"F24c","qn":"Q4.1.2","pg":4}]},{"id":"F24c-4-1-3","ch":4,"sl":"10","tp":"Code review of Util class","t":"tf","q":"<pre>public class Util {\n  public static int add(int a, int b) { return a + b; }\n  public static int sub(int a, int b) { return a - b; }\n  public static int mul(int a, int b) { return a * b; }\n  public static int div(int a, int b) { return a / b; }\n  public static boolean isEven(int num) { return num % 2 == 0; }\n  public static boolean is_Odd(int num) { return num % 2 != 0; }\n  public static void printMessage(String message) { System.out.println(message); }\n}\npublic class Main {\n  public static void main(String[] args) {\n    int result = Util.add(5, 3);\n    Util.printMessage(\"The sum is: \" + result);\n    result = Util.sub(10, 4); …  result = Util.div(20, 4); …\n    boolean isEven = Util.isEven(12); …\n    boolean isOdd = Util.isOdd(11); …\n  }\n}</pre>The methods in the class violate the Single Responsibility Principle (SRP).","a":1,"e":"Each method does exactly one thing (add, subtract, check even, print…) — slide 10: \"Functions should do one thing.\"","from":[{"s":"F24c","qn":"Q4.1.3","pg":4}]},{"id":"F24c-4-1-4","ch":4,"sl":"","tp":"Code review of Util class","t":"tf","q":"<pre>public class Util {\n  public static int add(int a, int b) { return a + b; }\n  public static int sub(int a, int b) { return a - b; }\n  public static int mul(int a, int b) { return a * b; }\n  public static int div(int a, int b) { return a / b; }\n  public static boolean isEven(int num) { return num % 2 == 0; }\n  public static boolean is_Odd(int num) { return num % 2 != 0; }\n  public static void printMessage(String message) { System.out.println(message); }\n}\npublic class Main {\n  public static void main(String[] args) {\n    int result = Util.add(5, 3);\n    Util.printMessage(\"The sum is: \" + result);\n    result = Util.sub(10, 4); …  result = Util.div(20, 4); …\n    boolean isEven = Util.isEven(12); …\n    boolean isOdd = Util.isOdd(11); …\n  }\n}</pre>There is high coupling between main() and class Util.","a":0,"e":"main() calls every static method of Util directly, so it depends on Util's whole interface — any change to Util ripples into main (high fan-out, Quality slide 31). <i>This item is open to interpretation; justify your choice either way.</i>","from":[{"s":"F24c","qn":"Q4.1.4","pg":4}]},{"id":"M24c-1-6","ch":4,"sl":"10","tp":"DRY","t":"mcq","q":"In design quality, we follow the DRY rule, which means:","o":["Defer Redundant Yellowpages","Duplicate Reduction Yields","Different Reports Yearly","Don't Repeat Yourself"],"a":3,"e":"Source Code Quality slide 10: \"DRY: <b>Don't Repeat Yourself</b> — to avoid code duplications.\"","from":[{"s":"M24c","qn":"Q1.6","pg":1}]},{"id":"F24b-1-2","ch":4,"sl":"9","tp":"Code smell","t":"mcq","q":"What does the term \"Code Smell\" refer to?","o":["A pleasant aroma in the development environment","A coding style that is universally accepted","Comments in the code that are too verbose","Indications of potential issues in the code"],"a":3,"e":"Source Code Quality slide 9: \"Programmers often describe bad code as having a '<b>bad smell</b>' that needs to be removed.\" A code smell is a sign of a problem in the code.","from":[{"s":"F24b","qn":"Q1.2","pg":1}]},{"id":"F24b-1-4","ch":4,"sl":"3, 12, 13","tp":"Code readability","t":"mcq","q":"What is code readability?","o":["The ability to execute code without errors","The efficiency of code execution","The number of lines of code in a program","The ease with which code can be understood by humans"],"a":3,"e":"Source Code Quality slide 3 (legibility issues): \"Code should document itself; code should be easy to read.\" Slides 12–13 show how meaningful names make code understandable.","from":[{"s":"F24b","qn":"Q1.4","pg":1}]},{"id":"F24b-2-3","ch":4,"sl":"8","tp":"True / False","t":"tf","q":"Code reviews are an essential component of ensuring software quality.","a":0,"e":"Source Code Quality slides 8–9: code review improves the code and the programmer; at Google no code can be pushed without a review.","from":[{"s":"F24b","qn":"Q2.3","pg":3}]},{"id":"F24b-2-7","ch":4,"sl":"33","tp":"True / False","t":"tf","q":"Formal methods are always more expensive than traditional testing techniques.","a":1,"e":"\"Always\" is wrong — formal methods have high up-front cost but can reduce later testing and rework costs, especially for critical systems. Source Code Quality slide 33 introduces formal methods.","from":[{"s":"F24b","qn":"Q2.7","pg":3}]},{"id":"F24a-2-8","ch":4,"sl":"8","tp":"Code review purpose","t":"mcq","q":"What is the primary purpose of a code review?","o":["To improve the code and the programmer","To update project documentation","To clean up unnecessary files","To enhance user interface design"],"a":0,"e":"Source Code Quality slide 8: \"Code review really has two purposes: Improving the code. Improving the programmer.\"","from":[{"s":"F24a","qn":"Q2.8","pg":3}]},{"id":"F24a-2-9","ch":4,"sl":"20–23","tp":"Be explicit — curly brackets","t":"mcq","q":"What issue is often associated with not using curly brackets in conditional statements?","o":["Reduced performance","Syntax errors","Increased ambiguity and potential errors","Better readability"],"a":2,"e":"Source Code Quality slides 20–23 (Be explicit): without braces, adding a second statement or nesting if/else makes the code ambiguous (dangling else) — \"Does that do what you mean?\" — so use curly brackets.","from":[{"s":"F24a","qn":"Q2.9","pg":3}]},{"id":"F24a-2-10","ch":4,"sl":"31","tp":"Correct program","t":"mcq","q":"What does a \"correct\" program mean?","o":["A program that is well-documented","A program that compiles without errors","A program that meets its design and user requirements","A program that has no user interface bugs"],"a":2,"e":"Source Code Quality slide 31: \"A 'correct' program is one that does exactly what its designers and users intend it to do — no more and no less.\"","from":[{"s":"F24a","qn":"Q2.10","pg":3}]},{"id":"M24a-3A-1","ch":4,"sl":"8","tp":"Purpose of code review","t":"short","q":"What is the primary purpose of code review?","a":"Code review (careful, systematic study of code by people who are not its author) has two purposes: <b>improving the code</b> and <b>improving the programmer</b>.","e":"Source Code Quality slide 8.","from":[{"s":"M24a","qn":"Q3 Part A.1","pg":4}]},{"id":"M24a-3A-2","ch":4,"sl":"32","tp":"Compile-time errors","t":"short","q":"What type of errors can be caught during compile time?","a":"<b>Syntax errors</b> and <b>static semantic errors</b> — these are reported by the compiler. (Dynamic semantic and logical errors appear only at runtime.)","e":"Source Code Quality slide 32: \"Compile time errors: syntax errors and static semantic errors indicated by the compiler.\"","from":[{"s":"M24a","qn":"Q3 Part A.2","pg":4}]},{"id":"M24a-3A-3","ch":4,"sl":"4, 7, 27","tp":"Why documentation matters","t":"short","q":"Why is code documentation important?","a":"Maintenance is the most expensive part of the software lifetime, and we don't know who will change the code later. Documentation explains <b>what the code does, its parameters, return values, input restrictions and exceptions</b>, so other developers can understand, use and maintain it without having to reverse-engineer it.","e":"Source Code Quality slide 4 (documentation should exist, follow standards and document), slide 7 (why: maintenance is most expensive) and slide 27 (what to include).","from":[{"s":"M24a","qn":"Q3 Part A.3","pg":4}]},{"id":"M24a-3A-4","ch":4,"sl":"10","tp":"Boy Scout rule","t":"short","q":"What is the \"Boy Scout Rule\" in clean coding?","a":"\"<b>Leave the campground cleaner than you found it</b>\" — every time you touch code, leave it a little cleaner (better names, less duplication) than it was.","e":"Source Code Quality slide 10 (Some clean code principles).","from":[{"s":"M24a","qn":"Q3 Part A.4","pg":4}]},{"id":"M24a-3B","ch":4,"sl":"12–16, 23, 27–29","tp":"Refactor longest-string code","t":"short","q":"The following code snippet is supposed to find the length of the longest string from a string array. Refactor the code snippet to make it more readable by using code quality practices.<pre>int x(string g[]){\nstring p = g[0];\nint o = p.length();\nfor (int z=1;z&lt;g.length; z++)\nif (g[z].length()&gt;o) {\np = g[z];\no = p.length();\n}\nreturn o;\n}</pre>","a":"<pre>/**\n * Given an array of strings, computes the length of the longest string.\n * This method will not work for empty lists.\n * @param list  the list of strings to be processed\n * @return      the size of the longest string in the array\n */\nint longestStringLength(string list[]) {\n    string maxString = list[0];\n    int maxSize = maxString.length();\n    for (int i = 1; i &lt; list.length; i++) {\n        if (list[i].length() &gt; maxSize) {\n            maxString = list[i];\n            maxSize = maxString.length();\n        }\n    }\n    return maxSize;\n}</pre>","e":"This is the exact example from Source Code Quality slides 12–13 (meaningful identifiers), 17 (indentation), 23 (curly brackets) and 29 (JavaDoc).","from":[{"s":"M24a","qn":"Q3 Part B","pg":4}]},{"id":"F23c-2-8","ch":4,"sl":"31","tp":"True / False","t":"tf","q":"When a program is proven to be correct using formal verification, then we can indicate that the program is formally correct.","a":0,"e":"Source Code Quality slide 31: a 'formally correct' program is one whose correctness can be proved mathematically. (The official Fall 2023 key says True; the solved copy of this exam marked False — that is wrong.)","from":[{"s":"F23c","qn":"Q2.8","pg":3}]},{"id":"F23b-1-1","ch":4,"sl":"10","tp":"Clean code principles","t":"mcq","q":"Which of the following is <b>not</b> one of the clean code principles?","o":["Rule of thumb","Boy Scout rule","Don't Repeat Yourself","Single Responsibility Principle"],"a":0,"e":"Source Code Quality slide 10 lists the clean code principles: <b>Boy Scout rule</b>, <b>DRY</b> and <b>SRP</b>. \"Rule of thumb\" is not one of them.","from":[{"s":"F23b","qn":"Q1.1","pg":1}]},{"id":"F23b-1-6","ch":4,"sl":"15","tp":"Coherent identifiers","t":"mcq","q":"To use coherent identifiers in an attempt to clean up your code means:","o":["Choosing one variable style for one language, such as CamelCase identifiers","Choosing meaningful variables","Choosing proper data structure","Choosing proper indentation"],"a":0,"e":"Source Code Quality slide 15 (Use coherent identifiers): choose one language and <b>one variable style</b> — either CamelCase or underscores, but not both.","from":[{"s":"F23b","qn":"Q1.6","pg":3}]},{"id":"F23a-1-4","ch":4,"sl":"31, 33","tp":"Formal verification advantage","t":"mcq","q":"Which of the following is a key advantage of formal verification?","o":["Quick and easy to apply","Can detect all possible defects in a software system","Provides mathematical proof of correctness","Requires no formal specification of software behaviour"],"a":2,"e":"Source Code Quality slide 31: a 'formally correct' program's correctness can be <b>proved mathematically</b>; slide 33: formal methods use mathematical modelling for specification and verification. Official key: c.","from":[{"s":"F23a","qn":"Q1.4"}]},{"id":"F23a-2-8","ch":4,"sl":"31","tp":"True / False","t":"tf","q":"When a program is proven to be correct using formal verification, then we can say that the program is formally correct.","a":0,"e":"Source Code Quality slide 31: a 'formally correct' program is one whose correctness can be proved mathematically. Official key: T.","from":[{"s":"F23a","qn":"Q2.8"}]},{"id":"M22b1-1-3","ch":4,"sl":"15","tp":"Coherent identifiers","t":"mcq","q":"To maintain code quality, we should use coherent identifiers, which means:","o":["We should use camel case identifiers","We should use one language and one variable style","We should use a unified vertical alignment","We should use meaningful variable names"],"a":1,"e":"Source Code Quality slide 15: \"Use coherent identifiers — choose <b>one language</b> … use <b>one variable style</b>, either CamelCase or underscores, but not both.\" (d is 'meaningful names', a different rule on slide 14.)","from":[{"s":"M22b1","qn":"Q1.3","pg":1},{"s":"M21b","qn":"Q1.6","pg":2}]},{"id":"M22b1-1-4","ch":4,"sl":"10","tp":"Boy Scout rule","t":"mcq","q":"The Boy Scout rule says:","o":["Don't Repeat Yourself","Leave the campground cleaner than you found it","Functions should do one thing. They should do it well.","Speak only to your friends. Treat friends' friends as your enemies."],"a":1,"e":"Source Code Quality slide 10: Boy Scout rule — \"Leave the campground cleaner than you found it.\"","from":[{"s":"M22b1","qn":"Q1.4","pg":1}]},{"id":"M22a-1-7","ch":4,"sl":"10","tp":"Not a clean code principle","t":"mcq","q":"Which is <b>not</b> a clean code principle?","o":["A problem in code must be fixed by the original developer","Avoid code duplications","Functions should do one thing"],"a":0,"e":"Avoid duplication (DRY) and one-thing functions (SRP) are on Source Code Quality slide 10. Quality slide 17 says the opposite of (a): \"Fix problems when you see them\" — you can fix others' code directly. Official key: a.","from":[{"s":"M22a","qn":"Q1.7"}]},{"id":"M22a-2-1","ch":4,"sl":"12–16, 26–29","tp":"Evaluate and fix string-reverse code","t":"short","q":"Evaluate the quality of the following code and fix the issues (the code reverses a string; find at least 3 issues):<pre>public class string\n{static String string1(String x1)\n{String x2=\"\";\nfor(int i=x1.length();i&gt;0;--i)  {  x2=x2+(x1.charAt(i-1));  }\nreturn x2; }\npublic static void main(String[] arg) {\nstring  x3=new string ();\nScanner x4=new Scanner(System.in);\nSystem.out.print(\"Enter a string: \");\nString  x5=x4.nextLine();\nSystem.out.println(\"Reverse of a String  is : \"+x3.string1(X5));  }}</pre>","a":"<b>Issues:</b><ul><li>Meaningless identifiers (<code>string</code>, <code>string1</code>, <code>x1</code>…<code>x5</code>) — slide 14; the class name <code>string</code> is lowercase and clashes with <code>String</code>.</li><li>Inconsistent identifier: <code>X5</code> vs <code>x5</code> (Java is case-sensitive — it won't compile).</li><li>No indentation / poor layout — slides 17–18.</li><li>No documentation — slides 26–29.</li><li>A static method is called through an unnecessary object instance.</li></ul><b>Fixed:</b><pre>/** Reverses strings. */\npublic class StringReverser {\n    /**\n     * Reverses the given text.\n     * @param text  the string to reverse (not null)\n     * @return      the reversed string\n     */\n    static String reverse(String text) {\n        String reversed = \"\";\n        for (int i = text.length(); i &gt; 0; i--) {\n            reversed = reversed + text.charAt(i - 1);\n        }\n        return reversed;\n    }\n\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        System.out.print(\"Enter a string: \");\n        String userText = input.nextLine();\n        System.out.println(\"Reverse of the string is: \" + reverse(userText));\n    }\n}</pre>","e":"Source Code Quality slides 12–16 (meaningful, coherent identifiers), 17–18 (indentation and structure), 26–29 (documentation, JavaDoc).","from":[{"s":"M22a","qn":"Q2.1"}]},{"id":"Q21-2a","ch":4,"sl":"15","tp":"CamelCase","t":"mcq","q":"A CamelCase identifier is a:","o":["Pattern","Code problem","Variable style","Documentation style"],"a":2,"e":"Source Code Quality slide 15: \"Use one <b>variable style</b> — either CamelCaseIdentifiers or underscores_identifiers.\"","from":[{"s":"Q21","qn":"Quiz 2 (sec 371) Q1a"}]},{"id":"Q21-2c","ch":4,"sl":"12–14, 19, 26–29","tp":"Evaluate test code","t":"short","q":"Evaluate the quality of the following code (write two problems):<pre>public void testCompareTo() throws Exception\n{\nWikiPagePath a = PathParser.parse(\"PageA\");\nWikiPagePath ab = PathParser.parse(\"PageA.PageB\");\nWikiPagePath b = PathParser.parse(\"PageB\");\nWikiPagePath aa = PathParser.parse(\"PageA.PageA\");\nWikiPagePath bb = PathParser.parse(\"PageB.PageB\");\nWikiPagePath ba = PathParser.parse(\"PageB.PageA\");\nassertTrue(a.compareTo(a) == 0);    // a == a\nassertTrue(a.compareTo(b) != 0);    // a != b\nassertTrue(ab.compareTo(ab) == 0);  // ab == ab\nassertTrue(a.compareTo(b) == -1);   // a &lt; b\n…</pre>","a":"Problem 1: identifiers are <b>not meaningful</b> (a, ab, b, aa, bb, ba).<br>Problem 2: <b>no vertical alignment</b> (or: the code has no documentation).","e":"Quiz 2 model answer. Source Code Quality slides 12–14 (meaningful names), 19 (vertical alignment), 26–29 (documentation).","from":[{"s":"Q21","qn":"Quiz 2 (sec 371) Q2"}]},{"id":"Q21-2d","ch":4,"sl":"5","tp":"Testing on every change","t":"tf","q":"Code should be tested on every change.","a":0,"e":"Source Code Quality slide 5: \"Code should be tested on every change!\"","from":[{"s":"Q21","qn":"Quiz 2 (sec 372) Q1a"}]},{"id":"Q21-2g","ch":4,"sl":"10, 14–18, 24","tp":"Match clean-code terms","t":"short","q":"Match the term with the expression that describes it the most.<br><b>Terms:</b> a) Refactoring b) DRY c) SRP d) Coherent identifiers e) Coherent code structure<ol><li>Avoid code duplications</li><li>Concerned with variable style</li><li>The process of maintaining and improving the existing code</li><li>Implement related data as a data structure</li></ol>","a":"<ol><li><b>b) DRY</b></li><li><b>d) Coherent identifiers</b></li><li><b>a) Refactoring</b></li><li><b>e) Coherent code structure</b></li></ol>","e":"Quiz 2 model answer. Source Code Quality slide 10 (DRY), slide 15 (coherent identifiers = one variable style), slide 18/24 (structure, proper data structures).","from":[{"s":"Q21","qn":"Quiz 2 (sec 373) Q1"}]},{"id":"Q21-2h","ch":4,"sl":"17, 18, 26","tp":"Evaluate one-line method","t":"short","q":"Evaluate the quality of the following code (write two problems):<pre>public static String renderPageWithSetupsAndTeardowns( PageData pageData, boolean isSuite) throws Exception { if (isTestPage(pageData)) includeSetupAndTeardownPages(pageData, isSuite); return pageData.getHtml(); }</pre>","a":"Problem 1: it doesn't use a <b>standard code structure</b> — everything is on one line with no indentation, and the if-statement has no curly brackets.<br>Problem 2: the code has <b>no documentation</b>.","e":"Quiz 2 model answer. Source Code Quality slides 17–18 (indentation, standard structure), 20–23 (be explicit with brackets), 26 (documentation).","from":[{"s":"Q21","qn":"Quiz 2 (sec 373) Q2"}]},{"id":"M26b-3A-1","ch":5,"sl":"15","tp":"SOLID principles","t":"short","q":"Mention three principles of the SOLID design principles.","a":"Any three of: <b>S</b>ingle Responsibility Principle · <b>O</b>pen/Closed Principle · <b>L</b>iskov Substitution Principle · <b>I</b>njection of Dependency · <b>D</b>emeter Principle.","e":"Slide 15 (OO Design Principles — SOLID): SRP — a class should have one and only one reason to change; OCP — open for extension, closed for modification; LSP — substituting a subclass should preserve correct behaviour; Injection of Dependency; Demeter — speak only to your friends.","from":[{"s":"M26b","qn":"Q3 Part A.1","pg":4}]},{"id":"M26b-3A-2","ch":5,"sl":"22","tp":"Adapter drawback","t":"short","q":"The <i>Adapter</i> design pattern converts the interface of a class into another interface clients expect. However, this might have a negative/bad effect. What is this bad effect?","a":"<b>The overall complexity of the code increases</b> (you add new interfaces and adapter classes).","e":"Slide 22 lists the Adapter pros (SRP, Open/Closed) and the con: \"The overall complexity of the code increases.\"","from":[{"s":"M26b","qn":"Q3 Part A.2","pg":4}]},{"id":"M25a-3A-1","ch":5,"sl":"19, 25","tp":"OO design patterns","t":"short","q":"Mention two patterns of the OO design patterns.","a":"Any two of: <b>Singleton</b> (only one instance of a class can exist), <b>Adapter</b> (match interfaces of different classes), <b>Façade</b> (a single class that represents an entire subsystem).","e":"OOAD slide 19: \"Three Design Patterns: Singleton, Adapter, Façade\"; slide 25 summarises each.","from":[{"s":"M25a","qn":"Q3 Part A.1","pg":3}]},{"id":"M25a-3A-2","ch":5,"sl":"15","tp":"Open/Closed principle","t":"short","q":"What is the Open/Closed OO design principle?","a":"Classes should be <b>open for extension but closed for modification</b> — you add new behaviour by extending (e.g. subclassing or new implementations) without changing existing, tested code.","e":"OOAD slide 15 (SOLID): \"Open/Closed Principle — Classes should be open for extension but closed for modification.\"","from":[{"s":"M25a","qn":"Q3 Part A.2","pg":3}]},{"id":"F24c-1-7","ch":5,"sl":"20, 25","tp":"Choosing a design pattern","t":"mcq","q":"A web application needs to manage user login sessions across multiple devices. Users can stay logged in on one device. If a user logs in from a different device, they are automatically logged out from the previous device. Which design pattern would be most appropriate to implement this user session management functionality?","o":["Singleton Pattern","Factory Pattern","Observer Pattern","Adapter Pattern"],"a":0,"e":"Only <b>one</b> active session may exist per user, managed by a single session manager — the Singleton pattern \"restricts creation of more than one object\" (OOAD slides 20, 25). Adapter only converts interfaces.","from":[{"s":"F24c","qn":"Q1.7","pg":6}]},{"id":"M24c-1-7","ch":5,"sl":"15, 24","tp":"Characteristic of good design","t":"mcq","q":"Which of the following is considered a characteristic of a good design?","o":["Low degree of connectivity/associations among the objects","Long communication chains between the objects","High coupling","Low cohesion"],"a":0,"e":"Good OO design has <b>low coupling</b> (few connections between objects) and high cohesion. OOAD slide 24: Façade gives \"low coupling between the subsystem and its clients\"; slide 15 Demeter: speak only to your friends (short chains).","from":[{"s":"M24c","qn":"Q1.7","pg":1}]},{"id":"M24c-4B","ch":5,"sl":"7","tp":"Initiating vs participating actor","t":"short","q":"From the use case diagram of the <b>Online Shopping System</b> (actors: Customer, &lt;&lt;service&gt;&gt; Authentication, Identity Provider, Credit Payment Service, PayPal; use cases: View items, Make purchase, Complete checkout, Log in), give an example of:<br>- An initiating actor<br>- A participating actor","a":"<b>Initiating actor:</b> <b>Customer</b> — starts the use cases (view items, make purchase, log in).<br><b>Participating actor:</b> e.g. <b>Credit Payment Service</b> or <b>PayPal</b> (take part in Complete checkout), or the Authentication / Identity Provider (take part in Log in) — they interact with the system but do not start the use case.","e":"OOAD slide 7: \"Use case — a complete sequence of related actions <b>initiated by an actor</b>; Actor — an external entity that interacts with the system.\"","from":[{"s":"M24c","qn":"Q4 B","pg":7}],"img":"M24c_usecase.jpg"},{"id":"M24c-4C","ch":5,"sl":"15","tp":"Shape code — pattern and violations","t":"short","q":"Check the following Java code:<pre>public interface Shape { double calculateArea(); }\n\npublic class Square implements Shape {\n  private int sideLength;\n  public Square(int sideLength) { this.sideLength = sideLength; }\n  @Override public double calculateArea() { return sideLength * sideLength; }\n  public void printArea() {\n    double area = calculateArea();\n    System.out.println(\"Square area: \" + area);\n  }\n}\npublic class Circle implements Shape {\n  private int radius;\n  public Circle(int radius) { this.radius = radius; }\n  @Override public double calculateArea() { return Math.PI * radius * radius; }\n  public void draw() { /* draw a circle on screen */ }\n}\npublic class ShapeProcessor {\n  public double calculateArea(Shape shape) { return shape.calculateArea(); }\n}\npublic class Main {\n  public static void main(String[] args) {\n    Shape square = new Square(5);\n    double squareArea = new ShapeProcessor().calculateArea(square);\n    Circle circle = new Circle(3);\n    double circleArea = new ShapeProcessor().calculateArea(circle);\n    square.printArea();\n    circle.draw();\n  }\n}</pre>1) What is the design pattern used? Justify.<br>2) Provide two design principles that this code violates and explain how.","a":"1) <b>Strategy</b> — <code>Shape</code> is a common interface for a family of interchangeable area algorithms (Square, Circle); <code>ShapeProcessor</code> (the context) works with any Shape without knowing the concrete class.<br>2) <b>Single Responsibility Principle:</b> Square both computes its area and prints it (<code>printArea</code>), and Circle both computes and draws itself — presentation is mixed with geometry, so each class has more than one reason to change.<br><b>Liskov Substitution Principle:</b> the subclasses are not interchangeable through the Shape type — Square adds <code>printArea()</code> and Circle adds <code>draw()</code>, which are not in the interface, so <code>square.printArea()</code> on a <code>Shape</code> reference does not even compile; clients must know the concrete type.<br><i>(Also acceptable: Open/Closed — adding a new shape's display behaviour means changing client code.)</i>","e":"OOAD slide 15 (SOLID). The Strategy pattern is not one of the three patterns in your OOAD deck; the Final 2021 model answer defines it as \"defines a family of algorithms, encapsulates each one and makes them interchangeable\".","from":[{"s":"M24c","qn":"Q4 C","pg":3}]},{"id":"M24b-3","ch":5,"sl":"15","tp":"SOLID violations in OrderProcessor","t":"short","q":"The following Java code violates some design principles and SOLID rules. Identify two of the design issues and explain how they are violated.<pre>public class OrderProcessor {\n  private DatabaseConnector databaseConnector;\n  private EmailSender emailSender;\n\n  public OrderProcessor() {\n    databaseConnector = new DatabaseConnector();\n    emailSender = new EmailSender();\n  }\n  public void processOrder(Order order) {\n    databaseConnector.connect();\n    databaseConnector.saveOrder(order);\n    databaseConnector.disconnect();\n  }\n  public void sendEmail(String message) {\n    System.out.print(\"Order processed successfully.\");\n  }\n}\npublic class DatabaseConnector {\n  public void connect()  { /* connect */ }\n  public void saveOrder(Order order) { /* save */ }\n  public void disconnect() { /* disconnect */ }\n}</pre>Choices: a) short communication chains b) avoid \"hub\" modules c) high cohesion d) low coupling e) Single Responsibility f) Open/Closed g) Injection of Dependency h) Liskov Substitution i) Demeter","a":"<b>e) Single Responsibility Principle</b> — OrderProcessor both processes/saves orders <i>and</i> sends emails, so it has more than one reason to change.<br><b>g) Injection of Dependency</b> — the constructor creates its collaborators itself with <code>new DatabaseConnector()</code> and <code>new EmailSender()</code>. They should be injected (passed in, ideally as interfaces) so implementations can vary at runtime.<br><i>(Also acceptable: d) Low coupling — OrderProcessor is tied to concrete classes; f) Open/Closed — switching to another database or email service requires modifying OrderProcessor.)</i>","e":"OOAD slide 15 (SOLID): SRP — a class should have one and only one reason to change; Injection of Dependency — collaborating classes whose implementation may vary at runtime should depend on an intermediate injected dependency.","from":[{"s":"M24b","qn":"Q3 A","pg":4}]},{"id":"F23c-1-6","ch":5,"sl":"15","tp":"SOLID","t":"mcq","q":"Which of the following is <b>not</b> one of the SOLID software design principles?","o":["Single Responsibility Principle","Open-Closed Principle","DRY Principle","Liskov Substitution Principle"],"a":2,"e":"OOAD slide 15 (SOLID): Single Responsibility, Open/Closed, Liskov Substitution, Injection of Dependency, Demeter. <b>DRY</b> is a clean-code principle (Source Code Quality slide 10).","from":[{"s":"F23c","qn":"Q1.6","pg":2}]},{"id":"F23b-1-5","ch":5,"sl":"26, 27","tp":"Broker pattern / middleware","t":"mcq","q":"The __________ is an architectural pattern used to structure distributed software systems with components that interact by remote method calls.","o":["Strategy pattern","Broker pattern","Repository pattern","Publisher-Subscriber pattern"],"a":1,"e":"The <b>Broker</b> pattern puts a middleware broker between distributed components that coordinates remote method calls (e.g. CORBA, Java RMI). OOAD slide 27: middleware offers services related to object communication so that extraneous functionality is offloaded to it.","from":[{"s":"F23b","qn":"Q1.5","pg":1}]},{"id":"F23b-1-8","ch":5,"sl":"7","tp":"Supporting actor","t":"mcq","q":"The actor that passively participates in the use case is called a(n):","o":["Onstage actor","Offstage actor","Supporting actor","Initiating actor"],"a":2,"e":"A <b>supporting</b> (participating/secondary) actor takes part in a use case started by someone else — e.g. a payment service. The initiating (primary) actor starts it. OOAD slide 7 defines actors as external entities that interact with the system.","from":[{"s":"F23b","qn":"Q1.8","pg":3}]},{"id":"F23b-2-1","ch":5,"sl":"20–25","tp":"Match pattern to situation","t":"short","q":"Match the design pattern to the situation where you should apply it (a pattern can be used for more than one system; each system has one pattern).<br><b>Patterns:</b> 1 Singleton · 2 Façade · 3 Observer · 4 Adapter · 5 Strategy<ol><li>Sending an SMS message requires lots of big ugly code, involving connection, message and other objects.</li><li>An app developed in the USA returns the top speed of luxury cars in miles per hour (MPH). Now we need to use the same app for clients in Saudi Arabia who want the same results but in kilometres per hour (km/h).</li><li>A shared single washing machine among all the residents in a hotel.</li><li>Each YouTuber has many subscribers on their channel. Each subscriber wants to watch their subscribed channel's videos.</li></ol>","a":"<ol><li><b>Façade</b> — one simple <code>sendSMS()</code> interface hides the complex connection/message subsystem.</li><li><b>Adapter</b> — converts the MPH interface into the km/h interface the Saudi clients expect.</li><li><b>Singleton</b> — only one instance exists and everyone shares it.</li><li><b>Observer</b> — subscribers are notified when the channel publishes a new video.</li></ol>","e":"OOAD slide 25: Singleton — a class of which only a single instance can exist; Adapter — match interfaces of different classes; Façade — a single class that represents an entire subsystem. Observer (publish/subscribe) is not in your deck.","from":[{"s":"F23b","qn":"Q2.1","pg":2}]},{"id":"F23b-2-2","ch":5,"sl":"15","tp":"Law of Demeter — installDoor","t":"short","q":"Consider the method installDoor() from the Contractor class:<pre>class Contractor {\n  installDoor() {\n    subcontractor  = YellowPages.getSubcontractor();\n    carpenter      = subcontractor.getCarpenter();\n    doorHandle     = carpenter.getDoorHandle();\n    doorBody       = carpenter.getDoorBody();\n    screws         = carpenter.getScrews();\n    door           = carpenter.assemble(doorHandle, doorBody, screws);\n    securityExpert = subcontractor.getSecurityExpert();\n    securityExpert.installDoorSensors(door);\n  }\n}</pre>1) Evaluate the quality of the code (write two problems).<br>2) What major design flaw is evident? Which design principle(s) are violated? Specify one design issue and suggest a solution.","a":"1) Problems: <b>no documentation</b> of what the method does; variables are never declared/typed; the method <b>does too much</b> (finds the subcontractor, gathers parts, assembles, installs sensors); it depends on a global <code>YellowPages</code> class.<br>2) <b>Violates the Law of Demeter</b> (\"speak only to your friends; treat your friends' friends as strangers\"): Contractor reaches through the subcontractor to the carpenter and security expert and manipulates their parts — <b>long communication chains and high coupling</b>. It also violates <b>SRP</b> and <b>Injection of Dependency</b> (it looks up its own subcontractor).<br><b>Solution:</b> tell, don't ask — delegate the work: <code>subcontractor.installDoor()</code>, where the subcontractor asks its carpenter to <code>buildDoor()</code> and its security expert to install sensors. Inject the subcontractor into Contractor instead of fetching it from YellowPages.","e":"OOAD slide 15: Demeter principle, SRP and Injection of Dependency; Source Code Quality slides 26–27 (documentation).","from":[{"s":"F23b","qn":"Q2.2","pg":2},{"s":"M22a","qn":"Q2.2"}]},{"id":"M22b1-1-1","ch":5,"sl":"27","tp":"Middleware","t":"mcq","q":"A __________ is software used to make diverse applications work together smoothly.","o":["Middleware","Traceability Matrix","JUnit Assertion","ISO 9001"],"a":0,"e":"OOAD slide 27: \"In general, <b>middleware</b> is software used to make diverse applications work together smoothly.\"","from":[{"s":"M22b1","qn":"Q1.1","pg":1},{"s":"M22a","qn":"Q1.3"},{"s":"M21b","qn":"Q1.3","pg":2}]},{"id":"M22b1-2a","ch":5,"sl":"13, 15","tp":"Compare sequence diagrams","t":"short","q":"This is a module sequence diagram of an online clothing store: after a customer places an order, this use case calculates the discount value of the total order.<br><b>(a)</b> <i>Order</i> does everything itself: getQuantity and getProduct from Order Line, getPricingDetails from Product, calculateBasePrice and calculateDiscounts itself, getDiscountInfo from Customer.<br><b>(b)</b> <i>Order</i> asks each Order Line to calculatePrice (which asks its Product getPrice(quantity)), then asks the Customer getDiscountedValue(order), which calls back getBaseValue.<br>Compare the two sequence diagrams in terms of OO design. Which provides a better design and why?","a":"<b>(b) is the better design.</b> Responsibility is distributed: each object does the work on the data it owns (Order Line computes its own price, Customer computes its own discount). This gives <b>shorter communication chains</b>, <b>lower coupling</b> and higher cohesion — Order no longer has to know the internals of Order Line, Product and Customer. In (a) Order is a \"hub\" that micromanages everyone (centralized control). <i>Official 2021 model answer: \"(b) has shorter communication chain than (a) and less responsibilities on an order, which means b has lower coupling.\"</i>","e":"OOAD slide 13 (sequence diagrams: messages, activations) and slide 15 (SRP, Demeter — speak only to your friends).","from":[{"s":"M22b1","qn":"Q2 a","pg":2},{"s":"M21b","qn":"Q2","pg":3}],"img":"M22_seq.jpg"},{"id":"M22b1-2c","ch":5,"sl":"7","tp":"Primary actor","t":"mcq","q":"If the system has an actor who initiates the use case to achieve a goal, then this actor is called a(n):","o":["Primary actor","Participating actor","Supporting actor","Offstage actor"],"a":0,"e":"The <b>primary</b> actor initiates the use case to achieve a goal (OOAD slide 7: a use case is initiated by an actor). Supporting/participating actors help; offstage actors have an interest but don't interact.","from":[{"s":"M22b1","qn":"Q2 c","pg":3},{"s":"M21a","qn":"Q1.3","pg":2}]},{"id":"M22b1-3-1","ch":5,"sl":"20–25","tp":"Match pattern to situation","t":"short","q":"Match the design pattern to the situation (each system has one pattern).<br><b>Patterns:</b> 1 Singleton · 2 Façade · 3 Observer · 4 Adapter · 5 Strategy<ol><li>Sending an SMS message requires lots of big ugly code, involving connection, message and other objects.</li><li>Your program must support switching among several different email libraries, but each one has a slightly different interface.</li><li>Your video game needs to listen for presses of the arrow keys to update the position of the character in the game.</li><li>The office of the President of the United States has at most one active president at any given time. Regardless of the identity of the active president, the title \"The President of the United States\" is a global point of access that identifies the person in the office.</li></ol>","a":"<ol><li><b>Façade</b> (2)</li><li><b>Adapter</b> (4)</li><li><b>Observer</b> (3)</li><li><b>Singleton</b> (1)</li></ol>","e":"Official 2021 model answer. OOAD slide 25: Façade = one class representing a whole subsystem; Adapter = match interfaces of different classes; Singleton = only one instance with a global access point. Observer (listeners) is not in your deck.","from":[{"s":"M22b1","qn":"Q3.1","pg":4},{"s":"M21b","qn":"Q3.1","pg":4}]},{"id":"M22b1-3-2","ch":5,"sl":"21, 22","tp":"RoboChef — Adapter design","t":"short","q":"You created an \"intelligent\" kitchen system, RoboChef, that controls kitchen appliances. Initially RoboChef uses only Electrolux gas ovens: <code>RoboChef —controls→ ElectroluxGasOven { +heat(howHot: Temperature, howLong: Time) }</code>. Now you want to support other ovens: <code>MaytagMicrowave { +cook(seconds: Integer, power: Integer) }</code> and <code>WhirlpoolElectricRange { +bake(degrees: Integer, time: Time) }</code>. Update the design to allow easy switching between oven-control systems.<br>1) What design pattern(s) should you use and why? 2) Draw a class diagram. 3) What effect did the new design have on the coupling between RoboChef and ElectroluxGasOven?","a":"1) <b>Adapter</b> — each vendor already provides an interface that <i>almost</i> does what RoboChef needs but with a different signature; an adapter converts it into the interface RoboChef expects, so new ovens are added without changing RoboChef (Open/Closed).<br>2) Class diagram:<pre>RoboChef ──controls──▶ «interface» Oven\n                        + heat(howHot: Temperature, howLong: Time)\n                              ▲ (implements)\n        ┌─────────────────────┼──────────────────────┐\nElectroluxAdapter       MaytagAdapter          WhirlpoolAdapter\n   │ adaptee                │ adaptee                │ adaptee\n   ▼                        ▼                        ▼\nElectroluxGasOven      MaytagMicrowave      WhirlpoolElectricRange\n+heat(...)             +cook(seconds, power) +bake(degrees, time)</pre>Each adapter's <code>heat()</code> translates the call (e.g. MaytagAdapter converts temperature/time to seconds/power and calls <code>cook()</code>).<br>3) <b>Reduced their coupling</b> — RoboChef now depends only on the Oven interface, not on ElectroluxGasOven.","e":"OOAD slide 21: Adapter converts the interface of a class into another interface clients expect; slide 22: Open/Closed — introduce new adapters without breaking client code.","from":[{"s":"M22b1","qn":"Q3.2","pg":5},{"s":"M21b","qn":"Q3.2","pg":4}]},{"id":"M22a-1-8","ch":5,"sl":"15","tp":"SRP violation","t":"mcq","q":"A block of code such as a class or method serving multiple different functionalities tends to violate which of the following?","o":["Single responsibility principle","Liskov substitution principle","Open/closed principle"],"a":0,"e":"OOAD slide 15: SRP — a class should have one and only one reason to change. Official key: a.","from":[{"s":"M22a","qn":"Q1.8"}]},{"id":"M22a-3-1","ch":5,"sl":"20–25","tp":"Match pattern to situation","t":"short","q":"Match the design pattern to the situation (each system has one pattern).<br><b>Patterns:</b> 1 Singleton · 2 Façade · 3 Observer · 4 Adapter · 5 Strategy<ol><li>You are building a system that relies on a complex algorithm, and that algorithm may be changed often due to marketing pressures.</li><li>Your company already implemented a component that almost implements the interface that you need, but not quite.</li><li>A cricket app notifies viewers about the current score, run rate etc. CricketData has all the data; whenever data changes, the display elements (CurrentScoreDisplay, AverageScoreDisplay) are notified with new data and display it.</li><li><code>public class PrintSpooler { private static final PrintSpooler instance = new PrintSpooler(); private PrintSpooler() {} public static PrintSpooler getInstance() { return instance; } }</code></li><li>Clients need a simplified interface to the overall functionality of a complex subsystem.</li></ol>","a":"<ol><li><b>Strategy</b> (5)</li><li><b>Adapter</b> (4)</li><li><b>Observer</b> (3)</li><li><b>Singleton</b> (1) — private constructor + static getInstance()</li><li><b>Façade</b> (2)</li></ol>","e":"Official model answer. OOAD slides 20–25 (Singleton, Adapter, Façade). Strategy and Observer are not in your deck.","from":[{"s":"M22a","qn":"Q3.1"}]},{"id":"M21a-1-5","ch":5,"sl":"15","tp":"Open/Closed principle","t":"mcq","q":"The Open/Closed design principle means:","o":["A class should have only one reason to change","A class can be extended but not modified","A class speaks to only friend classes","Substituting a subclass for a class should preserve correct program behavior"],"a":1,"e":"OOAD slide 15: \"Classes should be open for extension but closed for modification.\" (a = SRP, c = Demeter, d = Liskov.) Official key: b.","from":[{"s":"M21a","qn":"Q1.5","pg":2}]},{"id":"M21a-1-6","ch":5,"sl":"21","tp":"Delegation — Adapter","t":"mcq","q":"The __________ design pattern provides delegation of responsibility:","o":["Adapter","Singleton","Observer","Publisher-Subscriber"],"a":0,"e":"An Adapter <b>delegates</b> each client call to the adaptee object after converting the interface (OOAD slide 21). Official key: a.","from":[{"s":"M21a","qn":"Q1.6","pg":2}]},{"id":"M21a-2-4","ch":5,"sl":"13","tp":"True / False","t":"tf","q":"System sequence diagrams represent interactions of modules inside the software system.","a":1,"e":"A <b>system</b> sequence diagram treats the system as a black box and shows interactions between the external actors and the system — not the internal modules. Official key: F.","from":[{"s":"M21a","qn":"Q2.4","pg":3}]},{"id":"M21a-3","ch":5,"sl":"21, 22","tp":"Adapter — document printers","t":"short","q":"In a document-editing system, Document objects know how to print themselves using a <code>PostscriptPrinter</code> object. There are other types of printers with slightly different interfaces. Use a design pattern to refactor the design so different printers can be easily swapped.<br>1) Which pattern(s) and why? 2) Draw a design class diagram. 3) What effect did the new design have on the coupling between Document and PostscriptPrinter?","a":"1) <b>Adapter</b> (or Adapter + Strategy) — each printer has a slightly different interface; adapters convert them all to one <code>Printer</code> interface that Document uses, so printers can be swapped without changing Document.<br>2)<pre>Document ──uses──▶ «interface» Printer\n                     +print(doc)\n                         ▲ implements\n          ┌──────────────┼───────────────┐\n PostscriptAdapter   InkjetAdapter    LaserAdapter\n        │ adaptee        │ adaptee        │ adaptee\n PostscriptPrinter   InkjetPrinter    LaserPrinter</pre>3) <b>Reduced their coupling</b> — Document now depends only on the Printer interface.","e":"Official model answer: \"Adapter OR Adapter + Strategy\"; coupling: reduced. OOAD slides 21–22.","from":[{"s":"M21a","qn":"Q3","pg":3}]},{"id":"Q21-3a","ch":5,"sl":"7","tp":"Traceability matrix and participating actor","t":"short","q":"Fill in the blanks:<br>a) ______ is used to check that all requirements are covered by the use cases and to prioritize the work on use cases.<br>b) A(n) ______ is one of the use case's actors but does not initiate it.","a":"a) <b>Traceability matrix</b><br>b) <b>Participating actor</b>","e":"Quiz 3 model answer. OOAD slide 7: a use case is initiated by an actor; other actors participate.","from":[{"s":"Q21","qn":"Quiz 3 (sec 371) Q1"}]},{"id":"Q21-3b","ch":5,"sl":"20","tp":"Write a Singleton","t":"short","q":"Complete the following class to follow the Singleton design pattern:<pre>public final class Singleton {\n\n}</pre>","a":"<pre>public final class Singleton {\n    private static Singleton instance = new Singleton();\n    private Singleton() {}                 // nobody else can create one\n    public static Singleton getInstance() {\n        return instance;                   // global access point\n    }\n}</pre>","e":"Quiz 3 model answer. OOAD slide 20: Singleton restricts creation of more than one object of the class.","from":[{"s":"Q21","qn":"Quiz 3 (sec 371) Q2"}]},{"id":"Q21-3d","ch":5,"sl":"25","tp":"Match pattern to description","t":"short","q":"Match the design pattern with its description.<br><b>Patterns:</b> 1 Singleton · 2 Observer · 3 Façade · 4 Strategy · 5 Adapter<ol><li>Match interfaces of different classes</li><li>A single class that represents an entire subsystem</li><li>A way of notifying change to a number of classes</li><li>Encapsulates an algorithm inside a class</li></ol>","a":"<ol><li><b>5 Adapter</b></li><li><b>3 Façade</b></li><li><b>2 Observer</b></li><li><b>4 Strategy</b></li></ol>","e":"Quiz 3 model answer. OOAD slide 25 gives the Adapter and Façade definitions word for word.","from":[{"s":"Q21","qn":"Quiz 3 (sec 372) Q2"}]},{"id":"Q21-3e","ch":5,"sl":"13","tp":"Design sequence diagrams","t":"tf","q":"The design sequence diagrams represent interactions of external actors.","a":0,"e":"Official quiz key: True. (Compare Midterm 1 2021: <i>system</i> sequence diagrams do not show internal modules.) OOAD slide 13: sequence diagrams depict the interaction among objects over time.","from":[{"s":"Q21","qn":"Quiz 3 (sec 373) Q1a"}]},{"id":"Q21-3f","ch":5,"sl":"15, 24","tp":"Cohesion and coupling","t":"tf","q":"One of the goals in designing a system is to have low cohesion and high coupling.","a":1,"e":"The goal is the opposite: <b>high cohesion and low coupling</b> (OOAD slide 24: Façade gives low coupling between a subsystem and its clients).","from":[{"s":"Q21","qn":"Quiz 3 (sec 373) Q1b"}]},{"id":"Q21-3g","ch":5,"sl":"21","tp":"Adapter class diagram","t":"short","q":"Draw a class diagram for the Adapter design pattern.","a":"<pre>Client ──uses──▶ «interface» Target\n                    +request()\n                        ▲ implements\n                     Adapter ──adaptee──▶ Adaptee\n                    +request()            +specificRequest()\n                    { adaptee.specificRequest() }</pre>","e":"OOAD slide 21: convert the interface of a class into another interface clients expect.","from":[{"s":"Q21","qn":"Quiz 3 (sec 373) Q2"}]},{"id":"F26a-3-5","ch":6,"sl":"4, 14, 16, 24, 40","tp":"Match security terms","t":"short","q":"Choose the correct security engineering term for each description.<br><b>Terms:</b> Confidentiality · Integrity · Operational Security · Security Risk Assessment · Attack Detection and Elimination · Vulnerability Avoidance · Exposure Limitation and Recovery · Interception Threat · Modification Threat · Infrastructure Security · Security Design Guidelines<ol><li>Evaluating the possible losses that might result from attacks on the system</li><li>Balance security and usability where sometimes weaker security is accepted to make the system more usable</li><li>Designing the system so that security weaknesses do not occur</li><li>When an attacker gains unauthorized access to assets</li><li>Consequences and damage after a successful attack are minimised</li><li>Ensuring that information remains accurate and unaltered</li></ol>","a":"<ol><li><b>Security Risk Assessment</b></li><li><b>Security Design Guidelines</b></li><li><b>Vulnerability Avoidance</b></li><li><b>Interception Threat</b></li><li><b>Exposure Limitation and Recovery</b></li><li><b>Integrity</b></li></ol>","e":"1 → slide 24: risk assessment is \"assessing the possible losses that might ensue from attacks on the system\". 2 → slide 40, design guideline 4 \"Balance security and usability\". 3, 5 → slide 16 (security assurance): vulnerability avoidance / exposure limitation and recovery. 4 → slide 14: interception threats allow an attacker to gain access to an asset. 6 → slide 4: integrity — information must not be damaged or corrupted.","from":[{"s":"F26a","qn":"Q3 Part 2","pg":4}]},{"id":"F25b-2-3","ch":6,"sl":"12","tp":"Security terminology — threat","t":"mcq","q":"__________ means circumstances that have potential to cause loss or harm.","o":["Attack","Control","Threat","Vulnerability"],"a":2,"e":"Security slide 12: \"<b>Threat</b> — circumstances that have potential to cause loss or harm.\"","from":[{"s":"F25b","qn":"Q2.3","pg":2}]},{"id":"F25b-2-4","ch":6,"sl":"6","tp":"Protection levels","t":"mcq","q":"__________ : Protection that is invoked when access to specific information is requested.","o":["Platform-level","Record-level","Application-level","All of the above"],"a":1,"e":"Slide 6 (system layers where security may be compromised) comes from Sommerville ch. 13, which defines three protection levels: platform-level (the OS/platform), application-level (built into the application), and <b>record-level — protection invoked when access to specific information is requested</b>. <i>Note: the solved copy circled D, but only record-level matches this definition.</i>","from":[{"s":"F25b","qn":"Q2.4","pg":2}]},{"id":"F25b-2-8","ch":6,"sl":"39","tp":"Design guideline — fail securely","t":"mcq","q":"In design guidelines, __________ means when systems fail, for whatever reason, ensure that sensitive information cannot be accessed by unauthorized users.","o":["Avoid a single point of failure","Log user actions","Use redundancy and diversity","Fail securely"],"a":3,"e":"Security slide 39, guideline 3: \"<b>Fail securely</b> — when systems fail, for whatever reason, ensure that sensitive information cannot be accessed by unauthorized users.\"","from":[{"s":"F25b","qn":"Q2.8","pg":3}]},{"id":"F25b-3B","ch":6,"sl":"4, 5, 14, 15","tp":"Match security terms","t":"short","q":"Match each term with its description.<table class=\"mini\"><tr><th>Column A</th><th>Column B (descriptions)</th></tr><tr><td>1- Confidentiality</td><td>Ensuring that data remains accurate and unaltered</td></tr><tr><td>2- Integrity</td><td>Ensuring the security of networks, servers, and shared IT hardware</td></tr><tr><td>3- Interruption Threat</td><td>Ensuring that the system remains accessible when needed</td></tr><tr><td>4- Modification Threat</td><td>Ensuring that system information is not disclosed to unauthorized individuals</td></tr><tr><td>5- Infrastructure Security</td><td>Ensuring the security of individual software applications</td></tr><tr><td>6- Application Security</td><td>Tampering with or corrupting a system asset</td></tr><tr><td>7- Availability</td><td>Making a system unavailable</td></tr></table>","a":"<table class=\"mini\"><tr><th>Description</th><th>Term</th></tr><tr><td>Data remains accurate and unaltered</td><td><b>2 Integrity</b></td></tr><tr><td>Security of networks, servers, shared IT hardware</td><td><b>5 Infrastructure Security</b></td></tr><tr><td>System remains accessible when needed</td><td><b>7 Availability</b></td></tr><tr><td>Information not disclosed to unauthorized individuals</td><td><b>1 Confidentiality</b></td></tr><tr><td>Security of individual software applications</td><td><b>6 Application Security</b></td></tr><tr><td>Tampering with or corrupting a system asset</td><td><b>4 Modification Threat</b></td></tr><tr><td>Making a system unavailable</td><td><b>3 Interruption Threat</b></td></tr></table>","e":"Slide 4: security dimensions (confidentiality, integrity, availability). Slide 5: security levels (infrastructure, application, operational). Slides 14–15: interruption threats make part of the system unavailable; modification threats tamper with an asset.","from":[{"s":"F25b","qn":"Q3 Part B","pg":4}]},{"id":"F24c-1-4","ch":6,"sl":"44","tp":"Penetration testing","t":"mcq","q":"Which of the following best describes the process of actively attempting to gain unauthorized access to a system or network in order to identify and exploit vulnerabilities?","o":["Penetration testing","Regression testing","Load testing","Structural testing"],"a":0,"e":"Security slide 44: \"<b>Penetration testing</b> — a team is established whose goal is to breach the security of the system by simulating attacks on the system.\"","from":[{"s":"F24c","qn":"Q1.4","pg":7}]},{"id":"F24c-4-2a-1","ch":6,"sl":"14, 15","tp":"Classify the attack","t":"mcq","q":"A web-based banking application (use cases: Login, View Account, Transfer funds, Update profile) received this attack. Select its threat type:<br>Sniffing the network traffic between the user's web browser and the bank's server to intercept user login credentials or sensitive financial information.","o":["Interruption","Interception","Fabrication","Modification"],"a":1,"e":"The attacker <b>gains access</b> to an asset (credentials/financial data) — interception (slide 14).","from":[{"s":"F24c","qn":"Q4.2a.1","pg":6}]},{"id":"F24c-4-2a-2","ch":6,"sl":"14, 15","tp":"Classify the attack","t":"mcq","q":"A web-based banking application (use cases: Login, View Account, Transfer funds, Update profile) received this attack. Select its threat type:<br>Creating fake user accounts to gain access to the users' profile.","o":["Interruption","Interception","Fabrication","Modification"],"a":2,"e":"The attacker <b>inserts false information</b> (fake accounts) into the system — fabrication (slide 15).","from":[{"s":"F24c","qn":"Q4.2a.2","pg":6}]},{"id":"F24c-4-2a-3","ch":6,"sl":"14, 15","tp":"Classify the attack","t":"mcq","q":"A web-based banking application (use cases: Login, View Account, Transfer funds, Update profile) received this attack. Select its threat type:<br>Denial of Service (DoS) attack, where the attacker disrupts the availability of the banking application's services by overwhelming the system with excessive login requests.","o":["Interruption","Interception","Fabrication","Modification"],"a":0,"e":"Making part of the system <b>unavailable</b> — interruption (slide 14 gives a denial of service attack as the example).","from":[{"s":"F24c","qn":"Q4.2a.3","pg":6}]},{"id":"F24c-4-2a-4","ch":6,"sl":"14, 15","tp":"Classify the attack","t":"mcq","q":"A web-based banking application (use cases: Login, View Account, Transfer funds, Update profile) received this attack. Select its threat type:<br>Changing the permissions for their account so they can have access to more data.","o":["Interruption","Interception","Fabrication","Modification"],"a":3,"e":"The attacker <b>tampers with</b> a system asset (the permission settings) — modification (slide 15).","from":[{"s":"F24c","qn":"Q4.2a.4","pg":6}]},{"id":"F24c-4-2bc","ch":6,"sl":"14, 15, 24","tp":"Misuse cases and mitigation","t":"short","q":"For the banking system above (actor <i>user</i>; use cases Login, View Account, Transfer funds, Update profile):<br>b) Modify the use case diagram with the misuse cases from the four attacks. Draw a proper misuse case diagram.<br>c) Pick one attack, specify what asset it threatens and suggest a proper mitigation.","a":"b) Add an <b>Attacker</b> (misuser) actor outside the system and four <b>misuse cases</b> (usually drawn shaded/black), each linked to the use case it attacks with a <code>&lt;&lt;threaten&gt;&gt;</code> arrow:<ul><li><i>Sniff network traffic</i> —threatens→ Login (and View Account)</li><li><i>Create fake account</i> —threatens→ Login / Update profile</li><li><i>Flood with login requests (DoS)</i> —threatens→ Login</li><li><i>Change account permissions</i> —threatens→ Update profile / View Account</li></ul>Mitigations can be added as use cases that <code>&lt;&lt;mitigate&gt;&gt;</code> the misuse cases.<br>c) Example: <b>Sniffing</b> threatens the users' <b>login credentials and financial data</b> (confidentiality) → mitigate by encrypting all traffic (HTTPS/TLS) and using multi-factor authentication. Other examples: DoS → asset: service availability → rate limiting, CAPTCHA, traffic filtering; permission change → asset: account data → strict authorization checks and logging of user actions.","e":"Security slide 13 (asset/threat/control examples), slides 14–15 (threat types), slide 40 (log user actions) and slide 24 (risk assessment). The Final 2021 model answer used the same &lt;&lt;threaten&gt;&gt; notation.","from":[{"s":"F24c","qn":"Q4.2 b–c","pg":3}]},{"id":"F24b-1-1","ch":6,"sl":"14","tp":"Threat types","t":"mcq","q":"__________ threats allow an attacker to gain access to an asset.","o":["Interruption","Interception","Fabrication","Modification"],"a":1,"e":"Security slide 14: \"<b>Interception</b> threats that allow an attacker to gain access to an asset.\" Interruption = make part of the system unavailable; modification = tamper with an asset; fabrication = insert false information.","from":[{"s":"F24b","qn":"Q1.1","pg":1},{"s":"F23a","qn":"Q1.2"},{"s":"M21c","qn":"Q1.4","pg":2}]},{"id":"F24b-1-10","ch":6,"sl":"6","tp":"Layers of protection","t":"mcq","q":"Which of the following is a layer of protection for security?","o":["Platform-level protection","Application-level protection","Record-level protection","All of the above"],"a":3,"e":"Security slide 6 (system layers where security may be compromised): security is applied at the <b>platform</b> level, the <b>application</b> level and the <b>record</b> level — all three are layers of protection.","from":[{"s":"F24b","qn":"Q1.10","pg":2}]},{"id":"F24b-2-2","ch":6,"sl":"3","tp":"True / False","t":"tf","q":"Security engineering is only concerned with maintenance of systems such that they can resist malicious attacks.","a":1,"e":"Security slide 3: tools, techniques and methods to support the <b>development and maintenance</b> of systems that can resist malicious attacks — not only maintenance.","from":[{"s":"F24b","qn":"Q2.2","pg":3}]},{"id":"F24b-3","ch":6,"sl":"6, 8, 12, 44","tp":"Match security terms","t":"short","q":"Write the number of the appropriate definition in front of each term.<table class=\"mini\"><tr><th>Term</th><th>Definition</th></tr><tr><td>Vulnerability</td><td>1. Something of value which has to be protected. This may be the software system itself or data used by that system.</td></tr><tr><td>Application-level protection</td><td>2. System security testing by simulating attacks on the system.</td></tr><tr><td>System Reliability</td><td>3. A weakness in a computer-based system that may be exploited to cause loss or harm.</td></tr><tr><td>Asset</td><td>4. The probability that the system will correctly deliver services as expected by users.</td></tr><tr><td>Penetration testing</td><td>5. Possible loss or harm to a computing system (loss or damage to data, or loss of time and effort if recovery is necessary).</td></tr><tr><td>System Security</td><td>6. A judgment of how likely it is that the system will cause damage to people or its environment.</td></tr><tr><td>System Safety</td><td>7. Specific protection mechanisms built into the application itself, e.g. additional password protection.</td></tr><tr><td>Exposure</td><td>8. A judgment of how likely it is that the system can resist accidental or deliberate intrusions.</td></tr></table>","a":"<table class=\"mini\"><tr><th>Term</th><th>No.</th></tr><tr><td>Vulnerability</td><td><b>3</b></td></tr><tr><td>Application-level protection</td><td><b>7</b></td></tr><tr><td>System Reliability</td><td><b>4</b></td></tr><tr><td>Asset</td><td><b>1</b></td></tr><tr><td>Penetration testing</td><td><b>2</b></td></tr><tr><td>System Security</td><td><b>8</b></td></tr><tr><td>System Safety</td><td><b>6</b></td></tr><tr><td>Exposure</td><td><b>5</b></td></tr></table>","e":"Security slide 12: asset, exposure, vulnerability. Slide 44: penetration testing simulates attacks. Slide 6: application-level protection. Dependability slide 8: reliability, safety and security definitions.","from":[{"s":"F24b","qn":"Q3","pg":4}]},{"id":"F24a-3-4","ch":6,"sl":"4","tp":"Security dimensions","t":"short","q":"What are the three key security dimensions?","a":"<b>Confidentiality</b>, <b>Integrity</b>, <b>Availability</b> (CIA).","e":"Security slide 4: confidentiality — information may be disclosed to unauthorized people; integrity — information may be damaged or corrupted; availability — access to the system or its data may not be possible.","from":[{"s":"F24a","qn":"Q3.4","pg":6}]},{"id":"F24a-3-5","ch":6,"sl":"5, 7","tp":"Application security","t":"short","q":"What is application security primarily concerned with?","a":"Application security is concerned with the <b>security of individual application systems or related groups of systems</b>. It is a software engineering problem: the system is designed to resist attacks.","e":"Security slide 5 (security levels) and slide 7: \"Application security is a software engineering problem where the system is designed to resist attacks.\"","from":[{"s":"F24a","qn":"Q3.5","pg":6}]},{"id":"F24a-3-6","ch":6,"sl":"20, 24","tp":"Security risk assessment purpose","t":"short","q":"What is the purpose of security risk assessment?","a":"To <b>assess the possible losses that might ensue from attacks</b> on the system and <b>balance these losses against the costs of security procedures</b> that may reduce them — so that security decisions are made in a cost-effective way.","e":"Security slide 24: \"Risk assessment and management is concerned with assessing the possible losses that might ensue from attacks on the system and balancing these losses against the costs of security procedures.\" Slide 20: no point spending more than the asset's value.","from":[{"s":"F24a","qn":"Q3.6","pg":6}]},{"id":"F24a-3-7","ch":6,"sl":"39","tp":"Fail securely","t":"short","q":"What does 'fail securely' mean in security design?","a":"When systems fail, for whatever reason, ensure that <b>sensitive information cannot be accessed by unauthorized users</b> even though the normal security procedures are unavailable.","e":"Security slide 39, design guideline 3.","from":[{"s":"F24a","qn":"Q3.7","pg":6}]},{"id":"F24a-3-8","ch":6,"sl":"12","tp":"Threat","t":"short","q":"What is a 'threat' in security terminology?","a":"<b>Circumstances that have potential to cause loss or harm</b> — you can think of it as a system vulnerability that is subjected to an attack.","e":"Security slide 12 (security terminology).","from":[{"s":"F24a","qn":"Q3.8","pg":6}]},{"id":"F24a-3-9","ch":6,"sl":"15","tp":"Fabrication threat","t":"short","q":"What is a 'fabrication threat'?","a":"A threat that allows an attacker to <b>insert false information into a system</b> — e.g. adding false transactions to a banking system that transfer money to the attacker's account.","e":"Security slide 15, threat type 4.","from":[{"s":"F24a","qn":"Q3.9","pg":6}]},{"id":"F24a-3-10","ch":6,"sl":"44","tp":"Penetration testing","t":"short","q":"What is 'penetration testing'?","a":"A security validation technique in which <b>a team is established whose goal is to breach the security of the system by simulating attacks</b> on it.","e":"Security slide 44 (security validation): experience-based testing, penetration testing, tool-based analysis, formal verification.","from":[{"s":"F24a","qn":"Q3.10","pg":6}]},{"id":"F23c-1-5","ch":6,"sl":"44","tp":"Security validation techniques","t":"mcq","q":"Which testing technique may <b>not</b> be directly related to security verification?","o":["Unit testing","Experience-based testing","Penetration testing","Formal verification"],"a":0,"e":"Security slide 44 lists the security validation techniques: <b>experience-based testing, penetration testing, tool-based analysis and formal verification</b>. Unit testing checks individual components' functionality, not security.","from":[{"s":"F23c","qn":"Q1.5","pg":1}]},{"id":"F23b-1-2","ch":6,"sl":"28","tp":"Security requirement classification","t":"mcq","q":"When requirements set out how the system should be designed so that it can recover from and restore system assets after some loss has occurred, it is called:","o":["Risk avoidance","Risk mitigation","Risk detection","Risk prevention"],"a":1,"e":"Security slide 28: \"<b>Risk mitigation</b> requirements set out how the system should be designed so that it can recover from and restore system assets after some loss has occurred.\" Avoidance = risks cannot arise; detection = identify and neutralise the risk before losses occur.","from":[{"s":"F23b","qn":"Q1.2","pg":1},{"s":"F21a","qn":"Q1.3","pg":2}]},{"id":"F23b-1-4","ch":6,"sl":"12","tp":"Vulnerability","t":"mcq","q":"__________ is a weakness in a computer-based system that may be exploited to cause loss or harm.","o":["Asset","Attack","Control","Vulnerability"],"a":3,"e":"Security slide 12: \"<b>Vulnerability</b> — a weakness in a computer-based system that may be exploited to cause loss or harm.\"","from":[{"s":"F23b","qn":"Q1.4","pg":1}]},{"id":"F23b-4-1","ch":6,"sl":"26","tp":"Security vs safety specification","t":"short","q":"Security specification has something in common with safety requirements specification — in both cases your concern is to avoid something bad happening — but they are not the same. Provide two major differences.","a":"Any two:<ol><li>Safety problems are <b>accidental</b> — the software is not in a hostile environment. In security you must assume <b>attackers know the system's weaknesses</b>.</li><li>After a safety failure you can look for the root cause; after a deliberate attack <b>the attacker may conceal the cause</b>.</li><li><b>Shutting down</b> a system can avoid a safety-related failure, but causing a shutdown may be <b>the aim of an attack</b>.</li><li>Safety events are not generated by an intelligent adversary; an <b>attacker can probe defences over time</b> to discover weaknesses.</li></ol>","e":"Security slide 26 (Security specification — four major differences).","from":[{"s":"F23b","qn":"Q4 i","pg":6},{"s":"M22b2","qn":"Q2.1","pg":2}]},{"id":"F23b-4-2","ch":6,"sl":"14, 15","tp":"Misuse case threat types","t":"short","q":"In the misuse case diagram (Customer and Operator use cases; misuser <b>Crook</b> with misuse cases <i>Flood system</i>, <i>Steal card info</i>, <i>Tap communication</i>, <i>Obtain password</i>), specify the type of threat of two of the misuse cases.","a":"<b>Flood system</b> → <b>Interruption</b> (denial of service makes the system unavailable)<br><b>Steal card info</b> → <b>Interception</b> (gains access to an asset)<br><b>Tap communication</b> → <b>Interception</b><br><b>Obtain password</b> → <b>Interception</b> (which can then lead to modification or fabrication)","e":"Security slides 14–15: interception = gain access to an asset; interruption = make part of the system unavailable; modification = tamper with an asset; fabrication = insert false information.","from":[{"s":"F23b","qn":"Q4 ii","pg":6}],"img":"F23b_misuse.jpg"},{"id":"F23a-1-6","ch":6,"sl":"","tp":"Third-party library security","t":"mcq","q":"Scenario: a software development team is considering the integration of a third-party API library for image processing. What security practice should the team follow to ensure the library is safe to use?","o":["Conduct code reviews of the library","Implement strong access controls","Enforce secure coding standards","Apply patch management practices"],"a":0,"e":"Before trusting external code you must <b>inspect/review it</b> for vulnerabilities (experience-based review against known attacks, Security slide 44). Access controls and coding standards protect your own system/code, not the library. Official key: a.","from":[{"s":"F23a","qn":"Q1.6"}]},{"id":"F23a-4","ch":6,"sl":"12, 13","tp":"Security terminology — XYZ Corp","t":"short","q":"Scenario: XYZ Corp is concerned about the security of its sensitive customer data stored in an online database. Fill each blank with the most appropriate term (no duplication).<br><b>Terms:</b> Vulnerability · Asset · Privacy · Attack · Availability · Threat · Reliability · Modification · Impersonation · Control · Denial of service · Exposure<ol><li>______ : Online database contains information such as names, addresses, and credit card numbers of their customers.</li><li>______ : Attempts happened to gain unauthorized access to the online database.</li><li>______ : XYZ Corp implements multi-factor authentication and intrusion detection systems.</li><li>______ : Customer database is at risk or could be compromised.</li><li>______ : An unauthorized individual will make an attempt to breach the database.</li><li>______ : A weak password system which makes it easy to set guessable passwords.</li></ol>","a":"<ol><li><b>Asset</b></li><li><b>Attack</b></li><li><b>Control</b></li><li><b>Exposure</b></li><li><b>Threat</b></li><li><b>Vulnerability</b></li></ol>","e":"Security slide 12 (definitions) and slide 13 (Mentcare examples: weak password system = vulnerability; password checking = control). Official model answer.","from":[{"s":"F23a","qn":"Q4"}]},{"id":"M22b2-1-3","ch":6,"sl":"24","tp":"Operational risk assessment","t":"mcq","q":"The risk assessment process that focuses on the possible risks that can arise from human behaviour is:","o":["Operational risk assessment","Life cycle risk assessment","Preliminary risk assessment","Baseline risk assessment"],"a":0,"e":"Security slide 24: \"<b>Operational risk assessment</b>: possible risks that can arise from human behavior.\"","from":[{"s":"M22b2","qn":"Q1.3","pg":1}]},{"id":"M22b2-2-2","ch":6,"sl":"14, 15","tp":"Add a misuse case","t":"short","q":"Complete the <b>Online Shopping System</b> use case diagram (Customer; use cases View items, Make purchase, Complete checkout, Log in; external services Authentication, Identity Provider, Credit Payment Service, PayPal) to include one misuse case, then specify the type of threat of that misuse case.","a":"Example: add an <b>Attacker</b> actor with misuse case <b>Steal login info</b> linked to <i>Log in</i> by <code>&lt;&lt;threaten&gt;&gt;</code> → threat type <b>Interception</b> (unauthorized access to an asset).<br>Other valid examples: <i>Flood the system with requests</i> → Interruption; <i>Change order/payment details</i> → Modification; <i>Create fake orders/accounts</i> → Fabrication.","e":"Security slides 14–15 (the four threat types). Any misuse case is accepted if its threat type matches.","from":[{"s":"M22b2","qn":"Q2.2","pg":3}]},{"id":"Q22b-1","ch":6,"sl":"10, 17, 18","tp":"Robot at a fun park","t":"mcq","q":"A hacker was able to attack a robot operation via the network. The robot received a huge number of service requests, which caused it to crash under the heavy load. If the purpose of the robot is to entertain children with songs at a fun park, what is the most important requirement for the children that could not be compromised?","o":["Usability","Maintainability","Security","Testability"],"a":2,"e":"The robot was taken over through the network; if it can be attacked it may behave unpredictably around children. Security slide 10: \"Security is an essential pre-requisite for availability, reliability and <b>safety</b>\"; slide 18: an attack means assumptions about safety may not hold. Of the options, <b>security</b> is the one that protects the children.","from":[{"s":"Q22b","qn":"Q1"}]},{"id":"Q22b-3","ch":6,"sl":"12, 13","tp":"Match security terms to examples","t":"short","q":"Match each term with the appropriate example.<br><b>Terms:</b> Control · Attack · Vulnerability · Asset<ol><li>Ability to access the system without a username and password</li><li>Sending a virus through an e-mail attachment</li><li>Database of sales records</li><li>Scanning a system for viruses periodically</li></ol>","a":"<ol><li><b>Vulnerability</b></li><li><b>Attack</b></li><li><b>Asset</b></li><li><b>Control</b></li></ol>","e":"Security slide 12: vulnerability = a weakness that may be exploited; attack = exploitation of a vulnerability; asset = something of value to protect; control = a protective measure that reduces vulnerability.","from":[{"s":"Q22b","qn":"Q3"}]},{"id":"Q22b-4","ch":6,"sl":"14","tp":"Denial of service","t":"mcq","q":"A hacker was able to attack a robot operation via the network. The robot received a huge number of service requests, which placed a load on the robot's system and caused it to crash. What type of attack is this?","o":["Modification","Interruption","Interception","Fabrication"],"a":1,"e":"Security slide 14: \"<b>Interruption</b> threats allow an attacker to make part of the system unavailable — e.g. a denial of service attack.\"","from":[{"s":"Q22b","qn":"Q4"}]},{"id":"F21a-4-1","ch":6,"sl":"37, 40","tp":"Security vs usability trade-off","t":"short","q":"When designing software systems there can be trade-offs: a highly secure system may compromise usability and vice versa. Give an example of a <b>real system you used</b> that compromises between security and usability, state its main functionality, which feature is compromised, and why the compromise is necessary.","a":"<table class=\"mini\"><tr><th></th><th></th></tr><tr><td>Software name</td><td>e.g. Al Ahli (SNB) banking app</td></tr><tr><td>Functionality</td><td>Mobile banking</td></tr><tr><td>Compromised feature</td><td><b>Usability</b></td></tr><tr><td>Explanation</td><td>Sessions are very short: if the user is idle the app signs out automatically and asks for login + OTP again. This is annoying (less usable) but protects the user's financial information if the phone is left unattended.</td></tr></table>","e":"Security slide 37 (design compromises: security measures may require users to remember information or do extra interactions, making the system less usable) and slide 40 (guideline 4: balance security and usability). Any proper real example is accepted.","from":[{"s":"F21a","qn":"Q4.1","pg":6}]},{"id":"F21a-4-2","ch":6,"sl":"14, 15","tp":"Misuse case for an online shop","t":"short","q":"Complete the use case diagram (Customer: Register, Submit review, Order goods; Shop clerk: Prepare order) to include one misuse case, then specify the type of threat of that misuse case.","a":"Add an <b>Outside crook</b> actor with misuse cases linked by <code>&lt;&lt;threaten&gt;&gt;</code>, for example:<ul><li><i>Flood system</i> → threatens Order goods → <b>Interruption</b></li><li><i>Steal card info</i> → threatens Order goods → <b>Interception</b></li><li><i>Reveal customer info</i> → <b>Interception</b></li><li><i>Get privileges</i> / <i>Spread malicious code</i> → <b>Modification</b></li><li><i>Submit fake reviews</i> → <b>Fabrication</b></li></ul>","e":"Official model answer (answers vary). Security slides 14–15 define the four threat types.","from":[{"s":"F21a","qn":"Q4.2–3","pg":6}]},{"id":"M21c-1-1","ch":6,"sl":"4","tp":"Security dimensions","t":"mcq","q":"The three main dimensions of security engineering are:","o":["Confidentiality, Integrity, and Availability","Competence, Integrity, and Availability","Confidentiality, Integrity and Reliability","None of the above"],"a":0,"e":"Security slide 4: <b>Confidentiality, Integrity, Availability</b>. Official key: a.","from":[{"s":"M21c","qn":"Q1.1","pg":2}]},{"id":"M21c-1-3","ch":6,"sl":"12","tp":"Asset","t":"mcq","q":"Something of value which has to be protected. The ___ may be the software system itself or data used by that system:","o":["Asset","Attack","Control","Threat"],"a":0,"e":"Security slide 12: <b>Asset</b>. Official key: a.","from":[{"s":"M21c","qn":"Q1.3","pg":2}]},{"id":"M26b-4A-1","ch":7,"sl":"7, 8","tp":"Principal dependability properties","t":"short","q":"Mention four of the five principal dependability properties/attributes.","a":"Any four of: <b>Availability</b>, <b>Reliability</b>, <b>Safety</b>, <b>Security</b>, <b>Resilience</b>.","e":"Slide 7 shows the principal dependability properties diagram; slide 8 defines availability, reliability, safety and security. Resilience is the fifth property in the diagram (Sommerville ch. 10).","from":[{"s":"M26b","qn":"Q4 Part A.1","pg":5},{"s":"M25a","qn":"Q4 Part A.1","pg":4}]},{"id":"M26b-4A-2","ch":7,"sl":"13, 14","tp":"Fault → error → failure","t":"short","q":"What is the relation between System Fault, System Error, and System Failure?","a":"A human <b>mistake</b> introduces a <b>fault</b> (a characteristic of the software, e.g. buggy code). When the faulty code executes it can produce a <b>system error</b> (an erroneous system state). If the error is not corrected it can lead to a <b>system failure</b> (the system does not deliver the expected service).<br><b>Fault → Error → Failure</b> — but faults do not necessarily cause errors, and errors do not necessarily cause failures.","e":"Slide 13 (reliability terminology) and slide 14: \"Failures are usually a result of system errors that are derived from faults in the system. However, faults do not necessarily result in system errors … Errors do not necessarily lead to system failures.\"","from":[{"s":"M26b","qn":"Q4 Part A.2","pg":5}]},{"id":"M26b-4B","ch":7,"sl":"23, 24, 26, 31","tp":"POFOD, ROCOF, availability","t":"short","q":"An online shopping system processes 3,000 orders per day. During operation, the system experienced 12 failures (7 caused by system shutdowns and 5 due to incorrect order processing). On average, it takes 8 minutes to recover from each failure.<br>1) Calculate the POFOD.<br>2) Calculate the ROCOF per minute.<br>3) Calculate the Availability of the system.","a":"1) POFOD = failures / requests = 12 / 3000 = <b>0.004</b><br>2) One day = 24 × 60 = 1440 minutes → ROCOF = 12 / 1440 = <b>0.0083 failures per minute</b><br>3) Only the 7 shutdowns make the system unavailable: downtime = 7 × 8 = 56 min.<br>Availability = (1440 − 56) / 1440 = <b>0.961</b> (≈ 96.1%)<br><i>If your instructor counts all 12 failures as downtime: (1440 − 96) / 1440 = 0.933.</i>","e":"Slide 23: POFOD = failures / requests. Slide 24: ROCOF = failures over a period of time. Slide 26: availability = uptime / total time, and it \"does not tend to take incorrect computations (partial failures) into account\" — the same approach as the slide 31 activity, where only the system crashes (37 × 2 min) count as downtime.","from":[{"s":"M26b","qn":"Q4 Part B","pg":5}]},{"id":"F26a-3-1","ch":7,"sl":"13, 14","tp":"Fault vs failure","t":"short","q":"What is the difference between a <i>system fault</i> and a <i>system failure</i>?","a":"A <b>system fault</b> is a characteristic of the software (e.g. a bug in the code) that <i>can</i> lead to a system error. A <b>system failure</b> is an <i>event</i> that occurs at some point in time when the system does not deliver a service as expected by its users.<br>A fault does not necessarily cause a failure (the faulty code may never run, or the error may be corrected).","e":"Slide 13 (reliability terminology) defines fault, error and failure; slide 14: faults do not necessarily result in errors, and errors do not necessarily lead to failures.","from":[{"s":"F26a","qn":"Q3 Part 1.1","pg":3}]},{"id":"F26a-3-2","ch":7,"sl":"24","tp":"ROCOF calculation","t":"short","q":"Calculate the ROCOF of a system that experiences 12 failures during 240 hours of operation.","a":"ROCOF = failures / operating time = 12 / 240 = <b>0.05 failures per hour</b> (5 failures per 100 hours).","e":"Slide 24: ROCOF is the probable number of failures over a period of time — \"ROCOF of 0.02 means that 2 failures are likely per 100 time units\".","from":[{"s":"F26a","qn":"Q3 Part 1.2","pg":3}]},{"id":"F26a-3-3","ch":7,"sl":"25","tp":"Comparing MTBF","t":"short","q":"If system X has an MTBF = 250 hours, and system Y has an MTBF = 200 hours, which system is more reliable? Justify your answer by calculating how many failures occur in 1,000 hours for each system.","a":"Failures in 1,000 h: X = 1000 / 250 = <b>4 failures</b>; Y = 1000 / 200 = <b>5 failures</b>.<br><b>System X is more reliable</b> — it has a longer average time between failures, so fewer failures in the same period.","e":"Slide 25: MTBF measures the average length of time between observed failures; a longer MTBF means fewer failures. Number of failures = operating time / MTBF.","from":[{"s":"F26a","qn":"Q3 Part 1.3","pg":3}]},{"id":"F26a-3-4","ch":7,"sl":"3","tp":"Cost of failures","t":"short","q":"Software failures are costly. Mention two of the software failure cost impacts.","a":"Any two of: <b>Financial</b>, <b>Time</b>, <b>Lives</b>, <b>Reputation</b>.","e":"Slide 3 (Cost of software failures): \"Cost of software application failures impact: Financial, Time, Lives, Reputation.\"","from":[{"s":"F26a","qn":"Q3 Part 1.4","pg":3}]},{"id":"F25x-4","ch":7,"sl":"23, 24, 26, 30–32","tp":"Does the system meet the spec?","t":"short","q":"A critical medical image processing system processes 5,000 MRI scans per day. During a week of operation, the system encountered failures in 25 scans: 10 were due to hardware malfunctions and 15 were due to software errors. The average time to restore the system after hardware malfunctions is 8 minutes.<br>The customer's quality specification expects software availability above 97% and ROCOF per hour lower than 6%.<br>A) Does the system meet the customer quality specification and why?<br>B) Calculate: 1) POFOD 2) ROCOF in faults per hour 3) Availability.","a":"1) Requests in a week = 5000 × 7 = 35,000 → POFOD = 25 / 35000 = <b>0.00071</b><br>2) One week = 7 × 24 = 168 hours → ROCOF = 25 / 168 = <b>0.149 faults per hour (≈ 14.9%)</b><br>3) Downtime = 10 hardware failures × 8 min = 80 min; one week = 10,080 min → Availability = (10080 − 80) / 10080 = <b>0.992 (99.2%)</b><br>A) <b>No.</b> Availability (99.2%) is above 97%, but ROCOF (14.9% per hour) is far above the 6% limit — so the system does not meet the specification.","e":"Same method as the Dependability slides 30–32 activity: compute ROCOF over the operating time, POFOD over the requests, availability from downtime; the product ships only if <i>every</i> requirement is met (slide 32: \"Availability/POFOD are good, but ROCOF is too low\").","from":[{"s":"F25x","qn":"Q4","pg":9}]},{"id":"F25b-2-1","ch":7,"sl":"8","tp":"Reliability definition","t":"mcq","q":"__________ : The probability that the system will correctly deliver services as expected by users.","o":["Reliability","Availability","Security","Robustness"],"a":0,"e":"Dependability slide 8: \"<b>Reliability</b> — the probability that the system will correctly deliver services as expected by users.\" Availability is the probability the system is up and running.","from":[{"s":"F25b","qn":"Q2.1","pg":2}]},{"id":"F25b-2-7","ch":7,"sl":"15","tp":"Types of system failure","t":"mcq","q":"__________ happens when the system does not deliver a service correctly to users.","o":["Loss of service","Incorrect service delivery","System/data corruption","Human error"],"a":1,"e":"Dependability slide 15: \"<b>Incorrect service delivery</b> — the system does not deliver a service correctly to users.\" Loss of service = system unavailable; data corruption = damage to the system or its data.","from":[{"s":"F25b","qn":"Q2.7","pg":2}]},{"id":"F25b-3A-1","ch":7,"sl":"7","tp":"Five dependability properties","t":"short","q":"List the five principal dependability quality attributes of a system.","a":"<b>Availability</b>, <b>Reliability</b>, <b>Safety</b>, <b>Security</b>, <b>Resilience</b>.","e":"Dependability slide 7 (principal dependability properties diagram): availability — deliver services when requested; reliability — deliver services as specified; safety — operate without catastrophic failure; security — protect itself against intrusion; resilience — resist and recover from damaging events.","from":[{"s":"F25b","qn":"Q3 Part A.1","pg":4},{"s":"F24a","qn":"Q3.1","pg":6}]},{"id":"F25b-3A-2","ch":7,"sl":"23","tp":"POFOD calculation","t":"short","q":"Calculate the POFOD if a system fails 40 times out of 10000 requests during 8 hours runtime.","a":"POFOD = failures / requests = 40 / 10000 = <b>0.004</b> (= 1/250). The 8 hours is not needed for POFOD.","e":"Slide 23: POFOD is the likelihood that a service request will result in a failure (failures / requests). It is independent of time.","from":[{"s":"F25b","qn":"Q3 Part A.2","pg":4}]},{"id":"F25b-3A-3","ch":7,"sl":"25","tp":"MTBF meaning","t":"short","q":"What does the reliability metric 'Mean Time Between Failures (MTBF)' measure?","a":"The <b>average length of time between observed failures</b> (MTBF = total operating time / number of failures). It requires the timestamp of each failure and of when the system resumed service.","e":"Slide 25: \"Measures the average length of time between observed failures. Requires the timestamp of each failure and the timestamp of when the system resumed service.\"","from":[{"s":"F25b","qn":"Q3 Part A.3","pg":4},{"s":"F24a","qn":"Q3.3","pg":6}]},{"id":"M25b-4A-1","ch":7,"sl":"4","tp":"Causes of failure","t":"short","q":"What are the three main causes of failure?","a":"1) <b>Hardware failure</b> — design/manufacturing errors or components reaching the end of their life.<br>2) <b>Software failure</b> — errors in specification, design or implementation.<br>3) <b>Operational failure</b> — human operators make mistakes (now perhaps the largest single cause).","e":"Dependability slide 4 (Causes of failure).","from":[{"s":"M25b","qn":"Q4 Part A.1","pg":6}]},{"id":"M25b-4A-2","ch":7,"sl":"8, 26","tp":"Availability definition","t":"short","q":"What is the definition of availability?","a":"Availability is <b>the probability that the system will be up and running and able to deliver useful services to users</b> at a given time (availability = uptime / total time).","e":"Dependability slide 8 (principal properties) and slide 26 (uptime / total time; takes repair and restart time into account).","from":[{"s":"M25b","qn":"Q4 Part A.2","pg":6}]},{"id":"M25b-4B","ch":7,"sl":"23, 24, 26, 31","tp":"POFOD, ROCOF, availability","t":"short","q":"Your system processes 12,000 requests per week. During testing, it failed on 18 requests (12 due to system crashes and 6 due to incorrect outputs). The average repair time after a system crash is 5 minutes.<br>1) Calculate the POFOD.<br>2) Calculate the ROCOF in minutes.<br>3) Calculate the Availability for the system.","a":"1) POFOD = 18 / 12000 = <b>0.0015</b><br>2) One week = 7 × 24 × 60 = 10,080 minutes → ROCOF = 18 / 10080 = <b>0.0018 failures per minute</b><br>3) Downtime = 12 crashes × 5 min = 60 min → Availability = (10080 − 60) / 10080 = <b>0.994</b> (≈ 99.4%)","e":"Slides 23–24: POFOD = failures / requests, ROCOF = failures / time. Slide 26: availability = uptime / total time — only crashes cause downtime (same method as the slide 31 activity).","from":[{"s":"M25b","qn":"Q4 Part B","pg":6}]},{"id":"M25a-4A-2","ch":7,"sl":"16","tp":"Fault tolerance","t":"short","q":"What is the meaning of fault tolerance?","a":"Fault tolerance means that the <b>system can continue in operation in spite of software failure</b> (faults). It is required where there are high availability requirements or where failure costs are very high.","e":"Dependability slide 16: \"Fault tolerance means that the system can continue in operation in spite of software failure.\"","from":[{"s":"M25b","qn":"Q4 Part A.3","pg":6},{"s":"M25a","qn":"Q4 Part A.2","pg":4},{"s":"F24a","qn":"Q3.2","pg":6}]},{"id":"M25a-4B","ch":7,"sl":"23, 24, 26, 31","tp":"POFOD, ROCOF, availability","t":"short","q":"A banking application handles 2,500 transactions per day. While the system gets into operation, it recorded 8 total failures (5 caused by unexpected shutdowns and 3 due to incorrect processing results). On average, it takes 10 minutes to restart after a shutdown.<br>1) Calculate the POFOD.<br>2) Calculate the ROCOF in minutes.<br>3) Calculate the Availability of the system.","a":"1) POFOD = 8 / 2500 = <b>0.0032</b><br>2) One day = 1440 minutes → ROCOF = 8 / 1440 = <b>0.0056 failures per minute</b><br>3) Downtime = 5 shutdowns × 10 min = 50 min → Availability = (1440 − 50) / 1440 = <b>0.965</b> (≈ 96.5%)","e":"Slide 23: POFOD = failures / requests. Slide 24: ROCOF = failures / time. Slide 26: availability = uptime / total time; only the shutdowns make the system unavailable (incorrect results are partial failures, as in the slide 31 activity).","from":[{"s":"M25a","qn":"Q4 Part B","pg":4}]},{"id":"F24c-1-1","ch":7,"sl":"4","tp":"Causes of failure","t":"mcq","q":"When human operators make mistakes in using the software system, we consider this failure as:","o":["Hardware failure","Operational failure","Software failure","None of the above"],"a":1,"e":"Dependability slide 4: \"<b>Operational failure</b> — human operators make mistakes. Now perhaps the largest single cause of system failures.\"","from":[{"s":"F24c","qn":"Q1.1","pg":7}]},{"id":"F24c-1-6","ch":7,"sl":"8","tp":"Most important dependability factor","t":"mcq","q":"A restaurant has a beeping device at each table that customers use to know when their orders are ready. Which dependability factor is most important?","o":["Availability","Safety","Scalability","Security"],"a":0,"e":"The device just has to be up and able to deliver its service (beep) whenever an order is ready → <b>availability</b> (Dependability slide 8). It cannot harm people (safety) and holds no sensitive data (security); scalability is not a dependability property.","from":[{"s":"F24c","qn":"Q1.6","pg":7}]},{"id":"F24c-5-1","ch":7,"sl":"23, 24, 26, 30–32","tp":"Is the product ready to ship?","t":"short","q":"A company developed an application for managing customer orders. Customer requirements:<ol><li>Availability: at least 99%</li><li>POFOD: less than 0.1</li><li>ROCOF: less than 2 failures per 8-hour work period</li></ol>After testing for <b>10 days</b>: total requests 2,500; total failures 120 (80 software crashes, 40 data corruption issues); average restart time after a failure 5 minutes.<br>a) Calculate the availability, POFOD, and ROCOF.<br>b) Can the MTBF be calculated? If so, calculate it.<br>c) Is the product ready to ship? Explain.","a":"Total time = 10 × 24 = 240 h = 14,400 min.<br>a) <b>Availability:</b> downtime = 80 crashes × 5 min = 400 min → (14400 − 400) / 14400 = <b>0.972</b> (97.2%). <i>(If all 120 failures are counted: 600 min → 0.958.)</i><br><b>POFOD</b> = 120 / 2500 = <b>0.048</b><br><b>ROCOF</b> = 120 / 240 h = 0.5 per hour = <b>4 failures per 8-hour period</b><br>b) <b>No</b> — MTBF needs the timestamp of each failure and of when service resumed; we only know the average restart time, not when each failure happened.<br>c) <b>No.</b> POFOD (0.048 &lt; 0.1) is fine, but availability (97.2% &lt; 99%) and ROCOF (4 &gt; 2 per 8 h) do not meet the requirements.","e":"This mirrors the Dependability slides 30–32 activity exactly: compute ROCOF per work period, POFOD per request, availability from crash downtime; \"Can we calculate MTBF? No — need timestamps.\"","from":[{"s":"F24c","qn":"Q5.1","pg":8}]},{"id":"F24c-5-2-1","ch":7,"sl":"16, 17","tp":"Fault handling type","t":"mcq","q":"A smart home system controls appliances and devices. It can leverage fault tolerance, fault avoidance and fault detection. Which type of fault handling is this action?<br>The system has backup power sources, such as a battery backup, to keep critical devices running during power outages.","o":["Fault tolerance","Fault avoidance","Fault detection"],"a":0,"e":"The system <b>keeps operating despite the failure</b> → fault tolerance (Dependability slide 16).","from":[{"s":"F24c","qn":"Q5.2.1","pg":8}]},{"id":"F24c-5-2-2","ch":7,"sl":"16, 17","tp":"Fault handling type","t":"mcq","q":"A smart home system controls appliances and devices. It can leverage fault tolerance, fault avoidance and fault detection. Which type of fault handling is this action?<br>Sensors throughout the house monitor for issues like water leaks, unusual temperature changes, or abnormal power consumption.","o":["Fault tolerance","Fault avoidance","Fault detection"],"a":2,"e":"Monitoring to <b>discover</b> problems → fault detection (slide 17, reliability achievement).","from":[{"s":"F24c","qn":"Q5.2.2","pg":8}]},{"id":"F24c-5-2-3","ch":7,"sl":"16, 17","tp":"Fault handling type","t":"mcq","q":"A smart home system controls appliances and devices. It can leverage fault tolerance, fault avoidance and fault detection. Which type of fault handling is this action?<br>Software updates are automatically applied to fix known vulnerabilities and improve the system's reliability.","o":["Fault tolerance","Fault avoidance","Fault detection"],"a":1,"e":"Fixing known weaknesses <b>before</b> they can cause errors or failures prevents faults from occurring in operation → fault avoidance (slide 17).","from":[{"s":"F24c","qn":"Q5.2.3","pg":8}]},{"id":"F24b-1-3","ch":7,"sl":"17","tp":"Reliability achievement","t":"mcq","q":"What is the term for a development process organised such that faults in the system are detected and repaired before delivery to the customer?","o":["Fault avoidance","Fault detection","Fault tolerance","None of the mentioned"],"a":1,"e":"Dependability slide 17 (reliability achievement): <b>fault avoidance</b> — development techniques that minimise the possibility of mistakes; <b>fault detection (and removal)</b> — verification and validation techniques that discover and remove faults <i>before the system is delivered</i>; <b>fault tolerance</b> — run-time techniques so faults do not cause failures.","from":[{"s":"F24b","qn":"Q1.3","pg":1}]},{"id":"F24b-1-6","ch":7,"sl":"13","tp":"Reliability terminology","t":"mcq","q":"A characteristic of a software system that can lead to a system error is known as?","o":["Human error or mistake","System fault","System error","System failure"],"a":1,"e":"Dependability slide 13: \"<b>System fault</b> — a characteristic of a software system that can lead to a system error.\"","from":[{"s":"F24b","qn":"Q1.6","pg":1}]},{"id":"F24b-1-8","ch":7,"sl":"4","tp":"Causes of failure","t":"mcq","q":"Operational failure means:","o":["Hardware fails because of design and manufacturing errors","Software fails due to errors in its specification, design or implementation","Human operators make mistakes","All of the above"],"a":2,"e":"Dependability slide 4: \"<b>Operational failure</b> — human operators make mistakes.\" (a) is hardware failure, (b) is software failure.","from":[{"s":"F24b","qn":"Q1.8","pg":2}]},{"id":"F24b-1-9","ch":7,"sl":"24","tp":"ROCOF","t":"mcq","q":"Which reliability metric sets out the probable number of system failures that are likely to be observed relative to a certain time period?","o":["POFOD","ROCOF","MTBF","AVAIL"],"a":1,"e":"Dependability slide 24: ROCOF — \"probable number of failures over a period of time or number of system executions.\"","from":[{"s":"F24b","qn":"Q1.9","pg":2}]},{"id":"F24b-2-4","ch":7,"sl":"3, 6","tp":"True / False","t":"tf","q":"Dependability is not relevant in non-critical systems, as failures in such systems do not have significant consequences.","a":1,"e":"Dependability slide 3: failures cost money, time, lives and reputation; slide 6: dependability reflects the user's trust in <i>any</i> system.","from":[{"s":"F24b","qn":"Q2.4","pg":3}]},{"id":"F24b-2-5","ch":7,"sl":"25","tp":"True / False","t":"tf","q":"Mean Time Between Failures (MTBF) is a measure of reliability, representing the average time a system operates before a failure occurs.","a":0,"e":"Dependability slide 25: MTBF \"measures the average length of time between observed failures.\"","from":[{"s":"F24b","qn":"Q2.5","pg":3}]},{"id":"F24b-2-8","ch":7,"sl":"16","tp":"True / False","t":"tf","q":"A fault-tolerant system requires manual intervention to recover from faults.","a":1,"e":"Dependability slide 16: fault tolerance means the system <b>can continue in operation</b> in spite of software failure — automatically.","from":[{"s":"F24b","qn":"Q2.8","pg":3}]},{"id":"F24b-5-1","ch":7,"sl":"23","tp":"Most critical dependability attribute","t":"mcq","q":"Choose the most appropriate dependability attribute that is crucial to the system:<br>In a railway signalling system, the primary focus is to control the movement of trains and ensure safety on the tracks. It is essential to minimize the risk of signalling failures that could lead to accidents or disruptions in train operations. The system must undergo rigorous testing and continuous monitoring to ensure the reliable and safe operation of railway traffic.","o":["POFOD","ROCOF","Availability"],"a":0,"e":"A signalling/protection system is called on when a train approaches — a failure <i>on demand</i> could cause an accident. Slide 23: POFOD \"should be used as a reliability metric in situations where a failure on request is serious.\"","from":[{"s":"F24b","qn":"Q5.1","pg":5}]},{"id":"F24b-5-2","ch":7,"sl":"8, 26","tp":"Most critical dependability attribute","t":"mcq","q":"Choose the most appropriate dependability attribute that is crucial to the system:<br>An Internet server provided by an ISP (Internet Service Provider) with thousands of customers.","o":["Security","Safety","Availability"],"a":2,"e":"Thousands of customers depend on the server being up and able to deliver its services at any time → <b>availability</b> (slide 8). Official model answer (Final 1st 2024): Availability.","from":[{"s":"F24b","qn":"Q5.2","pg":5},{"s":"F23a","qn":"Q5.6"}]},{"id":"F24b-5-3","ch":7,"sl":"8","tp":"Most critical dependability attribute","t":"mcq","q":"Choose the most appropriate dependability attribute that is crucial to the system:<br>In a data management system of a financial institution, the system is dedicated to preserving the integrity of data while preventing any unauthorized exposure.","o":["Security","Safety","Availability"],"a":0,"e":"Integrity and preventing unauthorized exposure are security concerns — slide 8: security is how likely the system can resist accidental or deliberate intrusions. Official model answer: Security.","from":[{"s":"F24b","qn":"Q5.3","pg":5},{"s":"F23a","qn":"Q5.4"}]},{"id":"F24b-5-4","ch":7,"sl":"8","tp":"Most critical dependability attribute","t":"mcq","q":"Choose the most appropriate dependability attribute that is crucial to the system:<br>In a hospital patient monitoring system, the main goal is to continuously track patients' vital signs such as heart rate, blood pressure, and oxygen levels. It ensures that healthcare professionals have real-time access to vital patient data, enabling timely interventions and improving patient care.","o":["Security","Safety","Availability"],"a":2,"e":"The description stresses <b>continuous</b> tracking and <b>real-time access</b> — the system must be up and able to deliver its service whenever needed → availability (slide 8). <i>Some students argue Safety because patients could be harmed; the wording here points to availability.</i>","from":[{"s":"F24b","qn":"Q5.4","pg":5}]},{"id":"F24b-5-5","ch":7,"sl":"26, 29","tp":"Availability calculation","t":"mcq","q":"A power plant operates continuously with a significant system impact upon failure. After 8050 total service requests in one year (8760 hours), with 5 failures and an average repair time of 5 hours per failure, the availability of the power plant ≈","o":["0.9994","0.00062","0.00057","0.9971"],"a":3,"e":"Downtime = 5 failures × 5 h = 25 h. Availability = (8760 − 25) / 8760 = 8735 / 8760 = <b>0.9971</b>. Same method as Dependability slide 29.","from":[{"s":"F24b","qn":"Q5.5","pg":5}]},{"id":"F24b-5-6","ch":7,"sl":"24","tp":"ROCOF calculation","t":"mcq","q":"Same power plant (8050 requests in 8760 hours, 5 failures, 5 hours average repair). The Rate of Occurrence of Failure (ROCOF) ≈","o":["0.9994","0.00062","0.00057","0.9971"],"a":2,"e":"ROCOF = failures / time = 5 / 8760 = <b>0.00057</b> failures per hour (slide 24). Note 0.00062 = 5 / 8050 is the POFOD (failures per request).","from":[{"s":"F24b","qn":"Q5.6","pg":5}]},{"id":"M24a-4A","ch":7,"sl":"13","tp":"Fault, error, failure with examples","t":"short","q":"What is the difference among system fault, system error, and system failure? Give examples for your answer.","a":"<b>System fault</b> — a characteristic of the software that can lead to an error. <i>Example: code that adds 1 hour to the last transmission time without checking if the time is ≥ 23:00.</i><br><b>System error</b> — an erroneous system state that can lead to unexpected behaviour. <i>Example: the transmission time is set to 24:XX instead of 00:XX.</i><br><b>System failure</b> — an event where the system does not deliver a service as users expect. <i>Example: no weather data is transmitted because the time is invalid.</i>","e":"Dependability slide 13 (reliability terminology — the wilderness weather station example).","from":[{"s":"M24a","qn":"Q4 A","pg":5}]},{"id":"M24a-4B","ch":7,"sl":"23–26, 30–32","tp":"Is the product ready to ship?","t":"short","q":"Your customers want an availability of at least 99%, a POFOD of less than 0.1, and a ROCOF of less than 2 failures per 8-hour work period.<br>After testing your code for 10 full days, 1500 requests were made. The product failed 70 times (45 system crashes, 25 bad calculations) and it took an average of 2 minutes to restart after each failure.<br>1) Calculate the availability. 2) Calculate POFOD. 3) Calculate ROCOF. 4) Can we calculate MTBF? 5) Is the product ready to ship, and why?","a":"10 days = 240 h = 14,400 min.<br>1) Downtime = 45 crashes × 2 min = 90 min → Availability = (14400 − 90) / 14400 = <b>0.994</b> (99.4%)<br>2) POFOD = 70 / 1500 = <b>0.047</b><br>3) ROCOF = 70 / 240 h = 0.29 per hour = <b>2.33 failures per 8-hour period</b><br>4) <b>No</b> — we need the timestamp of each failure; we only know the average restart time.<br>5) <b>No.</b> Availability (99.4%) and POFOD (0.047) are good, but ROCOF (2.33 per 8 h) is above the required 2.","e":"Identical method to the Dependability slides 30–32 activity (64 failures in 7 days, 37 crashes × 2 min, \"No — need timestamps\", \"ROCOF is too low\").","from":[{"s":"M24a","qn":"Q4 B","pg":5}]},{"id":"F23c-1-2","ch":7,"sl":"13","tp":"Human error","t":"mcq","q":"A characteristic of human behaviour that results in the introduction of faults into a system is a:","o":["Human error or mistake","System fault","System error","System failure"],"a":0,"e":"Dependability slide 13: \"<b>Human error or mistake</b> — human behavior that results in the introduction of faults into a system.\"","from":[{"s":"F23c","qn":"Q1.2","pg":1}]},{"id":"F23c-3","ch":7,"sl":"16, 25, 26","tp":"Hospital system — MTBF and availability","t":"short","q":"You are developing a software system that is critical to the operation of a hospital (patient records, appointments, medical payments). After extensive testing, the system has a mean time between failures (MTBF) of 200 hours. Each failure takes an average of 30 minutes to repair. Additionally, a fault-tolerance mechanism allows the system to continue functioning even if a single component fails, with a mean time to repair (MTTR) of 5 minutes. Assume the system operates 24/7 and failures are independent.<br>1) Approximately how many times would you expect the system to fail in a month?<br>2) What is the availability of the system? (formula + calculation)<br>3) How does the fault-tolerance mechanism affect the system's reliability and dependability?<br>4) Can you calculate the POFOD of the system?","a":"1) A month ≈ 30 × 24 = 720 h → 720 / 200 ≈ <b>3.6, i.e. about 3–4 failures per month</b>.<br>2) Availability = MTBF / (MTBF + MTTR).<br>Without fault tolerance: 200 / (200 + 0.5) = <b>0.9975</b> (99.75%).<br>With fault tolerance (MTTR = 5 min = 0.083 h): 200 / (200 + 0.083) = <b>0.9996</b> (99.96%).<br>3) Fault tolerance lets the system <b>keep operating in spite of a component failure</b>, so downtime drops from 30 to 5 minutes — availability and dependability increase and users experience fewer service failures (higher perceived reliability). It does not reduce the number of underlying faults.<br>4) <b>No</b> — POFOD = failures / requests, and the number of requests is not given.","e":"Dependability slide 16 (fault tolerance), slide 25 (MTBF), slide 26 (availability takes repair time into account), slide 23 (POFOD needs the number of requests).","from":[{"s":"F23c","qn":"Q3.2","pg":4}]},{"id":"F23b-1-7","ch":7,"sl":"7, 8","tp":"Principal dependability properties","t":"mcq","q":"Principal dependability properties are:","o":["Usability, Portability, Reliability and Resilience","Safety, Security, Complexity and Reliability","Availability, Safety, Security and Reliability","Availability, Reliability, Usability and Complexity"],"a":2,"e":"Dependability slide 8 (principal properties): <b>Availability, Reliability, Safety, Security</b> (resilience is the fifth on slide 7).","from":[{"s":"F23b","qn":"Q1.7","pg":3}]},{"id":"F23b-3a-i","ch":7,"sl":"8","tp":"Most critical dependability attribute","t":"mcq","q":"Which dependability attribute is the most critical for this system?<br>A digital calculator","o":["Security","Safety","Reliability"],"a":2,"e":"A calculator must give <b>correct results</b> — it holds no secrets and cannot harm anyone → reliability (slide 8).","from":[{"s":"F23b","qn":"Q3 a.i","pg":4}]},{"id":"F23b-3a-ii","ch":7,"sl":"8","tp":"Most critical dependability attribute","t":"mcq","q":"Which dependability attribute is the most critical for this system?<br>An Internet-based personal finance management system","o":["Availability","Security","Safety"],"a":1,"e":"It stores sensitive financial data and is exposed on the Internet → <b>security</b> (slide 8; Security slide 10: networked systems need security).","from":[{"s":"F23b","qn":"Q3 a.ii","pg":4}]},{"id":"F23b-3a-iii","ch":7,"sl":"8","tp":"Most critical dependability attribute","t":"mcq","q":"Which dependability attribute is the most critical for this system?<br>A system to control a refrigeration unit for home owners' use","o":["Security","Safety","Availability"],"a":2,"e":"It must keep running to keep the food cold; it is not safety-critical → <b>availability</b> (the Midterm 2 2021 model answer gives the same: refrigeration unit → availability).","from":[{"s":"F23b","qn":"Q3 a.iii","pg":4}]},{"id":"F23b-3a-iv","ch":7,"sl":"8","tp":"Most critical dependability attribute","t":"mcq","q":"Which dependability attribute is the most critical for this system?<br>A roller-coaster at a theme park","o":["Availability","Security","Safety"],"a":2,"e":"A failure could injure or kill riders → <b>safety</b> (slide 8: how likely the system will cause damage to people).","from":[{"s":"F23b","qn":"Q3 a.iv","pg":4}]},{"id":"F23b-3b","ch":7,"sl":"13, 16, 17","tp":"Match term to example","t":"short","q":"Match each term with the most appropriate example.<table class=\"mini\"><tr><th>Term</th><th>Example</th></tr><tr><td>1. Human error</td><td>You got an oil temperature warning in your car.</td></tr><tr><td>2. System failure</td><td>A train protection system automatically applies the brakes of a train if the speed limit for a segment of track is exceeded.</td></tr><tr><td>3. Fault detection</td><td>Loss of service in your system.</td></tr><tr><td>4. Fault tolerance</td><td>A car driver forgetting to set the park brake in his car.</td></tr></table>","a":"<table class=\"mini\"><tr><th>Term</th><th>Example</th></tr><tr><td>Human error</td><td><b>A car driver forgetting to set the park brake</b></td></tr><tr><td>System failure</td><td><b>Loss of service in your system</b></td></tr><tr><td>Fault detection</td><td><b>Oil temperature warning in your car</b></td></tr><tr><td>Fault tolerance</td><td><b>Train protection system automatically applies the brakes</b> (the system protects itself and keeps operating safely when a dangerous condition occurs)</td></tr></table>","e":"Dependability slide 13: human error = human behaviour that introduces faults; slide 15: loss of service is a type of system failure; slides 16–17: fault detection discovers problems, fault tolerance keeps the system operating in spite of faults.","from":[{"s":"F23b","qn":"Q3 b","pg":5}]},{"id":"F23b-3c","ch":7,"sl":"23–26","tp":"MTBF, availability, POFOD, ROCOF","t":"short","q":"An operating system (OS) was tested for 30 days. 4165 requests were made and it crashed on average once in 30 days and had 91 wrong results in total. When a system crash occurs, the Mean Time To Repair (MTTR) is 12 hours. Calculate MTBF, availability, POFOD and ROCOF.","a":"30 days = 720 hours; failures = 1 crash + 91 wrong results = 92.<br><b>MTBF</b> = 720 / 1 crash = <b>720 hours</b> (time between crashes)<br><b>Availability</b> = MTBF / (MTBF + MTTR) = 720 / 732 = <b>0.984</b> (or (720 − 12) / 720 = 0.983)<br><b>POFOD</b> = 92 / 4165 = <b>0.022 failures/request</b><br><b>ROCOF</b> = 92 / 720 = <b>0.128 failures/hour</b>","e":"Slide 23: POFOD = failures / requests; slide 24: ROCOF = failures / time; slide 25: MTBF = time between failures; slide 26: availability = uptime / total time (MTBF / (MTBF + MTTR), as in the Midterm 2 2021 model answer). Only the crash makes the system unavailable.","from":[{"s":"F23b","qn":"Q3 c","pg":5}]},{"id":"F23a-1-7","ch":7,"sl":"26, 29","tp":"Availability calculation","t":"mcq","q":"A server crashes on average once in 30 days. When this happens, it takes 12 hours to reboot it. What is the availability of the server?","o":["0.983","0.017","0.996","0.4"],"a":0,"e":"30 days = 720 h. Uptime = 720 − 12 = 708 h → Availability = 708 / 720 = <b>0.983</b>. (0.017 is the unavailability.) Same method as Dependability slide 29. Official key: a.","from":[{"s":"F23a","qn":"Q1.7"}]},{"id":"F23a-1-8","ch":7,"sl":"25","tp":"MTBF","t":"mcq","q":"In the context of dependability properties, what does \"MTBF\" stand for?","o":["Mean Time Between Failures","Maximum Time for Backup","Minimum Time for Recovery","Most Time for Buffering"],"a":0,"e":"Dependability slide 25: <b>Mean Time Between Failures</b>.","from":[{"s":"F23a","qn":"Q1.8"}]},{"id":"F23a-1-9","ch":7,"sl":"16","tp":"Fault tolerance","t":"mcq","q":"Which of the following best defines \"fault tolerance\"?","o":["The system's ability to avoid all faults","The system's ability to support and continue functioning in the presence of faults","The system's capacity to anticipate and prevent faults","The system's capability to identify faults in real-time"],"a":1,"e":"Dependability slide 16: \"Fault tolerance means that the system can <b>continue in operation</b> in spite of software failure.\" (a, c = fault avoidance; d = fault detection.)","from":[{"s":"F23a","qn":"Q1.9"}]},{"id":"F23a-5-1","ch":7,"sl":"26","tp":"Most critical dependability attribute","t":"mcq","q":"Choose the most appropriate dependability attribute that is crucial to the system:<br>The Internet of Things (IoT) project on the DHT11 sensor provides a continuous way to measure and monitor temperature and humidity in a variety of environments, storing the data in a database for analysis, climate-control decisions, user alerts and long-term trend tracking.","o":["POFOD","ROCOF","Availability"],"a":2,"e":"The sensor must run <b>continuously</b> to monitor the environment — the key requirement is that it is up and delivering data → availability. Official key: Availability.","from":[{"s":"F23a","qn":"Q5.1"}]},{"id":"F23a-5-2","ch":7,"sl":"8, 18","tp":"Most critical dependability attribute","t":"mcq","q":"Choose the most appropriate dependability attribute that is crucial to the system:<br>In an air traffic control system, the primary focus is to ensure the uninterrupted and error-free operation of flying activities, minimizing the potential for accidents or incidents.","o":["Security","Safety","Reliability"],"a":1,"e":"Minimizing accidents → <b>safety</b> (slide 8: how likely the system will cause damage to people or its environment). Official key: Safety.","from":[{"s":"F23a","qn":"Q5.2"}]},{"id":"F23a-5-3","ch":7,"sl":"23","tp":"Most critical dependability attribute","t":"mcq","q":"Choose the most appropriate dependability attribute that is crucial to the system:<br>In a financial trading platform, the system's primary goal is to execute transactions reliably and swiftly, even in high-pressure trading environments.","o":["POFOD","ROCOF","Security"],"a":0,"e":"Each trade request must succeed — a failure on a request is serious → <b>POFOD</b> (slide 23). Official key: POFOD.","from":[{"s":"F23a","qn":"Q5.3"}]},{"id":"F23a-5-5","ch":7,"sl":"8","tp":"Most critical dependability attribute","t":"mcq","q":"Choose the most appropriate dependability attribute that is crucial to the system:<br>In an online payment processing platform. This system operates in a fast-paced digital landscape, handling countless online payments daily.","o":["Security","Safety","Reliability"],"a":2,"e":"Countless payments must each be processed correctly → <b>reliability</b> (slide 8: correctly deliver services as expected). Official key: Reliability.","from":[{"s":"F23a","qn":"Q5.5"}]},{"id":"M22b2-3-1","ch":7,"sl":"16, 17","tp":"Train protection — fault tolerance","t":"mcq","q":"A train protection system automatically applies the brakes of a train if the speed limit for a segment of track is exceeded, or if the train enters a track segment that is currently signalled with a red light. This operation is called:","o":["Fault detection","Fault removal","Fault avoidance","Fault tolerance"],"a":3,"e":"The system keeps the train operating safely <b>in spite of</b> a fault (the driver speeding or passing a red signal) — fault tolerance (Dependability slide 16). Official Final 2021 key: d.","from":[{"s":"M22b2","qn":"Q3.1","pg":2},{"s":"F21a","qn":"Q5.1","pg":7}]},{"id":"F21a-5-2","ch":7,"sl":"8, 18","tp":"Train protection — critical attribute","t":"mcq","q":"A train protection system automatically applies the brakes if the speed limit is exceeded or if the train enters a red-signalled segment. Which dependability attribute is most critical for this system?","o":["Availability","Security","Safety"],"a":2,"e":"It is a critical system — a failure may cause a catastrophic accident and harm people → <b>safety</b> (Dependability slide 8). Official key: c.","from":[{"s":"M22b2","qn":"Q3.2","pg":2},{"s":"F21a","qn":"Q5.2","pg":7}]},{"id":"F21a-5-3","ch":7,"sl":"23","tp":"Train protection — reliability metric","t":"mcq","q":"Giving reasons, choose a reliability metric that might be used to specify the required reliability for the train protection system:","o":["POFOD","ROCOF","Availability"],"a":0,"e":"Slide 23: POFOD \"should be used as a reliability metric in situations where a failure on request is serious\" — protection systems are called on intermittently and infrequently, and must respond correctly each time. Official key: a.","from":[{"s":"M22b2","qn":"Q3.3","pg":2},{"s":"F21a","qn":"Q5.3","pg":7}]},{"id":"F21a-5-4","ch":7,"sl":"25","tp":"Train protection — MTBF","t":"mcq","q":"For the past month, the train protection system failed for one hour on three different occasions. What is the Mean Time Between Failures? (MTBF = total operational time / total number of failures)","o":["240 hours","0.33 hours","717 hours","3 hours"],"a":0,"e":"One month = 30 × 24 = 720 hours → MTBF = 720 / 3 = <b>240 hours</b> (official model answer).","from":[{"s":"M22b2","qn":"Q3.4","pg":2},{"s":"F21a","qn":"Q5.4","pg":7}]},{"id":"M21c-1-2","ch":7,"sl":"14, 16","tp":"Fault tolerant","t":"mcq","q":"A software system is fault tolerant if:","o":["It traps mistakes before they introduce system faults","It detects errors before the system goes into service","It ensures that system errors do not lead to system failures","It minimises the possibility of mistakes"],"a":2,"e":"Dependability slide 14: errors do not necessarily lead to failures — they can be corrected by built-in error detection and recovery; slide 16: fault tolerance = continue in operation in spite of faults. Official key: c.","from":[{"s":"M21c","qn":"Q1.2","pg":2}]},{"id":"M21c-1-6","ch":7,"sl":"6","tp":"Dependability = trust","t":"mcq","q":"\"The dependability of a system reflects the user's degree of trust in that system.\"","o":["True","False, it is the availability that reflects the user's degree of trust","False, it is the reliability that reflects the user's degree of trust","False, it is the security that reflects the user's degree of trust"],"a":0,"e":"Dependability slide 6: \"The dependability of a system reflects the user's degree of trust in that system.\" Official key: a.","from":[{"s":"M21c","qn":"Q1.6","pg":2}]},{"id":"M21c-2-2a","ch":7,"sl":"8","tp":"Most critical dependability attribute","t":"mcq","q":"Choose the dependability attribute that is likely to be most critical for this system:<br>A protection system monitors a chemical reactor and shuts down the reaction if it is overheating.","o":["Availability","Reliability","Security","Safety"],"a":3,"e":"Overheating could cause an explosion and harm people → <b>safety</b>. Official key: Safety. \"Any meaningful justification is accepted; reliability can be chosen for any of the systems.\"","from":[{"s":"M21c","qn":"Q2.2a","pg":3}]},{"id":"M21c-2-2b","ch":7,"sl":"8","tp":"Most critical dependability attribute","t":"mcq","q":"Choose the dependability attribute that is likely to be most critical for this system:<br>A university system that keeps track of student records such as transcripts. It handles a large number of transactions regularly throughout the day. You are willing to accept around 10 failures a day.","o":["Availability","Reliability","Security","Safety"],"a":2,"e":"Failures are tolerated (≈10 a day), but transcripts are confidential records that must not be changed → <b>security</b>. Official key: Security (reliability is also accepted). \"Any meaningful justification is accepted; reliability can be chosen for any of the systems.\"","from":[{"s":"M21c","qn":"Q2.2b","pg":3}]},{"id":"M21c-2-2c","ch":7,"sl":"8","tp":"Most critical dependability attribute","t":"mcq","q":"Choose the dependability attribute that is likely to be most critical for this system:<br>A system to control a refrigeration unit for home owners' use.","o":["Availability","Reliability","Security","Safety"],"a":0,"e":"It must keep running to keep food cold; it is not safety-critical → <b>availability</b>. Official key: Availability. \"Any meaningful justification is accepted; reliability can be chosen for any of the systems.\"","from":[{"s":"M21c","qn":"Q2.2c","pg":3}]},{"id":"M21c-3-1","ch":7,"sl":"23","tp":"Seatbelt POFOD","t":"short","q":"POFOD ranges from 0 to 1, and Dependability + POFOD = 1. An automobile manufacturer sets a goal of only 1 failed seatbelt in any of its cars during a 1-million-unit product run, assuming every car were to crash.<br>1) What is the POFOD if there are four seatbelts per car?<br>2) What is the necessary dependability of the seatbelts?","a":"1) 1 million cars × 4 seatbelts = 4,000,000 seatbelts → POFOD = <b>1 / 4,000,000 = 0.00000025</b><br>2) Dependability = 1 − POFOD = 1 − 1/4,000,000 = <b>0.99999975</b> (99.999975%)","e":"Official model answer. Dependability slide 23: POFOD = failures / demands.","from":[{"s":"M21c","qn":"Q3.1","pg":4}]},{"id":"M21c-3-2","ch":7,"sl":"26","tp":"Copier availability","t":"short","q":"A copier is expected to operate for 200 hours after repair, and the mean repair time is expected to be two hours. Determine the availability of the copier.","a":"MTBF = 200 h, MTTR = 2 h → Availability = MTBF / (MTBF + MTTR) = 200 / 202 = <b>0.99</b>","e":"Official model answer. Dependability slide 26: availability = uptime / total time, taking repair time into account.","from":[{"s":"M21c","qn":"Q3.2","pg":4}]},{"id":"M21a-2-1","ch":7,"sl":"18","tp":"True / False","t":"tf","q":"Software safety is equivalent to software reliability.","a":1,"e":"Dependability slide 18: \"Safety and reliability are related but distinct.\" Reliability is about conformance to the specification; safety is about not causing damage, whether or not the system conforms.","from":[{"s":"M21a","qn":"Q2.1","pg":3}]},{"id":"F26a-4-1","ch":8,"sl":"","tp":"CFG, cyclomatic complexity, basis paths","t":"short","q":"Given the pseudocode:<pre>System.out.println(\"Welcome\");\ndo {\n   System.out.print(\"Enter your rank, or 4 to Exit \");\n   a = scanner.nextInt();\n   switch (a) {\n      case 1: System.out.println(\"Gold Medal\");   break;\n      case 2: System.out.println(\"Silver Medal\"); break;\n      case 3: System.out.println(\"Bronze Medal\"); break;\n   }\n} while (a != 4);\nSystem.out.println(\"Good Luck\");</pre>1) Draw a control flow graph. 2) Calculate the cyclomatic complexity. 3) List the basic path set.","a":"<b>Nodes:</b> 1 = print Welcome · 2 = prompt, read a, switch(a) · 3 = Gold · 4 = Silver · 5 = Bronze · 6 = while (a != 4) · 7 = Good Luck<br><b>Edges (10):</b> 1→2, 2→3, 2→4, 2→5, 2→6 (no case matches), 3→6, 4→6, 5→6, 6→2 (loop), 6→7<br><b>V(G)</b> = E − N + 2 = 10 − 7 + 2 = <b>5</b> (check: 4 decisions — 3 extra switch branches + the while — plus 1).<br><b>Basis paths:</b><br>1) 1-2-6-7 (input 4)<br>2) 1-2-3-6-2-6-7 (input 1, then 4)<br>3) 1-2-4-6-2-6-7 (input 2, then 4)<br>4) 1-2-5-6-2-6-7 (input 3, then 4)<br>5) 1-2-6-2-6-7 (input 5, then 4)","e":"This is a software-testing question (no deck in your slides folder). Cyclomatic complexity V(G) = E − N + 2 = number of decisions + 1; each basis path adds at least one new edge.","from":[{"s":"F26a","qn":"Q4 Part 1","pg":5}]},{"id":"F26a-4-2","ch":8,"sl":"","tp":"Equivalence partitions and BVA","t":"short","q":"A method checkPass() accepts values between 60 and 100 inclusive [60 … 100].<br>a) Identify the equivalence partitions.<br>b) Using Boundary Value Analysis, list the values to be tested.","a":"a) Three partitions: <b>invalid &lt; 60</b> (e.g. 30) · <b>valid 60–100</b> (e.g. 80) · <b>invalid &gt; 100</b> (e.g. 120).<br>b) Test at and around each boundary: <b>59, 60, 61, 99, 100, 101</b> (minimum set: 59, 60, 100, 101).","e":"Software-testing question (no deck in your slides). Equivalence partitioning picks one value per class; boundary value analysis tests the edges of each class.","from":[{"s":"F26a","qn":"Q4 Part 2.1","pg":6}]},{"id":"F26a-4-3","ch":8,"sl":"","tp":"Automated testing advantages","t":"short","q":"Mention two advantages of Automated Testing.","a":"Any two: tests run <b>faster</b> and can be <b>re-run cheaply</b> after every change (regression testing); results are <b>consistent/repeatable</b> with fewer human errors; tests are <b>reusable</b>; more tests can be run, increasing coverage.","e":"Software-testing question (no deck in your slides).","from":[{"s":"F26a","qn":"Q4 Part 2.2","pg":6}]},{"id":"F25b-4A","ch":8,"sl":"","tp":"CFG for bubble sort","t":"short","q":"Given the pseudocode for a function that sorts an array using Bubble Sort and finds the second largest element:<pre> 1. function find_second_largest(A, N){\n 2.   for (i = 1 To N){\n 3.     for (j = i-1 to N){\n 4.       if (A[j] > A[j + 1]){\n 5.         temp = A[j]\n 6.         A[j] = A[j + 1]\n 7.         A[j + 1] = temp }}}\n 8.   if (N &lt; 2)\n 9.     return None\n10.   else\n11.     return A[N - 2] }</pre>1) Draw a control flow graph. 2) Calculate the cyclomatic complexity. 3) Find the basic path set.","a":"<b>Nodes:</b> 1 = start · 2 = outer for (i ≤ N?) · 3 = inner for (j ≤ N?) · 4 = if A[j] &gt; A[j+1] · 5 = swap (lines 5–7) · 6 = j++ · 7 = i++ · 8 = if N &lt; 2 · 9 = return None · 10 = return A[N−2] · 11 = end<br><b>Edges:</b> 1→2, 2→3 (T), 2→8 (F), 3→4 (T), 3→7 (F), 4→5 (T), 4→6 (F), 5→6, 6→3, 7→2, 8→9 (T), 8→10 (F), 9→11, 10→11 → E = 14, N = 11<br><b>V(G)</b> = 14 − 11 + 2 = <b>5</b> (4 decisions: outer for, inner for, if, if N&lt;2 → 4 + 1 = 5)<br><b>Basis paths:</b><br>1) 1-2-8-9-11<br>2) 1-2-8-10-11<br>3) 1-2-3-7-2-8-10-11<br>4) 1-2-3-4-6-3-7-2-8-10-11<br>5) 1-2-3-4-5-6-3-7-2-8-10-11","e":"Software-testing question (no deck in your slides). Every loop condition and if-statement is a decision node; V(G) = E − N + 2 = decisions + 1. Each basis path adds one new edge.","from":[{"s":"F25b","qn":"Q4 Part A","pg":5}]},{"id":"F25b-4B-1","ch":8,"sl":"","tp":"Equivalence classes and BVA","t":"short","q":"Function validateAge checks whether an integer input age falls within an acceptable range for a particular service. The valid age range is 18 to 65, inclusive.<br>a) What are the equivalence classes for black-box testing validateAge?<br>b) What values should be tested using Boundary Value Analysis?","a":"a) <b>age &lt; 18</b> (invalid) · <b>18 ≤ age ≤ 65</b> (valid) · <b>age &gt; 65</b> (invalid)<br>b) <b>17, 18, 65, 66</b> (optionally also 19 and 64)","e":"Software-testing question (no deck in your slides). Boundary value analysis tests just below, on, and just above each boundary.","from":[{"s":"F25b","qn":"Q4 Part B.1–2","pg":6},{"s":"F24a","qn":"Q4 Part 2.1–2","pg":4}]},{"id":"F25b-4B-2","ch":8,"sl":"","tp":"Black-box vs white-box","t":"short","q":"What is the main difference between black-box testing and white-box testing?","a":"<b>White-box</b> testing tests the internal <b>structure</b> of the code (paths, branches) and finds design and code errors, but cannot find missing functions. <b>Black-box</b> testing tests the <b>function</b> from the specification without looking at the code; it can find requirements/specification errors and missing functions.","e":"Software-testing question (no deck in your slides); this is the white-box vs black-box table used in the course.","from":[{"s":"F25b","qn":"Q4 Part B.3","pg":6},{"s":"F24a","qn":"Q4 Part 2.3","pg":4}]},{"id":"F24c-3-1","ch":8,"sl":"","tp":"Cyclomatic complexity from a graph","t":"short","q":"The following flow graph represents a program. Edges: 1→2, 1→6, 2→3, 2→4, 3→5, 4→5, 5→6, 6→7.<br>a) What is the cyclomatic complexity?<br>b) Write down the independent paths that should cover the test.","a":"a) E = 8, N = 7 → V(G) = 8 − 7 + 2 = <b>3</b> (2 decision nodes, 1 and 2, + 1)<br>b) <b>1-6-7</b> · <b>1-2-3-5-6-7</b> · <b>1-2-4-5-6-7</b>","e":"Software-testing question (no deck in your slides). V(G) = E − N + 2.","from":[{"s":"F24c","qn":"Q3.1","pg":5}],"img":"F24c_cfg.jpg"},{"id":"F24c-3-2","ch":8,"sl":"","tp":"Speeding fine — EP and BVA","t":"short","q":"The system calculates the fine for speeding:<ul><li>1–10 km/h over the limit: 100 SAR</li><li>11–20 km/h over: 200 SAR</li><li>21–30 km/h over: 300 SAR</li><li>more than 30 km/h over: 400 SAR</li></ul>a) How many equivalence classes could be identified?<br>b) Write down all boundary values.","a":"a) <b>5 classes:</b> not speeding (≤ 0) · 1–10 · 11–20 · 21–30 · &gt; 30<br>b) <b>0, 1, 10, 11, 20, 21, 30, 31</b>","e":"Software-testing question (no deck in your slides). Each fine band is one valid class; values at or below the limit form the extra class. Boundary values sit at the edges of each class.","from":[{"s":"F24c","qn":"Q3.2","pg":5}]},{"id":"F24b-1-5","ch":8,"sl":"","tp":"Testing terms","t":"mcq","q":"Identify the term which is <b>not</b> related to testing.","o":["Failure","Error","Test bot","Test case"],"a":2,"e":"Failure, error and test case are standard testing terms (a test case produces a failure caused by an error/fault). \"Test bot\" is not a testing term in the course. (Software testing has no deck in your slides.)","from":[{"s":"F24b","qn":"Q1.5","pg":1}]},{"id":"F24b-2-9","ch":8,"sl":"","tp":"True / False","t":"tf","q":"Coverage monitoring is vital for white-box testing.","a":0,"e":"White-box testing aims to exercise the code structure (statements, branches, paths), so coverage must be measured. Official model answer: T.","from":[{"s":"F24b","qn":"Q2.9","pg":3},{"s":"F23a","qn":"Q2.10"}]},{"id":"F24b-2-10","ch":8,"sl":"","tp":"True / False","t":"tf","q":"The goal of a software tester is to find bugs, find them as early as possible and make sure they get fixed.","a":0,"e":"This is the classic definition of the tester's goal (Patton, Software Testing).","from":[{"s":"F24b","qn":"Q2.10","pg":3}]},{"id":"F24b-4","ch":8,"sl":"","tp":"Testing terminology fill-in","t":"short","q":"Match the blank with the most appropriate term (no duplication).<br><b>Terms:</b> Verification · Automation Testing · Privacy · Model Checking · Regression Testing · Manual Testing · Reliability · Smoke testing · Test Oracles · Control · Validation · Load Testing<ol><li>______ performed on a newly developed software build.</li><li>______ refers to a different set of tasks that ensure that the software that has been built is traceable to customer requirements.</li><li>______ determines whether a system behaves correctly for test execution.</li><li>______ refers to the verification of changes in software after bug fixes or changes in requirements did not affect current features.</li><li>______ is used to re-run the test scenarios quickly and repeatedly, that were performed manually in manual testing.</li><li>______ refers to the set of tasks that ensure that the software correctly implements a specific function.</li></ol>","a":"<ol><li><b>Smoke testing</b></li><li><b>Validation</b></li><li><b>Test Oracles</b></li><li><b>Regression Testing</b></li><li><b>Automation Testing</b></li><li><b>Verification</b></li></ol>","e":"Verification = \"are we building the product right?\" (implements a function correctly); validation = \"are we building the right product?\" (traceable to customer requirements). A test oracle decides whether the output is correct. (Software testing has no deck in your slides.)","from":[{"s":"F24b","qn":"Q4","pg":6}]},{"id":"F23c-1-3","ch":8,"sl":"","tp":"Execution-based verification","t":"mcq","q":"__________ is/are considered as an execution-based verification.","o":["Inspections","Load testing","Formal verification","Static code analysis"],"a":1,"e":"Execution-based (dynamic) verification <b>runs the program</b> — load testing does. Inspections, formal verification and static analysis examine the code without running it. (Software testing — no deck in your slides.)","from":[{"s":"F23c","qn":"Q1.3","pg":1}]},{"id":"F23c-1-8","ch":8,"sl":"","tp":"Load testing","t":"mcq","q":"Which type of testing involves testing the software's ability to handle concurrent user requests?","o":["Functional testing","Smoke testing","Load testing","Code auditing"],"a":2,"e":"<b>Load testing</b> puts the system under many concurrent users/requests to check its behaviour under load. (Software testing — no deck in your slides.)","from":[{"s":"F23c","qn":"Q1.8","pg":2}]},{"id":"F23c-1-9","ch":8,"sl":"","tp":"Good test cases","t":"mcq","q":"Which of the following is <b>not</b> a characteristic of good test cases?","o":["They should be repeatable","They should be understandable","They should be automated","They should be testable"],"a":2,"e":"Good test cases are repeatable, understandable and testable (clear expected result). They do <b>not have to be automated</b> — manual test cases can be good test cases.","from":[{"s":"F23c","qn":"Q1.9","pg":2}]},{"id":"F23c-1-10","ch":8,"sl":"","tp":"Performance issue","t":"mcq","q":"You are testing a desktop spreadsheet application. During testing, you notice that the application freezes when a user tries to sort a large dataset. Which type of testing issue is this?","o":["Functional issue","Performance issue","Safety issue","Security issue"],"a":1,"e":"Sorting works but the app <b>freezes on a large data set</b> — it cannot handle the load in acceptable time → performance issue.","from":[{"s":"F23c","qn":"Q1.10","pg":2}]},{"id":"F23c-2-3","ch":8,"sl":"","tp":"True / False","t":"tf","q":"The cost of software testing is often less than the costs of other software development processes.","a":1,"e":"Testing is one of the most expensive activities — often around half of development cost.","from":[{"s":"F23c","qn":"Q2.3","pg":3}]},{"id":"F23c-2-5","ch":8,"sl":"","tp":"True / False","t":"tf","q":"One difference between sanity testing and regression testing is that regression testing is unscripted.","a":1,"e":"It is the other way round: <b>sanity</b> testing is unscripted and undocumented; regression testing re-runs scripted test cases (Final Fall 2023 model answer definitions).","from":[{"s":"F23c","qn":"Q2.5","pg":3}]},{"id":"F23c-2-6","ch":8,"sl":"","tp":"True / False","t":"tf","q":"Testing can detect bugs, but it cannot guarantee the absence of bugs.","a":0,"e":"Dijkstra: testing can show the presence of bugs, not their absence. Intro slide 16: exhaustive testing is infeasible.","from":[{"s":"F23c","qn":"Q2.6","pg":3}]},{"id":"F23c-2-7","ch":8,"sl":"","tp":"True / False","t":"tf","q":"When the complexity of the system increases, then the testing cost and effort increase as well.","a":0,"e":"More paths and states (higher cyclomatic complexity) need more test cases.","from":[{"s":"F23c","qn":"Q2.7","pg":3}]},{"id":"F23a-3","ch":8,"sl":"","tp":"Match testing terms","t":"short","q":"Match each term to its definition number.<table class=\"mini\"><tr><th>Term</th><th>#</th><th>Definition</th></tr><tr><td>Cluster Testing</td><td>1</td><td>Using specialized software tools and scripts to automate the execution of test cases and the comparison of actual outcomes with expected results.</td></tr><tr><td>Sanity Testing</td><td>2</td><td>A quick and preliminary test to verify whether the most critical and basic functionalities are working, often performed before more comprehensive testing.</td></tr><tr><td>Use-Based Testing</td><td>3</td><td>Evaluating the concurrent and multi-aspects of an OO system: how a set of classes and objects respond to one input or event.</td></tr><tr><td>Smoke Testing</td><td>4</td><td>A mechanism, such as a set of expected outcomes or rules, used to determine whether the software under test is functioning correctly.</td></tr><tr><td>Automated Testing</td><td>5</td><td>Re-running previously executed test cases to ensure that new changes do not introduce new defects or break existing features.</td></tr><tr><td>Test Oracle</td><td>6</td><td>Testing the software from the perspective of how users will interact with it.</td></tr><tr><td>Regression Testing</td><td>7</td><td>A subset of regression testing that is undocumented and unscripted and quickly checks that recent changes have not affected main functionality.</td></tr><tr><td>Thread-Based Testing</td><td>8</td><td>Assessing the interactions and behaviours of groups of related classes or objects within an OO system.</td></tr></table>","a":"<table class=\"mini\"><tr><th>Term</th><th>Definition #</th></tr><tr><td>Cluster Testing</td><td><b>8</b></td></tr><tr><td>Sanity Testing</td><td><b>7</b></td></tr><tr><td>Use-Based Testing</td><td><b>6</b></td></tr><tr><td>Smoke Testing</td><td><b>2</b></td></tr><tr><td>Automated Testing</td><td><b>1</b></td></tr><tr><td>Test Oracle</td><td><b>4</b></td></tr><tr><td>Regression Testing</td><td><b>5</b></td></tr><tr><td>Thread-Based Testing</td><td><b>3</b></td></tr></table>","e":"Official model answer. Smoke = quick check of critical functions on a new build; sanity = unscripted subset of regression after a change; thread-based = classes responding to one event; cluster = a group of collaborating classes. (Software testing has no deck in your slides.)","from":[{"s":"F23a","qn":"Q3"}]},{"id":"F21a-1-1","ch":8,"sl":"","tp":"Code inspection advantages","t":"mcq","q":"Which of the following is <b>not</b> one of the code inspection advantages?","o":["It can check non-functional characteristics of the code","It can check conformance with a specification","It can check incomplete versions of the code","It costs less than software testing"],"a":0,"e":"Inspections are static: they can check incomplete code, conformance with the specification and standards, and cost less than testing — but they <b>cannot check non-functional characteristics</b> such as performance or usability (Sommerville ch. 8). Official key: a.","from":[{"s":"F21a","qn":"Q1.1","pg":2}]},{"id":"F21a-1-5","ch":8,"sl":"","tp":"Integration testing","t":"mcq","q":"In which test level do you focus on possible defects in the interfaces and in the interaction between integrated components?","o":["Acceptance testing","Regression testing","Integration testing","Unit testing"],"a":2,"e":"<b>Integration testing</b> combines components and tests their interfaces and interactions. Official key: c.","from":[{"s":"F21a","qn":"Q1.5","pg":2}]},{"id":"F21a-1-7","ch":8,"sl":"","tp":"Equivalence classes — days","t":"mcq","q":"A software accepts days as numbers (1 = Sunday, 2 = Monday, …, 7 = Saturday). Which values would cover all equivalence classes?","o":["0, 8","0, 1, 7","0, 6, 14","1, 2, 3, 4, 5, 6, 7"],"a":2,"e":"Classes: invalid &lt; 1, valid 1–7, invalid &gt; 7. <b>0, 6, 14</b> takes one value from each class. (0, 8 misses the valid class; 0, 1, 7 misses the &gt; 7 class.) Official key: c.","from":[{"s":"F21a","qn":"Q1.7","pg":3}]},{"id":"F21a-1-8","ch":8,"sl":"","tp":"Boundary values — days","t":"mcq","q":"A software accepts days as numbers (1 = Sunday, …, 7 = Saturday). Which values would cover all boundary values?","o":["0, 8","0, 1, 7, 8","0, 6, 14","1, 2, 3, 4, 5, 6, 7"],"a":1,"e":"The boundaries are 1 and 7: test just outside and on each → <b>0, 1, 7, 8</b>. Official key: b.","from":[{"s":"F21a","qn":"Q1.8","pg":3}]},{"id":"F21a-3-1","ch":8,"sl":"","tp":"White box or black box?","t":"short","q":"Decide whether each test design method / test type is white box or black box:<br>Boundary value analysis · Cyclomatic complexity · Acceptance testing · Control flow graph · Code inspection · Equivalence partitioning","a":"<table class=\"mini\"><tr><th>Method</th><th>Type</th></tr><tr><td>Boundary value analysis</td><td><b>Black box</b></td></tr><tr><td>Cyclomatic complexity</td><td><b>White box</b></td></tr><tr><td>Acceptance testing</td><td><b>Black box</b></td></tr><tr><td>Control flow graph</td><td><b>White box</b></td></tr><tr><td>Code inspection</td><td><b>White box</b></td></tr><tr><td>Equivalence partitioning</td><td><b>Black box</b></td></tr></table>","e":"Official model answer: methods that look at the code's structure are white box; methods based only on the specification are black box.","from":[{"s":"F21a","qn":"Q3.1","pg":5}]},{"id":"F21a-3-2","ch":8,"sl":"","tp":"Cyclomatic complexity — fuel warning","t":"short","q":"The flow graph represents a program that shows a car's fuel level (check fuel; if low show a yellow warning light; if very low also show a red warning light; then show the litres). It has 6 nodes (A–F) and 7 edges.<br>1) What is the cyclomatic complexity? 2) Write the independent paths. 3) Write a test case and expected output for each path.","a":"1) V(G) = E − N + 2 = 7 − 6 + 2 = <b>3</b><br>2) <b>A-B-C-D-E-F</b> · <b>A-B-C-E-F</b> · <b>A-B-F</b><br>3)<table class=\"mini\"><tr><th>Test case</th><th>Expected output</th></tr><tr><td>5 litres</td><td>Show litres</td></tr><tr><td>3 litres</td><td>Show yellow light warning, show litres</td></tr><tr><td>1 litre</td><td>Show red light warning, show yellow light warning, show litres</td></tr></table>","e":"Official model answer.","from":[{"s":"F21a","qn":"Q3.2","pg":5}],"img":"F21_cfg.jpg"},{"id":"Q21-6a","ch":8,"sl":"","tp":"White box testing","t":"mcq","q":"The testing in which the code is checked is:","o":["Black box testing","White box testing","User acceptance testing","Release testing"],"a":1,"e":"<b>White-box</b> testing looks inside the code (structure, paths).","from":[{"s":"Q21","qn":"Quiz 6 (sec 371) Q1a"}]},{"id":"Q21-6b","ch":8,"sl":"","tp":"Cyclomatic complexity","t":"mcq","q":"Cyclomatic complexity measures:","o":["The number of nodes in a CFG","The number of predicates in a CFG","The number of partitions of input data","The number of linearly-independent paths through a program module"],"a":3,"e":"V(G) is the number of <b>linearly independent paths</b> through the program (= predicates + 1), i.e. the size of the basis path set. Quality slide 32 lists it as a static metric of control complexity.","from":[{"s":"Q21","qn":"Quiz 6 (sec 371) Q1b"}]},{"id":"Q21-6c","ch":8,"sl":"","tp":"BVA and EP — pizza order","t":"short","q":"Order Pizza text box: values 1 to 10 are valid (a success message is shown); values 11 to 99 are invalid and an error message appears: \"Only 10 Pizza can be ordered\".<br>a) Identify the equivalence partitions.<br>b) Using Boundary Value Analysis, identify the boundary values.","a":"a) Partitions: <b>invalid ≤ 0</b> · <b>valid 1–10</b> · <b>invalid 11–99</b> (and &gt; 99 if the box allows 3 digits).<br>b) <b>0, 1, 2, 9, 10, 11</b> (and 98, 99, 100 for the upper limit of the invalid range).","e":"Software testing (no deck in your slides).","from":[{"s":"Q21","qn":"Quiz 6 (sec 371/373) Q2"}]},{"id":"Q21-6d","ch":8,"sl":"","tp":"BVA is black box","t":"mcq","q":"Boundary value analysis belongs to:","o":["White box testing","Black box testing","Regression testing","Release testing"],"a":1,"e":"BVA is designed from the specification of the inputs, not the code → <b>black box</b> (Final 2021 model answer).","from":[{"s":"Q21","qn":"Quiz 6 (sec 372) Q1a"}]},{"id":"Q21-6e","ch":8,"sl":"","tp":"Non-functional testing","t":"mcq","q":"Which of the following is non-functional testing?","o":["White box testing","Black box testing","Performance testing","Unit testing"],"a":2,"e":"<b>Performance</b> testing checks a quality attribute (speed/response time), not a function.","from":[{"s":"Q21","qn":"Quiz 6 (sec 372) Q1b"}]},{"id":"Q21-6f","ch":8,"sl":"","tp":"Cyclomatic complexity of if/else","t":"short","q":"What is the cyclomatic complexity of the following code?<pre>A = 10\nIF B &gt; C THEN\n   A = B\nELSE\n   A = C\nENDIF\nPrint A\nPrint B\nPrint C</pre>","a":"One decision (IF) → V(G) = 1 + 1 = <b>2</b>. (Graph: nodes A=10/IF, A=B, A=C, Print → E = 4, N = 4, V = 4 − 4 + 2 = 2.)","e":"Software testing (no deck in your slides).","from":[{"s":"Q21","qn":"Quiz 6 (sec 372) Q2"}]},{"id":"Q21-6g","ch":8,"sl":"","tp":"Acceptance testing","t":"mcq","q":"Acceptance testing is also known as:","o":["Release testing","White box testing","Regression testing","Beta testing"],"a":3,"e":"Acceptance testing by real customers/users in their environment is called <b>beta testing</b> (alpha = at the developer's site).","from":[{"s":"Q21","qn":"Quiz 6 (sec 373) Q1a"}]},{"id":"Q21-6h","ch":8,"sl":"","tp":"Debugging","t":"mcq","q":"Debugging is:","o":["Concerned with confirming the presence of faults","Concerned with locating and repairing these faults","Concerned with locating errors before code execution","Concerned with integrating components to create a version of the system"],"a":1,"e":"Testing shows the presence of faults; <b>debugging locates and repairs</b> them. Source Code Quality slide 32: runtime errors are found by debugging.","from":[{"s":"Q21","qn":"Quiz 6 (sec 373) Q1b"}]},{"id":"F26a-5","ch":9,"sl":"","tp":"Evolution vs servicing vs refactoring","t":"short","q":"Complete the table using only <b>Yes</b> or <b>No</b>:<table class=\"mini\"><tr><th></th><th>Can involve major changes?</th><th>Can add new functionality?</th><th>Can modify/repair functionality?</th><th>Aims to make system easier to maintain?</th><th>Preventive maintenance?</th></tr><tr><td>Evolution</td><td>Yes</td><td>Yes</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td>Servicing</td><td>No</td><td></td><td></td><td></td><td></td></tr><tr><td>Phase-out</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Maintenance</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Re-engineering</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Refactoring</td><td></td><td></td><td></td><td></td><td></td></tr></table>","a":"<table class=\"mini\"><tr><th></th><th>Major changes</th><th>New functionality</th><th>Modify/repair</th><th>Easier to maintain</th><th>Preventive</th></tr><tr><td>Evolution</td><td>Yes</td><td>Yes</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td>Servicing</td><td>No</td><td>No</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td>Phase-out</td><td>No</td><td>No</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Maintenance</td><td>Yes</td><td>Yes</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td>Re-engineering</td><td>Yes</td><td>No</td><td>No</td><td>Yes</td><td>Yes</td></tr><tr><td>Refactoring</td><td>No</td><td>No</td><td>No</td><td>Yes</td><td>Yes</td></tr></table>","e":"Software evolution has no deck in your slides; the answer follows Sommerville ch. 9. <b>Servicing</b> only makes small changes and repairs (no new functionality). In <b>phase-out</b> the software is still used but no further changes are made. <b>Re-engineering</b> restructures/rewrites the system without changing its functionality to make it easier to maintain — your Intro slide 9 lists \"Preventive — re-engineering, make system more maintainable\". <b>Refactoring</b> is small continuous improvement that slows degradation — Sommerville calls it \"preventative maintenance\". The Maintenance row is the general term (corrective, adaptive, perfective changes).","from":[{"s":"F26a","qn":"Q5","pg":6}],"nb":"Related slide: Introduction slide 9 (maintenance types — preventive = re-engineering)"},{"id":"F25b-5","ch":9,"sl":"","tp":"Software evolution fill-in","t":"short","q":"Choose the correct term to fill each blank.<br><b>Terms:</b> Software Evolution · Reverse Engineering · System Re-engineering · Software Change · Software Requirements · Software Maintenance · System Refactoring · Servicing · Phase-out · Software Architecture · Maintenance Prediction · Software Testing<ol><li>Software change is inevitable because new ______ emerge when the software is used.</li><li>______ does not normally involve major changes to the system's architecture.</li><li>______ involves modifying a program to improve its structure, reduce its complexity, or make it easier to understand.</li><li>______ is a process that takes place after a system has been maintained for some time.</li><li>During ______, you need to understand how the program is structured and how it delivers functionality.</li><li>When software enters the ______ stage, it may still be used, but no further changes are made to it.</li></ol>","a":"<ol><li><b>Software Requirements</b></li><li><b>Software Maintenance</b></li><li><b>System Refactoring</b></li><li><b>System Re-engineering</b></li><li><b>Reverse Engineering</b></li><li><b>Phase-out</b></li></ol>","e":"Software evolution has no deck in your slides (Sommerville ch. 9). Maintenance does not normally involve major architectural changes; refactoring improves structure; re-engineering happens after a system has been maintained for some time and costs rise; reverse engineering recovers the program's structure; in phase-out no further changes are made.","from":[{"s":"F25b","qn":"Q5","pg":8},{"s":"F24a","qn":"Q5","pg":7}]},{"id":"F24c-2","ch":9,"sl":"","tp":"Evolution & security fill-in","t":"short","q":"Fill each blank with the most appropriate term (no duplication).<br><b>Terms:</b> Fail safe · Refactoring · Boy scout rule · Re-engineering · Application-level protection · Phase-out · Model checking · Servicing · Marshalling<ol><li>______ is a continuous process of improvement throughout the development and evolution process, while ______ takes place after a system has been maintained for some time and maintenance costs are increasing, especially for legacy systems.</li><li>In software maintenance, ______ means the software remains useful but the only changes made are those required to keep it operational, while ______ means that the software may still be used but no further changes are made to it.</li><li>______ is a specific protection mechanism built into the application itself, e.g. additional password protection.</li><li>______ is a formal method for verifying an abstract representation of a system using a finite state machine.</li></ol>","a":"<ol><li><b>Refactoring</b> … <b>Re-engineering</b></li><li><b>Servicing</b> … <b>Phase-out</b></li><li><b>Application-level protection</b></li><li><b>Model checking</b></li></ol>","e":"Refactoring vs re-engineering and servicing vs phase-out come from software evolution (Sommerville ch. 9 — no deck in your slides). Application-level protection: Security slide 6. Model checking uses a finite-state model of the system (formal verification).","from":[{"s":"F24c","qn":"Q2","pg":6}]},{"id":"F23c-1-4","ch":9,"sl":"","tp":"Phase-out","t":"mcq","q":"__________ means that a software may still be used but without any further changes.","o":["Evolution","Maintenance","Servicing","Phasing out"],"a":3,"e":"Sommerville ch. 9: in <b>phase-out</b> the software may still be used but no further changes are made to it. In servicing, only small changes needed to keep it operational are made.","from":[{"s":"F23c","qn":"Q1.4","pg":1}]},{"id":"F23c-2-1","ch":9,"sl":"","tp":"True / False","t":"tf","q":"Reverse engineering is the process of re-writing part or all of a legacy system without changing its functionality.","a":1,"e":"That describes <b>re-engineering</b>. Reverse engineering analyses a program to understand its structure and how it delivers functionality.","from":[{"s":"F23c","qn":"Q2.1","pg":3}]},{"id":"F23c-2-2","ch":9,"sl":"","tp":"True / False","t":"tf","q":"We can assess maintainability by measuring metrics such as the average time required for impact analysis.","a":0,"e":"Sommerville ch. 9 maintainability metrics: number of change requests, average time for impact analysis, average time to implement a change request, number of outstanding change requests.","from":[{"s":"F23c","qn":"Q2.2","pg":3}]},{"id":"F23c-2-4","ch":9,"sl":"","tp":"True / False","t":"tf","q":"The maintainability of a software product increases when the number of change requests increases.","a":1,"e":"An <b>increase</b> in the number of (corrective) change requests indicates a <b>decline</b> in maintainability (Sommerville ch. 9). <i>The solved copy marked True — that is wrong.</i>","from":[{"s":"F23c","qn":"Q2.4","pg":3}]},{"id":"F23a-2-1","ch":9,"sl":"","tp":"True / False","t":"tf","q":"The majority of the software budget in large companies is devoted to changing and evolving existing software rather than developing new software.","a":0,"e":"Sommerville ch. 9: most of the budget goes to evolving existing software. Official key: T.","from":[{"s":"F23a","qn":"Q2.1"}]},{"id":"F23a-2-2","ch":9,"sl":"","tp":"True / False","t":"tf","q":"Proposals for change are the driver for system evolution.","a":0,"e":"Sommerville ch. 9: change proposals drive system evolution. Official key: T.","from":[{"s":"F23a","qn":"Q2.2"}]},{"id":"F23a-2-3","ch":9,"sl":"","tp":"True / False","t":"tf","q":"Reengineering aims to enhance the functionality of the software without making changes to its structure.","a":1,"e":"It is the opposite: re-engineering restructures or rewrites the system <b>without changing its functionality</b> to make it more maintainable (Intro slide 9: preventive maintenance). Official key: F.","from":[{"s":"F23a","qn":"Q2.3"}]},{"id":"F23a-2-4","ch":9,"sl":"","tp":"True / False","t":"tf","q":"Ageing software can have high support costs.","a":0,"e":"Legacy/ageing software is expensive to maintain (outdated languages, degraded structure). Official key: T.","from":[{"s":"F23a","qn":"Q2.4"}]},{"id":"F23a-2-5","ch":9,"sl":"","tp":"True / False","t":"tf","q":"Refactoring is the process of making improvements to a program to accelerate degradation through change.","a":1,"e":"Refactoring improves a program to <b>slow down</b> degradation through change. Official key: F.","from":[{"s":"F23a","qn":"Q2.5"}]},{"id":"M22b2-1-1","ch":9,"sl":"","tp":"Change management","t":"mcq","q":"The CM (configuration management) activity for keeping track of requests for changes to the software from customers and developers is:","o":["Version management","Change management","Release management","System building"],"a":1,"e":"<b>Change management</b> keeps track of change requests, works out their costs and impact, and decides if/when to implement them. (Configuration management — not in your slides.)","from":[{"s":"M22b2","qn":"Q1.1","pg":1}]},{"id":"M22b2-1-2","ch":9,"sl":"","tp":"Checksums","t":"mcq","q":"__________ are signatures on the source code file that are calculated from data in the file.","o":["Deltas","Mitigations","Source code checksums","Modification timestamp"],"a":2,"e":"A <b>checksum</b> is computed from the file's contents, so it changes whenever the content changes (used by build systems to detect modified files). Deltas are differences between versions.","from":[{"s":"M22b2","qn":"Q1.2","pg":1}]},{"id":"M22b2-1-4","ch":9,"sl":"","tp":"Baseline","t":"mcq","q":"A __________ is the set of component versions that are included in the system.","o":["Mainline","Codeline","Baseline","Workspace"],"a":2,"e":"A <b>baseline</b> is a definition of a specific system: the component versions included in it. A codeline is a sequence of versions of one component.","from":[{"s":"M22b2","qn":"Q1.4","pg":1}]},{"id":"M22b2-1-5","ch":9,"sl":"","tp":"Distributed version control","t":"mcq","q":"Which of the following is <b>not</b> true for a distributed version control system?","o":["It is essential for open source development","It provides a backup mechanism for the repository","Developers can compile and test the entire system on their local machines","Developers check out components from the project repository into their private workspace"],"a":3,"e":"Checking out components from a central project repository is how a <b>centralized</b> system works. In a distributed system developers <b>clone</b> the whole repository.","from":[{"s":"M22b2","qn":"Q1.5","pg":1}]},{"id":"F21a-1-2","ch":9,"sl":"","tp":"Change management","t":"mcq","q":"Which process is concerned with analyzing the costs and benefits of proposed changes?","o":["System building","Version management","Release management","Change management"],"a":3,"e":"<b>Change management</b> analyses the costs and benefits of proposed changes, approves them, and tracks which components changed. Official key: d. (Configuration management — not in your slides.)","from":[{"s":"F21a","qn":"Q1.2","pg":2}]},{"id":"F21a-1-4","ch":9,"sl":"","tp":"Checksums","t":"mcq","q":"__________ is a signature on the source code file calculated from the source code text.","o":["Deltas","Checksums","Timestamps","Change requests"],"a":1,"e":"A <b>checksum</b> is calculated from the file's text, so any change to the text changes the checksum. Official key: b.","from":[{"s":"F21a","qn":"Q1.4","pg":2}]},{"id":"M21c-1-5","ch":9,"sl":"","tp":"Codeline","t":"mcq","q":"In version management systems, which definition best describes a codeline?","o":["An instance of a configuration item","A collection of component versions that make up a system","A version of a software system that is distributed to customers","A sequence of versions of source code with later versions in the sequence derived from earlier versions"],"a":3,"e":"A <b>codeline</b> is a sequence of versions of source code, each derived from the previous. (b = baseline, c = release.) Official key: d.","from":[{"s":"M21c","qn":"Q1.5","pg":2}]},{"id":"M21c-2-1","ch":9,"sl":"","tp":"Centralized vs distributed VCS","t":"short","q":"Provide two differences between distributed and centralized version control systems.","a":"<table class=\"mini\"><tr><th>Centralized</th><th>Distributed</th></tr><tr><td>Developers check out components from a single project repository</td><td>Each developer creates a <b>clone</b> of the whole repository</td></tr><tr><td>Programmers commit their changes to the central copy</td><td>Allows <b>off-line</b> working; commits are local, then pushed</td></tr><tr><td>The central server is a single point of failure</td><td>Every clone is a backup of the repository</td></tr><tr><td>Example: Subversion</td><td>Example: Git — essential for open-source development</td></tr></table>","e":"Official model answer. (Configuration management — not in your slides.)","from":[{"s":"M21c","qn":"Q2.1","pg":3}]},{"id":"F25b-4B-3","ch":10,"sl":"","tp":"Test-driven development","t":"short","q":"What is the main idea of Test-Driven Development (TDD)? Give one advantage of using TDD.","a":"<b>Test first:</b> write a (failing) unit test <i>before</i> writing the functional code, then write just enough code to pass it, then refactor.<br><b>Advantages:</b> more tests → increased confidence in the code; yields many regression test cases; simpler, better-designed code; bugs found early.","e":"TDD is not in your slide decks (Source Code Quality slide 35 only links to a TDD reading).","from":[{"s":"F25b","qn":"Q4 Part B.4–5","pg":6},{"s":"F24a","qn":"Q4 Part 2.4–5","pg":4}]},{"id":"F24c-1-2","ch":10,"sl":"","tp":"Model checking limitation","t":"mcq","q":"One major limitation of model checking is:","o":["The verification occurs too late in the process","It cannot guarantee the absence of bugs","Difficult to scale when software grows","Very weak debugging capabilities"],"a":2,"e":"Model checking explores every reachable state, so the state space explodes as the software grows — it is hard to <b>scale</b>. It is used early (on models) and gives counter-examples that help debugging. (Not in your slide decks.)","from":[{"s":"F24c","qn":"Q1.2","pg":7}]},{"id":"F24c-1-3","ch":10,"sl":"","tp":"TDD cycle","t":"mcq","q":"The Test-Driven Development cycle elements are:","o":["Red, green, blue","Red, green, refactor","Write a test, make a test pass, refactor","Both b and c"],"a":3,"e":"TDD cycle: <b>Red</b> — write a failing test; <b>Green</b> — write code to make the test pass; <b>Refactor</b> — clean up the code. Options b and c describe the same cycle. (TDD is only referenced as a reading on Source Code Quality slide 35.)","from":[{"s":"F24c","qn":"Q1.3","pg":7}]},{"id":"M24c-1-3","ch":10,"sl":"","tp":"Traceability matrix","t":"mcq","q":"To check that all requirements are covered by the use cases, we use:","o":["Use case diagrams","Sequence diagrams","Design patterns","Traceability matrix"],"a":3,"e":"A <b>traceability matrix</b> maps each requirement to the use cases (or tests) that cover it, so gaps are visible. (PM slide 18 mentions deriving traceability information for requirements changes; the matrix itself is not on your slides.)","from":[{"s":"M24c","qn":"Q1.3","pg":8},{"s":"F23b","qn":"Q1.3","pg":1}]},{"id":"M24c-1-4","ch":10,"sl":"","tp":"SaaS","t":"mcq","q":"SaaS is a software delivery model where:","o":["Software is developed using agile methodologies","Users access software applications over the Internet","Software is installed and maintained on individual computers","Software is hosted and managed by a third-party provider"],"a":1,"e":"Software as a Service: the application runs on the provider's servers and users <b>access it over the Internet</b> (usually through a browser) instead of installing it. (Option d describes hosting in general and is part of SaaS, but b is the defining feature.) Not on your slides.","from":[{"s":"M24c","qn":"Q1.4","pg":8}]},{"id":"M24c-4A","ch":10,"sl":"","tp":"Pattern for notifications","t":"mcq","q":"You are developing a chat application where users can send messages to each other. The application needs to notify users whenever a new message is received, and it should support multiple notification mechanisms such as email, SMS, and push notifications. Additionally, the application should allow for easy addition of new notification mechanisms in the future. Select the most appropriate design pattern and justify your choice.","o":["Singleton","Facade","Adapter","Observer"],"a":3,"e":"<b>Observer:</b> the chat (subject) notifies all registered notifiers/users (observers) automatically when a new message arrives. Email, SMS and push are each an observer implementing the same <code>update()</code> interface, so a new mechanism is added by registering a new observer without changing the chat code. Observer is not one of the three patterns in your OOAD deck (Singleton, Adapter, Façade).","from":[{"s":"M24c","qn":"Q4 A","pg":7}]},{"id":"F24b-1-7","ch":10,"sl":"","tp":"Model checking","t":"mcq","q":"A disadvantage of model checking in formal verification is:","o":["Scalability","Weak debugging capabilities","It requires deep training","Cannot be integrated within industrial development cycle"],"a":0,"e":"Model checking explores <b>every reachable state</b> of a finite-state model, so the number of states explodes as the system grows (the 'state explosion' problem) — it does not scale well to large systems. It gives good counter-examples for debugging and is used in industry. (Not in your slide decks.)","from":[{"s":"F24b","qn":"Q1.7","pg":2}]},{"id":"F24b-2-1","ch":10,"sl":"","tp":"True / False","t":"tf","q":"Model checking is proven unsuccessful in detecting problems in the early stages of the development cycle.","a":1,"e":"Model checking is <b>successful</b> at finding problems early (on design models). Official model answer: F. (Not in your slide decks.)","from":[{"s":"F24b","qn":"Q2.1","pg":3},{"s":"F23a","qn":"Q2.6"}]},{"id":"F24b-2-6","ch":10,"sl":"","tp":"True / False","t":"tf","q":"Model checking is a technique used in formal methods to verify the correctness of a system by exhaustively exploring all possible states.","a":0,"e":"Model checking builds a finite-state model and exhaustively checks every reachable state against the specification. (Not in your slide decks.)","from":[{"s":"F24b","qn":"Q2.6","pg":3}]},{"id":"M24b-4","ch":10,"sl":"","tp":"Observer pattern — stock market","t":"short","q":"<b>Stock Market Monitoring System:</b> design a system that tracks the prices of multiple stocks in real time and provides notifications to subscribed investors whenever there is a significant change in the stock prices. Investors should receive updates on their selected stocks without tightly coupling the notification system to the individual stocks.<br>a) What design pattern is most appropriate? Justify.<br>b) Draw a sequence diagram showing how the pattern operates between the stock market and two investors A and B.","a":"a) <b>Observer pattern</b> — defines a one-to-many dependency so that when one object (the subject: the stock) changes state, all its dependents (observers: investors) are notified automatically. The subject only knows observers through an <code>Observer</code> interface, so stocks and investors stay <b>loosely coupled</b>, and investors can subscribe/unsubscribe at runtime.<br>b) Lifelines: <code>:StockMarket</code> (subject), <code>A:Investor</code>, <code>B:Investor</code>.<ol><li>A → StockMarket: <code>attach(A)</code> (subscribe)</li><li>B → StockMarket: <code>attach(B)</code></li><li>StockMarket: <code>setPrice(newPrice)</code> → significant change → <code>notify()</code> (self-call)</li><li>StockMarket → A: <code>update(stock, price)</code></li><li>StockMarket → B: <code>update(stock, price)</code></li><li>(optional) A/B → StockMarket: <code>getPrice()</code> and a return message</li></ol>","e":"The Observer pattern is not one of the three patterns in your OOAD deck (Singleton, Adapter, Façade), so this sits under 'other topics'. Sequence-diagram notation (lifelines, synchronous messages, activations) is on OOAD slide 13.","from":[{"s":"M24b","qn":"Q4","pg":4}]},{"id":"F23c-2-9","ch":10,"sl":"","tp":"True / False","t":"tf","q":"The model checking method uses a sequence diagram as the system model for formal verification.","a":1,"e":"Model checking uses a <b>finite state machine</b> model.","from":[{"s":"F23c","qn":"Q2.9","pg":3}]},{"id":"F23c-2-10","ch":10,"sl":"","tp":"True / False","t":"tf","q":"Model checking is the only method of formal verification.","a":1,"e":"Formal verification also includes theorem proving / deductive verification (e.g. JML specifications, Source Code Quality slide 33).","from":[{"s":"F23c","qn":"Q2.10","pg":3}]},{"id":"F23a-1-1","ch":10,"sl":"","tp":"TDD cycle","t":"mcq","q":"Which of the following is <b>not</b> part of a Test Driven Development (TDD) cycle?","o":["Write a successful test","Write a failing test","Make the test pass","Refactoring"],"a":0,"e":"The TDD cycle is red → green → refactor: write a <b>failing</b> test first, make it pass, then refactor. You never start by writing a test that already succeeds. Official key: a.","from":[{"s":"F23a","qn":"Q1.1"},{"s":"M21b","qn":"Q1.4","pg":2}]},{"id":"F23a-1-3","ch":10,"sl":"","tp":"Object responsibilities","t":"mcq","q":"What type of object responsibility is \"references to other objects\"?","o":["Doing responsibility","Knowing responsibility","Delegation responsibility","Initiation responsibility"],"a":1,"e":"In responsibility-driven design, <b>knowing</b> responsibilities are what an object knows: its private data, <b>references to related objects</b>, and things it can derive. Doing responsibilities are actions it performs. Official key: b. (Not on your slides.)","from":[{"s":"F23a","qn":"Q1.3"}]},{"id":"F23a-1-10","ch":10,"sl":"","tp":"Strategy pattern","t":"mcq","q":"Which design pattern is used when you want to define a family of algorithms, encapsulate each one, and make them interchangeable?","o":["Singleton Pattern","Façade Design Pattern","Strategy Pattern","Observer Pattern"],"a":2,"e":"That is the intent of the <b>Strategy</b> pattern (also used in the Final 2021 model answer). Singleton = only one instance; Façade = a single class representing a subsystem (OOAD slide 25). Official key: c.","from":[{"s":"F23a","qn":"Q1.10"}]},{"id":"F23a-2-7","ch":10,"sl":"","tp":"True / False","t":"tf","q":"Using finite state machines is a limitation of model checking.","a":0,"e":"Model checking needs the system expressed as a finite-state model, which limits it (large or infinite state spaces cannot be fully explored). Official key: T.","from":[{"s":"F23a","qn":"Q2.7"}]},{"id":"F23a-2-9","ch":10,"sl":"","tp":"True / False","t":"tf","q":"The model checking method uses a data flow diagram as the system model for formal verification.","a":1,"e":"Model checking uses a <b>finite state machine</b> (state transition model), not a data flow diagram. Official key: F.","from":[{"s":"F23a","qn":"Q2.9"}]},{"id":"M22b1-1-2","ch":10,"sl":"","tp":"Serialization","t":"mcq","q":"The process of converting an object into a stream of bytes to store the object or transmit it to memory, a database, or a file is called:","o":["Serialization","Code Refactoring","Dependency Injection","Iteration"],"a":0,"e":"<b>Serialization</b> turns an object into bytes so it can be stored or sent (and deserialization rebuilds it). Official 2021 key: a. (Not on your slides.)","from":[{"s":"M22b1","qn":"Q1.2","pg":1},{"s":"M21a","qn":"Q1.2","pg":2}]},{"id":"M22b1-2b","ch":10,"sl":"","tp":"Doing responsibility","t":"mcq","q":"What type of object responsibility is data processing?","o":["Doing responsibility","Knowing responsibility","Delegation responsibility","Initiation responsibility"],"a":0,"e":"<b>Doing</b> responsibilities are actions an object performs: creating objects, doing calculations/data processing, initiating actions in other objects. Knowing = data it holds and references to other objects. (Not on your slides.)","from":[{"s":"M22b1","qn":"Q2 b","pg":3},{"s":"M21b","qn":"Q1.2","pg":2}]},{"id":"Q22a-4","ch":10,"sl":"","tp":"SaaS example","t":"tf","q":"Zoom is a SaaS company.","a":0,"e":"Zoom delivers its software as a service: it runs on Zoom's servers and users access it over the Internet by subscription. (SaaS is not on your slides.)","from":[{"s":"Q22a","qn":"Q4"}]},{"id":"M22a-1-5","ch":10,"sl":"","tp":"Design pattern classifications","t":"mcq","q":"Which of the following is the correct list of classifications of design patterns?","o":["Creational, Structural and Behavioral patterns","Executional, Structural and Behavioral patterns","Creational, Executional and Behavioral patterns","None of the above"],"a":0,"e":"The Gang-of-Four groups patterns as <b>creational</b> (e.g. Singleton), <b>structural</b> (e.g. Adapter, Façade) and <b>behavioral</b> (e.g. Observer, Strategy). Official key: a.","from":[{"s":"M22a","qn":"Q1.5"}]},{"id":"M22a-3-2","ch":10,"sl":"","tp":"Observer — bank interest rate","t":"short","q":"A Bank-client system issues loans based on an interest rate. Currently all clients keep checking the interest rate by requesting the Bank server every 5 seconds, which is inefficient. Refine the design so clients are informed when the interest rate changes.<br><b>Which?</b> pattern and its intent · <b>Why?</b> how it addresses the problem · <b>How?</b> implementation and a class diagram for this specific case.","a":"<b>Which:</b> <b>Observer</b> — defines a one-to-many dependency so that when one object changes state, all its dependents are notified and updated automatically.<br><b>Why:</b> instead of clients polling every 5 seconds (active approach), the Bank pushes a notification only when the interest rate actually changes — no wasted requests, and Bank and clients stay loosely coupled.<br><b>How:</b><pre>«interface» Subject                 «interface» Observer\n+attach(o: Observer)                 +update(rate: double)\n+detach(o: Observer)                          ▲\n+notifyObservers()                            │ implements\n        ▲ implements                          │\n      Bank ─────────── observers 0..* ──────▶ Client\n  -interestRate: double                 -currentRate: double\n  +setInterestRate(r)  → notifyObservers()   +update(rate)\n  +getInterestRate()</pre>Clients call <code>bank.attach(this)</code> once; when <code>setInterestRate()</code> changes the rate, Bank calls <code>update(rate)</code> on every registered client.","e":"Official model answer: Observer pattern. (Observer is not one of the three patterns in your OOAD deck.)","from":[{"s":"M22a","qn":"Q3.2"}]},{"id":"F21a-2","ch":10,"sl":"","tp":"Strategy — universal decompressor","t":"short","q":"A professor is trying to open emailed homework that students compressed in various formats (zip, tar, jar, rar, etc.) on OSX. OSX has built-in support only for zip, so the professor has to install various command-line tools, which is cumbersome. Design a universal compression tool that can deal with various compression formats.<br><b>Which?</b> pattern + intent · <b>Why?</b> · <b>How?</b> class diagram for this case.","a":"<b>Which:</b> <b>Strategy</b> — defines a family of algorithms, encapsulates each one and makes them interchangeable.<br><b>Why:</b> we need different decompression behaviours; new formats may be added later, and we want to call a single <code>decompress()</code> method. Strategy gives one unified interface for all formats.<br><b>How:</b><pre>FileExplorer ──uses──▶ «interface» Strategy\n  (context)              +decompress(file)\n                             ▲ implements\n              ┌──────────────┼──────────────┐\n            Zip             Rar             Tar   (Jar, …)\n       +decompress()   +decompress()   +decompress()</pre>","e":"Official model answer (Strategy is not one of the three patterns in your OOAD deck).","from":[{"s":"F21a","qn":"Q2","pg":4}]},{"id":"M21a-1-4","ch":10,"sl":"","tp":"Prioritizing use cases","t":"mcq","q":"To prioritize the work on use cases we use:","o":["Class diagram","Activity diagram","Traceability matrix","System sequence diagram"],"a":2,"e":"A traceability matrix links requirements to use cases (with priorities), showing which use cases cover the most important requirements. Official key: c.","from":[{"s":"M21a","qn":"Q1.4","pg":2}]},{"id":"M21a-2-3","ch":10,"sl":"","tp":"True / False","t":"tf","q":"In TDD, we write white-box tests before writing the code.","a":1,"e":"TDD writes unit tests before the code, but they are written against the required behaviour (the code doesn't exist yet), so they are not white-box tests. Official key: F.","from":[{"s":"M21a","qn":"Q2.3","pg":3}]},{"id":"Q21-1a","ch":10,"sl":"","tp":"SaaS","t":"short","q":"What does \"SaaS\" stand for? What does it mean?","a":"<b>Software as a Service</b> — the software is hosted by a provider and delivered to users over the Internet (usually through a browser, by subscription) instead of being installed on their own computers.","e":"Quiz 1 model answer. (Not on your slides.)","from":[{"s":"Q21","qn":"Quiz 1 (sec 372) Q1"}]},{"id":"Q21-1f","ch":10,"sl":"","tp":"SaaS advantage","t":"mcq","q":"An advantage of using SaaS is:","o":["Safety of data storage","Higher privacy of individual's data","Most suitable for critical systems","All of the above"],"a":0,"e":"The provider stores and backs up the data professionally (safe storage). Privacy is actually a <i>concern</i> with SaaS (data sits with a third party), and critical systems usually avoid it. Quiz 1 model answer: a.","from":[{"s":"Q21","qn":"Quiz 1 (sec 373) Q2b"}]},{"id":"Q21-1g","ch":10,"sl":"","tp":"P&amp;D","t":"short","q":"What does \"P&amp;D\" stand for? What does it mean?","a":"<b>Plan and Document</b> — a heavyweight process (e.g. waterfall, spiral) where the project is planned up front and every phase produces extensive documentation, as opposed to agile.","e":"Quiz 1 model answer.","from":[{"s":"Q21","qn":"Quiz 1 (sec 371) Q1"}]},{"id":"Q21-2b","ch":10,"sl":"","tp":"TDD green phase","t":"mcq","q":"In TDD, the \"Green\" phase is about:","o":["How to improve the existing code","How to make your test fail","How to make your test pass","What to develop"],"a":2,"e":"Red = write a failing test; <b>Green = write just enough code to make the test pass</b>; Refactor = improve the code.","from":[{"s":"Q21","qn":"Quiz 2 (sec 371) Q1b"}]},{"id":"Q21-2f","ch":10,"sl":"","tp":"TDD circle of life","t":"short","q":"Draw the TDD circle of life.","a":"<pre>   ┌──────────────► RED ───────────────┐\n   │      write a failing test          │\n   │                                    ▼\nREFACTOR ◄──────────────────────── GREEN\n clean up the code          write just enough code\n (tests still pass)          to make the test pass</pre>Repeat the cycle for every small piece of functionality.","e":"TDD (not on your slide decks).","from":[{"s":"Q21","qn":"Quiz 2 (sec 372) Q2"}]},{"id":"Q21-3c","ch":10,"sl":"","tp":"Types of object responsibilities","t":"short","q":"List two types of an object's responsibilities.","a":"<b>Knowing</b> responsibility and <b>Doing</b> responsibility.","e":"Quiz 3 model answer. (Not on your slides.)","from":[{"s":"Q21","qn":"Quiz 3 (sec 372) Q1"}]}]};
